COLLDATA("asabahur","ur",[[8481,"§۹۸۷۰ ۔ ابوراشد الازدی(1)\nعبدالرحمن بن عبید ہیں، ناموں میں ذکر ہو چکا ہے۔","",{"fn":"(1) اسد الغابہ (۵۸۶۶) استیعاب (۲۹۸۷) تجرید (۱۶۴/۲)"}],[8482,"§۹۸۷۱ ۔ ابوراشد (دوسرے)\nابوملیکہ میں تذکرہ ہونا ہے۔"],[8483,"§۹۸۷۲ ۔ ابورافع القبطی(1) (مولیٰ رسول اللہ صلی اللہ علیہ وسلم)\nان کا نام: ابراہیم، اسلم، سنان، یسار، صالح، عبدالرحمن، قزمان، یزید، ثابت اور ہرمز بتایا جاتا ہے۔ ابن عبدالبر فرماتے ہیں: ان کا نام اسلم زیادہ مشہور ہے۔ یحییٰ بن معین کا قول ہے: ان کا نام ابراہیم ہے۔ یہی قول مصعب الزبیری کا ہے۔ ان کا لقب بُرَیہ ہے جو ابراہیم کی تصغیر ہے۔ ابن شاہین نے بحوالہ ابوداؤد نقل کیا ہے کہ ان کا نام قزمان تھا، بعد میں ابراہیم رکھا گیا۔ ایک قول ہے: اسلم ہے۔ ابن حبان نے یہ اضافہ نقل کیا ہے کہ یسار اور ہرمز بھی بتایا جاتا ہے۔ ایک قول ہے: یہ عباس بن عبدالمطلب کے غلام تھے، انہوں نے نبی صلی اللہ علیہ وسلم کو ہبہ کر دیا، آپ نے انہیں اس وقت آزاد کر دیا تھا جب انہوں نے آپ کو عباس بن عبدالمطلب کے اسلام لانے کی خوشخبری سنائی۔ محفوظ تو یہ ہے کہ وہ اسلم ہیں جب انہوں نے عباس رضی اللہ عنہ کو یہ خوشخبری دی کہ نبی صلی اللہ علیہ وسلم کو خیبر والوں پر فتح ہوئی ہے۔ جس کا ایک واقعہ ہے وہ بدر سے پہلے اسلام لے آئے تھے، لیکن اس میں شرکت نہ کر سکے۔ البتہ احد اور بعد کے معرکوں میں شریک رہے۔ نبی صلی اللہ علیہ وسلم اور عبداللہ بن مسعود رضی اللہ عنہ سے روایت کرتے ہیں ان سے ان کی اولاد میں سے رافع، حسن، عبیداللہ اور مغیرہ روایت کرتے ہیں اور پوتوں میں سے حسن، صالح، عبیداللہ جو علی بن ابی رافع کی اولاد ہے۔ فضل بن عبیداللہ بن ابی رافع، ابوسعید المقبری، سلیمان بن یسار، عطاء بن یسار، عمرو بن شرید، ابوغطفان بن ظریف، سعید بن ابی سعید مولیٰ حزم، حصین، داؤد کے والد اور شرحبیل بن سعد وغیرہ۔ امام واقدی رحمہ اللہ کا قول ہے کہ ابورافع مدینہ میں سیدنا عثمان رضی اللہ عنہ سے کچھ مدت پہلے یا بعد میں فوت ہوئے۔ ابن حبان کا قول ہے: خلافت علی بن ابی طالب میں فوت ہوئے۔","",{"fn":"(1) اسد الغابہ (۵۸۶۷) تجرید (۱۶۴/۲)"}],[8484,"§۹۸۷۳ ۔ ابورافع انصاری\nابوداؤد میں مخابرہ کی حدیث میں ان کا ذکر آتا ہے، جو بطریق مجاہد بواسطہ ابن رافع بن خدیج بحوالہ ان کے والد مروی ہے۔ فرمایا: ہمارے پاس ابورافع آئے... پھر وہ حدیث ذکر کی۔ احتمال ہے کہ یہ بعد والے ہوں۔"],[8485,"§۹۸۷۴ ۔ ابورافع ظہیر بن رافع بن خدیج\nناموں میں ذکر ہو چکا ہے۔"],[8486,"§۹۸۷۵ ۔ ابورافع الحکم بن عمرو الغفاری\nناموں میں ذکر ہو چکا ہے۔"],[8487,"§۹۸۷۶ ۔ ابورافع الغفاری\nبقی بن مخلد نے ان کی ایک حدیث نقل کی ہے، احتمال ہے کہ پہلے والے ہوں۔"],[8488,"§۹۸۷۷ ۔ ابورافع\nمولا نبی صلی اللہ علیہ وسلم دوسرے ہیں۔ قبطی نہیں۔ مصعب الزبیری نے ان کا ذکر کیا ہے کہ ابورافع، ابواحیحہ سعید بن عاص بن امیہ کے غلام تھے، تو ان کی اولاد میں سے سوائے خالد بن سعید کے سب نے اپنا حصہ آزاد کر دیا۔ انہوں نے اپنا حصہ نبی صلی اللہ علیہ وسلم کو سونپ دیا، آپ نے انہیں آزاد کر دیا۔ وہ کہا کرتے تھے: میں رسول اللہ صلی اللہ علیہ وسلم کا مولا (آزاد کردہ غلام) ہوں۔ امیر معاویہ رضی اللہ عنہ کے دور حکومت میں جب عمرو بن سعید بن عاص بن امیہ مدینہ کا حاکم بنا، اس نے ابورافع رضی اللہ عنہ کے بیٹے کو بلایا پوچھا تم کس کے مولا ہو؟ کہا: رسول اللہ صلی اللہ علیہ وسلم کا، تو عمرو بن سعید نے اسے سو کوڑے مارے اور پھر پوچھا: تم کس کے مولا ہو؟ اس نے کہا: رسول اللہ صلی اللہ علیہ وسلم کا۔ پھر سو کوڑے لگائے۔ یہاں تک کہ پانچ سو کوڑے لگائے۔ مبرد نے \"الکامل\" میں ذکر کیا ہے، اس کا تقاضا ہے کہ یہ وہ ابورافع ہیں جن کا ذکر ہو چکا ہے۔ ابن عبدالبر نے اسی کو اختیار کیا ہے اور مذکورہ قصہ ابورافع قبطی کے حالات میں لکھا ہے۔ جو عبداللہ کاتب علی رضی اللہ عنہ کے والد ہیں۔ جبکہ یہ بالکل غلط ہے، اس واسطے کہ وہ ابورافع جو عبیداللہ کے والد ہیں وہ تو عباس بن عبدالمطلب رضی اللہ عنہ کے غلام تھے، جنہیں آپ صلی اللہ علیہ وسلم نے آزاد کر دیا تھا۔ ابوعمر فرماتے ہیں: نقلا یہ قصہ ثابت نہیں کیونکہ اس میں اضطراب بہت زیادہ ہے۔ عمرو بن دینار، جریر بن ابی حازم اور ایوب کی روایت ہے کہ جس نے ابورافع میں سے اپنا حصہ روک لیا تھا وہ صرف خالد ہی ہیں۔ ایک اور روایت میں ہے کہ ماسوائے ایک حصہ کے وہ ابواحیجہ کے تھے، تو ان کی اولاد نے اپنا حصہ آزاد کر دیا۔ آپ صلی اللہ علیہ وسلم نے وہ ایک حصہ خرید کر انہیں آزاد کر دیا۔ میں کہتا ہوں: ابوسعید بن الاعرابی نے یہ قصہ اپنی معجم میں بطریق جریر بن حازم بواسطہ حماد بن موسیٰ جن کا تعلق مدینہ سے ہے نقل کیا ہے کہ عثمان بن الیسع بن ابی رافع نے ان سے بیان کیا کہ میرے دادا ابواحیجہ نے میراث چھوڑی بدر کے روز اپنی اولاد کے ساتھ روانہ ہوئے۔ ان میں سے تین سعید، عبیداللہ اور عاص نے تو اپنا حصہ آزاد کر دیا یہ تینوں بدر کے روز کفر پر مرے۔ تو سعید کی اولاد میں سے سوائے خالد بن سعید کے سب نے انہیں آزاد کر دیا۔ کیونکہ خالد کو ابواحیجہ کی لونڈی کی وجہ سے ابورافع پر غصہ تھا وہ اس سے شادی کرنا چاہتے تھے۔ خالد نے انہیں روکا لیکن انہوں نے بات نہ مانی، اور ان پر حملہ کر دیا۔ جب ابورافع مسلمان ہو گئے، ہجرت کرلی تو رسول اللہ صلی اللہ علیہ وسلم سے خالد کے بارے میں بات کی، انہوں نے آزاد کرنے، ہبہ کرنے یا فروخت کرنے سے انکار کیا۔ بعد میں انہیں ندامت ہوئی۔ اور نبی صلی اللہ علیہ وسلم کو ہبہ کر دیا۔ آپ صلی اللہ علیہ وسلم نے اپنا حصہ آزاد کر دیا، ابورافع کہا کرتے تھے، میں رسول اللہ صلی اللہ علیہ وسلم کا مولا ہوں۔ جب عمرو بن سعید بن عاص مدینہ کا والی بنا تو بہی بن ابی رافع کو بلا بھیجا، پوچھا تم کس کے مولا ہو؟ اس نے کہا: رسول اللہ صلی اللہ علیہ وسلم کا تو اس نے سو کوڑے لگائے، پھر پوچھا: تم کس کے مولا ہو؟ تو یہی جواب دیا۔ یہاں تک کہ پانچ سو وڑے لگائے جب جان کا خوف ہوا تو کہہ دیا، میں تمہارا مولا ہوں۔ جب عبدالملک بن مروان نے عمرو بن سعید کو قتل کر دیا تو بہی نے اس کی مدح کی اور عمرو بن سعید کی ہجو کی۔ اس سے معلوم ہوا اس واقعہ والے ابورافع عبداللہ کے والد کے علاوہ کوئی شخص ہیں اس لیے کہ ان کی اولاد میں بھی نامی کوئی نہیں۔"],[8489,"§۹۸۷۸ ۔ ابورائطہ(1)\nابوریطہ میں تذکرہ ہوتا ہے۔","",{"fn":"(1) اسد الغابہ (۵۸۶۸) تجرید (۱۶۵/۲)"}],[8490,"§۹۸۷۹ ۔ ابوالرباب\nکتاب النساء الرباب میں ذکر ہوگا۔"],[8491,"§۹۸۸۰ ۔ ابوالربذاء\nبقول بعض میم اور دال سے تذکرہ ہوتا ہے۔"],[8492,"§۹۸۸۱ ۔ ابوربعی\nعمرو بن الامتم تمیمی، تذکرہ ہو چکا ہے۔"],[8493,"§۹۸۸۲ ۔ ابوالربیع عبداللہ بن ثابت انصاری\nحدیث جابر بن عتیک میں ان کا ذکر ہو چکا ہے۔"],[8494,"§۹۸۸۳ ۔ ابوربیعہ(1) (بے نسبت)\nابوموسیٰ کا قول ہے: ابوزکریا بن مندہ نے اپنے دادا کی کتاب کے استدراک میں ان کا ذکر کیا ہے اور ان کی کوئی حدیث نقل نہیں کی۔","",{"fn":"(1) اسد الغابہ (۵۸۷۱) تجرید (۱۶۵/۲)"}],[8495,"§۹۸۸۴ ۔ ابورحیمہ(1) (بے نسبت)\nحاء سے یا خاء سے۔ ابونعیم نے ان کا ذکر کیا اور بطریق روح بن جناح، عطاء بن نافع بواسطہ حسن بحوالہ ابورحیمہ روایت نقل کی ہے کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو سینگی لگائی تو آپ نے مجھے ایک درہم دیا۔(2) اس کی سند میں ضعف ہے۔","",{"fn":"(1) اسد الغابہ (۵۸۷۳) تجرید (۱۶۵/۲)\n(2) جامع المسانید والسنن (۴۰/۱۱۴) اسد الغابہ (۴۴۲/۴)"}],[8496,"§۹۸۸۵ ۔ ابورداد اللیثی(1)\nبقول ابواحمد الحاکم اور ابن حبان، انہیں شرف صحابیت حاصل ہے ان کی حدیث زہری نے بواسطہ ابوسلمہ بن عبدالرحمن بحوالہ ان کے نبی صلی اللہ علیہ وسلم سے نقل کی ہے۔ اسی سند کی حدیث ابوداؤد(2) نے نقل کی ہے جس کے الفاظ یہ ہیں کہ رداد نے بحوالہ عبدالرحمن بن عوف انہیں بتایا کہ انہوں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: اللہ تعالیٰ نے فرمایا: \"میں رحمن ہوں میں نے رحم (رشتہ داری) کو پیدا کیا۔\" ایسا ہی ابن حبان نے ثقات التابعین میں \"رداد اللیثی\" لکھا ہے۔ پھر بطریق معمر بواسطہ زہری، ابوسلمہ سے، رداد سے بحوالہ عبدالرحمن بن عوف بیان کی، فرماتے ہیں: میرا گمان نہیں کہ معمر نے اسے یاد رکھا ہو۔ میں کہتا ہوں: ابن عیینہ نے زہری سے ترمذی میں ان کی متابعت کی ہے۔ امام بخاری رحمہ اللہ فرماتے ہیں: حدیث معمر میں غلطی ہے۔ امام بخاری رحمہ اللہ نے \"الادب المفرد\" میں بطریق ابن ابی عتیق، زہری، ابوسلمہ محمد بن عبدالرحمن، بواسطہ ابورداد اللیثی بحوالہ نبی صلی اللہ علیہ وسلم روایت کی ہے۔ شعیب نے بحوالہ زہری اس کی متابعت کی ہے۔ ابوحاتم رازی لکھتے ہیں: اس سلسلہ میں ابوسلمہ بن عبدالرحمن بن عبدالرحمن کی روایت مشہور ہے۔ اس میں ابورداد کا قصہ ہے وہ یہ کہ ابورداد بیمار ہوئے تو عبدالرحمن بن عوف ان کی عیادت کرنے گئے، آپ صلی اللہ علیہ وسلم نے فرمایا: لوگوں میں سے بہترین اور صلہ رحمی کرنے والا ابومحمد ہے۔ تو انہوں نے کہا: عبدالرحمن... پھر حدیث ذکر کی۔","",{"fn":"(1) اسد الغابہ (۵۸۷۴) تجرید (۱۶۵/۲)\n(2) ابوداؤد کتاب الزکوٰۃ باب صلۃ الرحم (۱۶۹۵، ۱۶۹۶)"}],[8497,"§۹۸۸۶ ۔ ابوالردین(1) (بے نسبت)\nبغوی نے ان کا ذکر کیا ہے لیکن ان کی کوئی حدیث ذکر نہیں کی۔ ابن مندہ کا قول ہے۔ صحابہ رضی اللہ عنہم میں ان کا ذکر آتا ہے۔ لیکن ان کا صحابی ہونا ثابت نہیں۔ ان کی حدیث حارث بن ابی اسامہ اور طبرانی نے مسند شامیین میں بطریق عبدالحمید بن عبدالرحمن بحوالہ ابوالردین نقل کی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جو قوم بھی اکٹھے ہو کر اللہ تعالیٰ کی کتاب پڑھتی اور ایک دوسرے کو سکھاتی ہے تو وہ اللہ کے مہمان ہیں اور فراغت تک فرشتے انہیں گھیر لیتے ہیں۔\"(2)","",{"fn":"(1) اسد الغابہ (۵۸۷۵) تجرید (۱۶۵/۲)\n(2) المعجم الکبیر (۸۴۴/۲۲) مجمع الزوائد (۱۲۲/۱) جامع المسانید (۴۲/۱۴) اسد الغابہ (۴۴۳/۴)"}],[8498,"§۹۸۸۷ ۔ ابورزین(1) (بے نسبت)\nبقول ابوعمر: ان سے صرف ان کا بیٹا عبداللہ روایت کرتا ہے یہ دونوں نامعلوم شخص ہیں۔ شکار کے چھپ جانے کے بارے میں ان کی حدیث آتی ہے۔","",{"fn":"(1) اسد الغابہ (۵۸۷۷) تجرید (۱۶۵/۲)"}],[8499,"§۹۸۸۸ ۔ ابورزین(2) (دوسرے ہیں)(1)\nبقول بعض: اہل صفہ میں شامل ہیں، خلعیات میں ہم نے بطریق عمرو بن بکر سکسکی، محمد بن زید، ابوسلمہ بن عبدالرحمن، وہ بحوالہ اپنے والد روایت کی ہے کہ نبی صلی اللہ علیہ وسلم نے اہل صفہ میں سے ایک شخص سے کہا: جن کی کنیت ابورزین تھی۔ ابورزین! جب تم خلوت میں ہوا کرو تو اللہ تعالیٰ کے ذکر میں اپنی زبان کو حرکت دینا کیونکہ جب تک تم اپنے رب کا ذکر کرتے رہے تو نماز میں شامل لکھے جاؤ گے۔ ابورزین! جب لوگ جہاد کے لیے جانے لگیں اور تم چاہو کہ تمہیں بھی انہی جیسا اجر ملے تو مسجد سے جدا نہ ہونا۔ وہاں بغیر اجرت اذان دیتے رہنا۔ اس کی سند ضعیف ہے۔ ان کا ذکر ایک اور حدیث میں بھی آتا ہے جو عقیلی نے \"الضعفاء\" میں محمد بن اشعث(3) جو ایک مجہول راوی ہے کے حالات میں نقل کی ہے جو اس کے طریق سے بواسطہ ابوسلمہ بحوالہ ابوہریرہ رضی اللہ عنہ مروی ہے کہ ابورزین نے عرض کی: اللہ کے رسول! میرے راستہ میں قبرستان آتا ہے تو کیا کوئی ایسی بات ہے جو میں وہاں سے گزرتے ہوئے ان سے کہوں؟ آپ نے فرمایا: یوں کہو! السلام علیکم یا اہل القبور من المسلمین انتم لنا سلف و نحن لکم تبع و انا ان شاء اللہ بکم لاحقون۔ تو ابورزین نے کہا: اللہ کے رسول! کیا وہ سنتے ہیں؟ آپ نے فرمایا: \"سنتے تو ہیں لیکن جواب نہیں دے سکتے۔ ابورزین! کیا تم خوش نہیں کہ ان کی تعداد میں فرشتے تمہیں جواب دیں؟\" عقیلی فرماتے ہیں: یہ روایت اسی سند سے مشہور ہے جو کتابوں میں (اور حفاظ کے سینوں میں) محفوظ نہیں۔ مردوں کو سلام کی اصل روایت اس کے علاوہ صحیح سند سے نقل کی جاتی ہے۔","",{"fn":"(1) اسد الغابہ (۵۸۷۹) تجرید (۱۶۵/۲)\n(2) حلیۃ الاولیاء (۳۶۶/۱) اسد الغابہ (۴۴۴/۴)\n(3) الضعفاء (۱۹/۴)"}],[8500,"§۹۸۸۹ ۔ ابورزین العقیلی(1)\nلقیط بن عامر ناموں میں ذکر ہوا ہے۔","",{"fn":"(1) اسد الغابہ (۵۸۷۸) استیعاب (۲۹۹۳) تجرید (۱۶۵/۲)"}],[8501,"§۹۸۹۰ ۔ ابورعلہ القشیری\nخواتین کے حصہ میں ام رعلہ میں تذکرہ ہوگا۔"],[8502,"§۹۸۹۱ ۔ ابورفاعہ العدوی(1)\nتمیم بن اسد۔ امام بخاری رحمہ اللہ نے یہی نام لیا ہے کسی نے ابن اسید کسی نے اسید (تصغیر) کسی نے کہا: ان کا نام عبداللہ بن حارث ہے، یہی خلیفہ وغیرہ کا قول ہے۔ یہ نبی صلی اللہ علیہ وسلم سے اور ان سے حمید بن ہلال، وصلہ بن اشیم جو دونوں عدوی اور بصری ہیں روایت کرتے ہیں۔ صحیح مسلم میں حدیث حمید سے ان کی حدیث آتی ہے، فرمایا: میں رسول اللہ صلی اللہ علیہ وسلم کے پاس آیا پھر قصہ ذکر کیا کہ آپ ان کی خاطر منبر سے اترے اور گفتگو کی، آپ کی عادت تھی جب کوئی مسافر شخص دین کی کوئی بات پوچھتا تو آپ منبر سے اتر آتے، چنانچہ آپ لوہے کے پایوں والی ایک کرسی پر تشریف فرما ہوئے۔ اور مجھے وہ چیزیں سکھانے لگے جو اللہ تعالیٰ نے آپ کو سکھائی تھیں۔ (حدیث)(2) الحاکم کی مصعب زبیری کے طریق سے روایت ہے کہ ابورفاعہ عدوی صحابی ہیں ان کا نام عبداللہ بن حارث بن اسید بن عدی بن مالک بن تمیم بن الدول بن حسل بن عدی بن عبد مناۃ ہے عبدالرحمن بن سمرہ کی معیت میں بجستان کی جنگ میں شرکت کی رات کی آخری گھڑی کھڑے ہوئے گرنے کی وجہ سے فوت ہو گئے۔ ابن عبدالبر نے لکھا ہے کہ بصرہ کے فضلاء (فضیلت والے) صحابہ رضی اللہ عنہم میں سے تھے۔ کابل میں ۴۴ھ میں شہید ہوئے۔ خلیفہ کا قول ہے کہ ابن عامر نے ۴۴ھ میں کابل فتح کیا جس میں ابوقتادہ عدوی بقول بعض: اس میں شہید ہونے والے ابورفاعہ عدوی تھے۔ عدی بن غنام کا قول ہے: ابورفاعہ صحابی رسول صلی اللہ علیہ وسلم اور اسود بن کلثوم کی قبر بیہق میں ہے۔ یہی قول مسلم کا ہے کہ ابورفاعہ کی قبر بیہق میں ہے۔","",{"fn":"(1) اسد الغابہ (۵۸۸۰) تجرید (۱۶۵/۲)\n(2) مسلم کتاب الجمعہ باب حدیث التعلیم فی الخطبۃ (۲۰۲۲) نسائی کتاب الزینۃ باب الجلوس علی الکراسی (۵۳۹۲) مسند احمد (۴۴/۱۴)"}],[8503,"§۹۸۹۲ ۔ ابورقاد\nنبی صلی اللہ علیہ وسلم نے اس سے زید بن ثابت رضی اللہ عنہ کو مخاطب کیا تھا۔ زید بن اشتہ کے حالات میں بطریق واقدی یہ بات بیان ہو چکی ہے۔"],[8504,"§۹۸۹۳ ۔ ابورقیہ (تصغیر ہے)\nتمیم بن اوس داری، ناموں میں ذکر ہوا ہے۔"],[8505,"§۹۸۹۴ ۔ ابورمثہ البلوی(1)\nبقول ترمذی: انہیں شرف صحابیت حاصل ہے۔ مصر کے رہائشی تھے اور افریقا میں فوت ہوئے۔ انہوں نے وصیت کی تھی کہ میری قبر زمین سے برابر کر دی جائے۔ اہل مصر سے ان کی حدیث منقول ہے۔ اسی طرح ابوعمر نے ان کا تذکرہ کیا ہے، ان میں اور بعد والے ابورمثہ تمیمی میں فرق کیا ہے، جبکہ المری نے ان سے اختلاف کرتے ہوئے لکھا ہے کہ بعد والے تیمی، بقول بعض بلوی ہیں۔","",{"fn":"(1) اسد الغابہ (۵۸۸۱) تجرید (۱۶۶/۲)"}],[8506,"§۹۸۹۵ ۔ ابورمثہ التیمی(1)\nاز تیم الرباب بقول بعض: التیمی، کا نام رفاعہ بن یثربی ہے۔ ایک قول ہے: یثربی بن عوف کسی نے یثربی بن رفاعہ کہا ہے اسی پر طبرانی کا اعتماد ہے ایک قول ہے: ان کا نام حیان ہے جس پر کئی لوگوں کا اعتماد ہے۔ بقول بعض: حبیب بن حیان، بقول بعض: حسحاس۔ نبی صلی اللہ علیہ وسلم سے روایت کرتے ہیں ان سے ایاد بن لقیط، ثابت بن منقذ روایت لیتے ہیں۔ تین اصحاب السنن نے ان کی روایت لی ہے۔ ابن خزیمہ، ابن حبان اور الحاکم نے ان کی حدیث کو صحیح لکھا ہے۔","",{"fn":"(1) اسد الغابہ (۵۸۸۲) استیعاب (۲۹۹۶) تجرید (۱۶۶/۲)"}],[8507,"§۹۸۹۶ ۔ ابورمداء البلوی(1)\nناموں میں تذکرہ ہو چکا ہے کہ ان کا نام یاسر ہے۔","",{"fn":"(1) اسد الغابہ (۵۸۸۳) استیعاب (۲۹۹۷) تجرید (۱۶۶/۲)"}],[8508,"§۹۸۹۷ ۔ ابورہم الغفاری(1)\nنام: کلثوم بن حصین بن خالد بن المعیر بن زید بن عمیس بن احمس بن غفار ہے، بقول بعض: ابن حصین بن عبید بن خلف بن حماس بن غفار غفاری۔ کنیت اور ناموں دونوں میں شہرت رکھتے ہیں۔ بیعت رضوان(2) میں شریک تھے۔ فتح مکہ کے موقعہ پر نبی علیہ السلام نے انہیں مدینہ میں اپنا نائب مقرر کیا تھا۔ یہی بات ابن اسحاق سے مغازی میں مروی ہے۔ انہوں نے غزوہ تبوک کی طویل حدیث نبی صلی اللہ علیہ وسلم سے روایت کی ہے۔ اسے بعض نے مختصراً نقل کیا ہے۔ ان سے ان کا بھتیجا اور مولا، ابوجازم تمار روایت کرتے ہیں۔ امام احمد اور بغوی وغیرہ نے بطریق معمر بحوالہ زہری روایت کی ہے کہ مجھے ابورہم کے بھتیجے نے بتایا کہ انہوں نے ابورہم کو فرماتے سنا: میں نے غزوہ تبوک میں نبی صلی اللہ علیہ وسلم کے ساتھ شرکت کی۔ پھر وہ(3) حدیث نقل کی۔ ابن سعد(4) لکھتے ہیں: نبی صلی اللہ علیہ وسلم نے انہیں اپنی قوم کو غزوہ تبوک کی تیاری کے لیے بھیجا۔(5) امام بخاری رحمہ اللہ کی الادب المفرد، صحیح ابن حبان، معجم طبرانی میں ان کی حدیث ہے۔ ابوعروبہ کا بیان ہے کہ اُحد میں ان کے سینہ کی ہڈی اور گردن میں تیر پیوست ہوا تھا۔ نبی صلی اللہ علیہ وسلم نے اس میں اپنا لعاب لگایا تو تندرست ہو گئے۔","",{"fn":"(1) اسد الغابہ (۵۸۹۳) استیعاب (۳۰۰۱) تجرید (۱۶۶/۲)\n(2) جامع المسانید (۴۴۸/۴)\n(3) مسند احمد (۳۴۹/۴)\n(4) الطبقات (۱۷۹/۴)\n(5) الطبقات (۳۴۹/۴) مجمع الزوائد (۳۴۲/۵)"}],[8509,"§۹۸۹۸ ۔ ابورہم بن قیس اشعری(1)\nبرادر ابوموسیٰ اشعری رضی اللہ عنہ ان کے بھائی ابوبردہ بن قیس کے سوانح میں ان کی حدیث گزر چکی ہے جو طاعون کے متعلق ہے اس کی سند صحیح ہے۔ میں نے تاریخ مظفری میں ابن قتیبہ کے حوالہ سے دیکھا ہے کہ ابورہم فتنوں میں جلدی کرتے تھے اور ان کے بھائی ابوموسیٰ ان سے روکتے تھے پھر ایک واقعہ ذکر کیا۔ ابن قتیبہ فرماتے ہیں: بقول بعض: یہ ابورہم مشہور نہیں۔ میں کہتا ہوں: شاید یہ وہی ہیں پھر مجھے مسند احمد میں بطریق قتادہ ابوموسیٰ کی سند کے دوران حسن کی روایت مل گئی کہ ابوموسیٰ رضی اللہ عنہ کا ابورہم نامی ایک بھائی تھے جو فتنوں میں جلدی کرتے تھے۔ ابوموسیٰ نے ان سے ایک حدیث بیان کی۔ جب دو مسلمان اپنی تلواریں لیے روبرو ہو جاتے ہیں اور ان سے ایک دوسرے کو قتل کر دے تو دونوں جہنم میں جائیں گے۔(2)","",{"fn":"(1) اسد الغابہ (۵۸۹۳) استیعاب (۲۹۹۸) تجرید (۱۶۷/۲)\n(2) نسائی کتاب التحریم باب تحریم القتل (۴۲۲۹) (۴۱۳۰) ابن ماجہ کتاب الفتن باب اذا التقی المسلمان بسیفیھما (۳۹۶۴) مسند احمد (۴۱۲/۴)"}],[8510,"§۹۸۹۹ ۔ ابورہم (دوسرے)(1)\nنام: مجدی بن قیس، تذکرہ ہو چکا ہے۔","",{"fn":"(1) اسد الغابہ (۵۸۹۴) تجرید (۱۶۷/۲)"}],[8511,"§۹۹۰۰ ۔ ابورہم الارحبی(1)\nناموں میں مطعم میں ان کا تذکرہ ہو چکا ہے، بغوی نے ان کا ذکر کیا ہے اور ابوعبید کے حوالہ سے نقل کیا ہے: ابورہم شاعر نے نبی صلی اللہ علیہ وسلم کی طرف ایک سو پانچ سال کی عمر میں ہجرت کی ان کا تعلق بنی اُڑکب سے تھا، جو ہمدان کے ہیں۔","",{"fn":"(1) اسد الغابہ (۵۸۹۰) تجرید (۱۶۷/۲)"}],[8512,"§۹۹۰۱ ۔ ابورہم(1)(2)\nبقول بعض: اسمعی۔ میرے نزدیک یہ احزاب کے علاوہ ہیں۔ ابن سعد(3) کا قول ہے: کوفہ کے رہنے والے تھے۔ شام جا بسے، صحابی ہیں۔ نہ ان کا نسب لکھا ہے اور نہ نام۔ ابن ابی خیثمہ کی روایت ہے کہ ابورہم صحابی رسول صلی اللہ علیہ وسلم سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جس نے اپنے امام (خلیفہ) کی بات نہ مانی اس کا اجر ضائع ہو گیا۔\" اسحاق بن راہویہ نے یہ روایت اپنی مسند میں بحوالہ بقیہ اور حسن بن سفیان نے بحوالہ اسحاق جبکہ دولابی نے بطریق ثور بن یزید یزید بن مرشد سے بحوالہ ابورہم نقل کی ہے، فرمایا: میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: \"جب تم میں سے کوئی سفر سے واپس آئے تو اپنے گھر والوں کے لیے ہدیہ لے کر جائے۔ اگر اور کچھ نہ ملے تو اپنے تھیلے میں پتھر ہی ڈال لے۔ یا ایندھن کا گٹھا لے جائے اس سے انہیں خوشی ہوگی۔\" ان تینوں احادیث سے ابورہم کے صحابی ہونے کا پتہ چلتا ہے، ان میں سے پہلی حدیث ابن ماجہ نے دوسری سند سے بواسطہ یزید بن ابی حبیب انہوں نے ابوالخیر سے بحوالہ ابورہم نقل کی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: سب سے افضل سفارش یہ ہے کہ تم نکاح کرانے میں سفارش کرو تا کہ دو افراد مل جائیں۔ اسی طرح طبرانی نے نقل کیا ہے البتہ متن میں یہ الفاظ زائد روایت کیے ہیں \"اور سب سے بڑا گناہ یہ ہے کہ کوئی کسی مسلمان کا مال ناجائز طور پر ہتھیا لے\"۔ (حدیث) اگر کسی راوی سے \"اسمعی\" کہنے میں غلطی نہ ہوئی ہو تو یہ صحابی ہیں انہیں سمعی کہا جاتا ہے یہ احزاب بن اسید نہیں ہیں کیونکہ انہیں صحابی ہونے کا شرف حاصل نہیں ہے۔ اور یہ ناممکن نہیں کہ ایک ہی کنیت اور نسبت دو آدمیوں کی واقع ہو جائے۔","",{"fn":"(1) الطبقات (۱۷۹/۵)\n(2) السنن الکبریٰ (۸۷/۹)\n(3) جامع المسانید (۵۸/۱۴) اسد الغابہ (۴۴۸/۴)"}],[8513,"§۹۹۰۲ ۔ ابورہیمہ(1) (تصغیر ہے) السمعی\nمستغفری اور بردگی نے ان کا ذکر کیا ہے اور ابوموسیٰ نے اپنے استدراک میں ان کا ذکر کیا ہے۔ ابن مندہ نے ابوخیلہ الہمی کے حالات میں ان کا ذکر کیا ہے جس کی تفصیل حرف نون میں آ رہی ہے۔ کیونکہ ابوموسیٰ نے بطریق ابن مندہ ان کا تذکرہ کیا ہے اور اس کا جواز پیش کیا ہے کہ وہ اس سے پہلے والی شخصیت ہے۔ اس کا احتمال ہے۔","",{"fn":"(1) اسد الغابہ (۵۸۹۶) تجرید (۱۶۷/۲)"}],[8514,"§۹۹۰۳ ۔ ابوالروم(1)\nبن عمیر بن ہاشم بن عبدالدار بن عبد مناف بن قصی العبدری، مصعب کے بھائی ہیں۔ بقول البلاذری: ان کا نام عبد مناف ہے، جب مسلمان ہوئے تو یہ نام چھوڑ دیا۔ سابقین اولین میں سے ہیں۔ حبشہ ہجرت کی، پھر وہاں سے واپس آ کر اُحد میں شریک ہوئے۔ ابن کلبی کا قول ہے: خیبر سے پہلے آکر اس میں شریک ہوئے۔ امام واقدی رحمہ اللہ فرماتے ہیں: ان کی ہجرت الی الحبشہ پر اتفاق نہیں۔ ہیم بن عدی وغیرہ نے اس کی نفی کی ہے۔","",{"fn":"(1) اسد الغابہ (۵۸۸۵) تجرید (۱۶۶/۲)"}],[8515,"§۹۹۰۴ ۔ ابورومی\nیعقوب بن سفیان نے ان کا ذکر کیا ہے اور بحوالہ ابن عباس رضی اللہ عنہما روایت کی ہے کہ ابورومی سب سے برے (شریر) شخص تھے، آپ صلی اللہ علیہ وسلم نے فرما دیا: اگر مجھے ابورومی نظر آ گیا تو میں اس کی گردن اتار دوں گا۔ صبح وہ خود ہی نبی صلی اللہ علیہ وسلم کی طرف آنے لگے، وہ آپ علیہ السلام کے صحابہ کے ساتھ تھے، ان سے باتیں کر رہے تھے۔ آپ نے جب دور سے انہیں دیکھا تو فرمایا: ابورومی خوش آمدید! اور انہیں جگہ دینے لگے۔ آپ نے ان سے فرمایا: \"ابورومی! گزشتہ رات تم نے کیا عمل کیا ہے؟\" وہ عرض کرنے لگے: \"اللہ کے رسول! میں ایسا کیا عمل کر سکتا ہوں حالانکہ میں تو سب سے شریر آدمی ہوں؟\"(1) آپ صلی اللہ علیہ وسلم نے فرمایا: \"خوش ہو! کیونکہ اللہ تعالیٰ نے تمہارے عمل کو جنت تک کا ذریعہ بنا دیا ہے، اس واسطے کہ اللہ تعالیٰ جو چاہتا ہے مٹاتا ہے اور جو چاہتا ہے برقرار رکھتا ہے۔\"(2)","",{"fn":"(1) اسد الغابہ (۵۸۸۶) تجرید (۱۶۶/۲)\n(2) الدر المنثور (۶۷/۴)"}],[8516,"§۹۹۰۵ ۔ ابورویحہ الثمالی(1)\nان کا نام ربیعہ بن السکن ہے، ناموں میں تذکرہ ہو چکا ہے۔ ابوموسیٰ کا قول ہے: ابورویحہ فرعی ثم سے تعلق رکھتے ہیں۔ فرمایا: میں نبی صلی اللہ علیہ وسلم کے پاس آیا آپ لوگوں میں بھائی چارہ قائم فرما رہے تھے یہی قول مستغفری کا ہے۔","",{"fn":"(1) اسد الغابہ (۵۸۸۸) تجرید (۱۶۶/۲)"}],[8517,"§۹۹۰۶ ۔ ابورویحہ الخثعمی(1)\nنبی صلی اللہ علیہ وسلم نے ان میں اور بلال مؤذن کے درمیان بھائی چارہ قائم فرمایا تھا۔ بقول بعض: ان کا نام عبداللہ بن عبدالرحمن خثعمی ہے۔ ابورویحہ نے نبی صلی اللہ علیہ وسلم سے کوئی بھی مسند حدیث نہیں نقل کی ہے۔ پھر انہوں نے بطریق محمد بن اسحاق یہ روایت نقل کی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے اپنے صحابہ رضی اللہ عنہم میں بھائی چارہ قائم کیا۔ تو بلال مولا ابوبکر مؤذن رسول اللہ صلی اللہ علیہ وسلم اور ابورویحہ عبداللہ بن عبدالرحمن خثعمی دونوں بھائی بنے۔ جب سیدنا عمر رضی اللہ عنہ نے شام میں رجسٹریشن کی تو سیدنا بلال رضی اللہ عنہ سے فرمایا: آپ کی رجسٹریشن کس کے ساتھ کروں؟ انہوں نے کہا: ابورویحہ کے ساتھ میں ان سے مذکورہ بھائی چارہ نہیں توڑ سکتا۔ چنانچہ آپ نے بلال رضی اللہ عنہ کی وجہ سے انہیں ان کے ساتھ ملا دیا اور حبشہ کا دیوان (رجسٹر) خثعم کے ساتھ شامل کر دیا۔ آج تک وہ شام میں خثعم کے ساتھ ہیں۔ ابواحمد الحاکم کا قول ہے: انہیں شرف صحابیت حاصل ہے۔ مجھے ان کے نام کا پتہ نہیں۔ ابوموسیٰ فرماتے ہیں: ابوعبداللہ بن مندہ نے \"الکنیٰ\" میں ان کا ذکر کیا ہے لیکن ہمارے پاس ان کی کتاب میں صحابہ رضی اللہ عنہم میں ان کا ذکر نہیں۔ پھر بطریق ابواحمد الحاکم بحوالہ ابوالدرداء روایت کی ہے کہ جب عمر بیت المقدس کی فتح سے واپس آئے اور جابیہ جانے لگے تو سیدنا بلال رضی اللہ عنہ نے ان سے درخواست کی مجھے شام ٹھہرا دیں، چنانچہ آپ نے ایسا ہی کیا۔ اور سیدنا بلال بولے: ابورویحہ میرا بھائی ہے۔ نبی صلی اللہ علیہ وسلم نے ہم میں بھائی چارہ قائم فرمایا تھا۔ پھر وہ دونوں بنی خولان کے ایک گھر والے کے پاس فروکش ہوئے۔ پھر وہ اور ان کا بھائی بنی خولان کے قبیلہ کے ہاں گئے ان سے کہا: ہم تم سے رشتہ لینے آئے ہیں۔ ہم دونوں کافر تھے، اللہ تعالیٰ نے ہمیں راہ ہدایت نصیب فرمائی۔ غلام تھے، اللہ تعالیٰ نے آزادی عطا فرمائی۔ نادار و فقیر تھے، اللہ تعالیٰ نے بے نیاز کر دیا۔ اب اگر تم لوگ ہماری شادیاں کر دو تو اللہ کا شکر ہے اور اگر ہمیں واپس بھیج دو تو اللہ کے سوا نہ کوئی طاقت ہے اور نہ کوئی قوت۔ چنانچہ ان لوگوں نے ان دونوں کو رشتے دے دیئے۔ ابوعمر لکھتے ہیں: ابورویحہ سے مروی ہے کہ میں نبی صلی اللہ علیہ وسلم کے پاس آیا تو آپ صلی اللہ علیہ وسلم نے مجھے پرچم بنا کر دیا اور فرمایا: \"جاؤ لوگوں میں اعلان کرو! جو ابورویحہ کے جھنڈے تلے آ جائے گا اسے امن ہے\"۔(2) میں کہتا ہوں: یہ بات ربیعہ بن السکن کے حالات میں ہو چکی ہے۔ ابوموسیٰ نے فزعی اور خثعمی میں فرق کیا ہے۔ ادھر ابن الاثیر(3) ان کا تعاقب کرتے ہوئے لکھتے ہیں: فزع خثعم کا بطن ہے۔ جو فزع بن شہران بن عفرس بن حلف بن افل۔ یہی خثعم ہیں ان سے یہ بات رہ گئی کہ پہلے شخص کا نام ربیعہ بن السکن ہے اور سیدنا بلال رضی اللہ عنہ کے بھائی کا نام عبداللہ بن عبدالرحمن ہے۔ میں ان کے حالات میں ذکر کر چکا ہوں کہ یہ ان کے علاوہ ہیں جن کے ساتھ نبی صلی اللہ علیہ وسلم نے سیدنا بلال رضی اللہ عنہ کا بھائی چارہ قائم فرمایا تھا۔ ابن عساکر نے فزعی کی حدیث خثعمی کے سوانح میں نقل کی ہے، شاید وہ دونوں ان کے نزدیک ایک شخصیت ہیں۔ واللہ اعلم!","",{"fn":"(1) اسد الغابہ (۵۸۸۷) تجرید (۱۶۶/۲)\n(2) الاسماء والکنیٰ للدولابی (۱۹۲/۱) اسد الغابہ (۴۴۷/۴)\n(3) اسد الغابہ (۴۴۷/۴)"}],[8518,"§۹۹۰۷ ۔ ابورناب\nذال میں ذکر ہوا ہے، بقول بعض ابوذئاب ہی ابورناب ہیں۔"],[8519,"§۹۹۰۸ ۔ ابوریحانہ الازدی(1)\nبقول بعض: انصاری ان کا نام شمعون تھا، ناموں میں حرف شین میں تذکرہ ہو چکا ہے۔","",{"fn":"(1) استیعاب (۳۰۰۴) تجرید (۱۶۷/۲)"}],[8520,"§۹۹۰۹ ۔ ابوریحانہ القرشی(1)\nناموں میں عقبہ بن مالک الجہنی کے حالات میں ان کی حدیث گزر چکی ہے۔","",{"fn":"(1) اسد الغابہ (۵۸۹۸) تجرید (۱۶۷/۲)"}],[8521,"§۹۹۱۰ ۔ ابوریطہ المذحجی(1)\nدولابی، طبرانی اور ابن مندہ نے ان کا ذکر کیا ہے اور بطریق عبداللہ بن احد الحصی بواسطہ علی بن ابی علی عمی سے بحوالہ ابوریطہ بن کرامہ مذحجی روایت نقل کی ہے، فرمایا: ہم نبی صلی اللہ علیہ وسلم کے پاس تھے۔ آپ نے ایک سفر کرنے والی جماعت سے فرمایا: ہرگز تمہارے ساتھ شوئی بیمار جانور نہ ہو اور کسی سائل کو ہرگز نہ ہٹانا اور ہرگز کوئی گمشدہ جانور اپنے ساتھ شامل نہ کرنا، اگر تمہارا (اس سفر سے) نفع (کمانے) اور سلامتی (سے واپسی) کا ارادہ ہے۔۔۔ (حدیث)(2) طبرانی کی روایت میں لکھا ہے، ابوریطہ عبداللہ بن کرامہ سے مروی ہے، مستغفری نے بطریق عمر بن صبیح، ابوحریز قاضی سجستان، بواسطہ شعبی بحوالہ ابوریطہ مذحجی نبی صلی اللہ علیہ وسلم سے روایت کی ہے کہ ایک دفعہ آپ مغرب اور عشاء کے درمیانی وقت میں بیٹھے تھے کہ ایک جماعت گزری جو آہستہ آہستہ جارہی تھی۔۔۔ پھر وہ حدیث ذکر کی۔ بغوی نے ان کا ذکر کیا تو لکھا، ابوریطہ(3)، ان کی کوئی روایت نہیں نقل کی۔","",{"fn":"(1) اسد الغابہ (۵۹۰۰) تجرید (۱۶۷/۲)\n(2) مجمع الزوائد (۲۱۲/۳) المعجم الکبیر (۳۷۶/۲۲) کنز العمال (۱۷۶/۷) (۴۴۰۲۲)\n(3) المعجم الکبیر (۹۴۱/۲۲) مجمع الزوائد (۲۱۲/۳) الکنیٰ للدولابی (۳۱/۱)"}],[8522,"§۹۹۱۱ ۔ ابوریطہ(1) (دوسرے، بے نسبت)\nابونعیم نے ان کا تذکرہ کیا اور بطریق حسن بن سفیان بحوالہ ریطہ روایت کی ہے ان کے والد صحابی رسول صلی اللہ علیہ وسلم تھے۔ فرماتے ہیں: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: میں رکابی چاٹ لوں یہ مجھے اسے کھانے سے بھر کر صدقہ کرنے سے زیادہ بہتر ہے۔(2) ابوموسیٰ نے اپنے استدراک میں ان کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابہ (۵۸۹۹) تجرید (۱۶۷/۲)\n(2) جامع المسانید (۶۴/۱۴) اسد الغابہ (۴۵۰/۴)"}],[8523,"§۹۹۱۲ ۔ ابوریمہ(1)\nابن حبان نے بغیر نام کے ان کا صحابہ رضی اللہ عنہم میں ذکر کیا ہے اور ان کے حالات کا کچھ بیان نہیں کیا۔ ابن مندہ اور ابونعیم بطریق منہال بن خلیفہ بحوالہ ازرق بن قیس روایت کرتے ہیں کہ ہمیں ابوریمہ نامی ایک شخص نماز پڑھاتے تھے وہ دائیں بائیں ایسے سلام پھیرتے تھے کہ ان کے رخساروں کی سپیدی نظر آتی تھی۔ پھر انہوں نے فرمایا: میں نے تمہیں ایسے ہی نماز پڑھائی ہے جیسے میں نے رسول اللہ صلی اللہ علیہ وسلم کو نماز پڑھتے دیکھا ہے۔ ابن مندہ کا بیان ہے(2) شعبہ نے یہ روایت بواسطہ ازرق بن قیس بن عبداللہ بن ریاح بحوالہ ایک صحابی جن کا نام نہیں ذکر کیا نقل کی ہے۔ اطراف میں المزی نے لکھا ہے: ابوداؤد نے اسی سند سے نقل کی ہے۔ لیکن مجھے سنن کے کسی نسخہ میں یہ حدیث نہیں ملی جن میں سے ایک نسخہ ابوالفضل بن طاہر کا ایک نسخہ جو خطیب کے قلم سے منقول ہے۔ حفاظ (حدیث) کی ایک جماعت نے دونوں کا مقابلہ کیا وہ انتہائی محفوظ ہے۔ اس پر اتفاق ہے کہ صحابی ابورمثہ یعنی طاء سے پہلے میم ہے ایسا ہی طبرانی یہ حدیث ابورمثہ کی مسند کے حوالہ سے اپنی معجم میں روایت کی ہے اور اسی طرح میں نے مستدرک حاکم میں دیکھی ہے۔ واللہ اعلم!","",{"fn":"(1) اسد الغابہ (۵۹۰۱) تجرید (۱۶۷/۲)\n(2) ابوداؤد کتاب الصلاۃ باب فی الرجل یتطوع فی مکانہ الذی صلی بہ المکتوبۃ (۱۰۰۷) مسند احمد (۳۱۸۲)"}],[8524,"§۹۹۱۳ ۔ ابورافع الصائغ(1)\nان کا نام شفیع ہے مدنی ہیں بصرہ فروکش ہوئے۔ یہ بنت نجار کے مولا ہیں۔ بقول بعض: ان کے چچا زاد ہیں۔ ابن سعد نے اہل بصرہ کے پہلے طبقہ میں ان کا ذکر کیا۔ لکھتے ہیں: یہ بہت پہلے مدینہ سے چلے گئے تھے۔ ثقہ ہیں۔ الحاکم ابواحمد نے الکنیٰ میں بطریق مرحوم العطار بواسطہ ثابت البنانی بحوالہ ابورافع روایت کی ہے کہ جاہلیت میں انہوں نے درندے کا گوشت کھا لیا تھا۔(2) میں کہتا ہوں: سیدنا ابوہریرہ رضی اللہ عنہ سے بکثرت اسی طرح خلفاء اربعہ ابن مسعود، زید بن ثابت، ابی بن کعب اور ابوموسیٰ وغیرہ سے روایت کرتے ہیں۔ ان سے ان کا بیٹا عبدالرحمن، ثابت البنانی، بکر مازنی، قتادہ اور سلیمان تیمی وغیرہ روایت کرتے ہیں۔ عجلی کا قول ہے: اکابر تابعین میں سے معتبر ہیں۔ طبرانی نے اس بات کو وزنی قرار دیا ہے کہ ان کی کنیت ہی ان کا نام ہے اور ان کی توثیق کی ہے۔ ابوعمر کا قول ہے: تابعین علماء میں سے مشہور ہیں۔ دور جاہلیت پایا ہے۔ ابراہیم حربی نے \"غریب الحدیث\" میں عمدہ سند سے بحوالہ ابورافع روایت کی ہے۔ فرمایا: سیدنا عمر رضی اللہ عنہ مجھ سے مزاح کر کے کہتے: سب سے جھوٹا صائغ ہے۔ جو آج کو کل کہتا ہے۔","",{"fn":"(1) اسد الغابہ (۵۸۶۸) استیعاب (۲۹۸۸) تجرید (۱۶۴/۲)\n(2) اسد الغابہ (۴۴۱/۴)"}],[8525,"§۹۹۱۴ ۔ ابورجاء العطاردی(1)\nبقول بعض: نام عمران بن ملحان، یا ابن تیم، ابن عبداللہ۔ ایک قول ہے: ان کا نام عطارد ہے۔ ابن قتیبہ لکھتے ہیں: ہجرت سے گیارہ(۱۱) سال پہلے پیدا ہوئے۔ اور ہشام بن عبدالملک کی خلافت تک زندہ رہے۔ تاریخ مظفری میں میں نے ایسا ہی لکھا دیکھا ہے۔ اشعث بن سوار کا قول ہے: ان کی عمر ایک سو ستائیس(۱۲۷) سال تھی۔ صحیح بخاری میں ایک طریق سے مروی ہے جب رسول اللہ صلی اللہ علیہ وسلم مبعوث ہوئے تو ہم لوگ آگ کی طرف یعنی مسیلمہ کذاب کی طرف بھاگے۔ بقول ابوحاتم: دور جاہلیت کے ہیں۔ فتح کے بعد اسلام لائے اور ایک سو بیس(۱۲۰) سال زندہ رہے۔ امام بخاری رحمہ اللہ فرماتے ہیں: سیدنا حسن سے پہلے فوت ہوئے۔ ان کی وفات دس(۱۰) میں ہوئی۔ نبی صلی اللہ علیہ وسلم سے مرسل روایت کرتے ہیں۔ سیدنا عمر، علی، عمران بن حصین، سمرہ بن جندب، ابن عباس اور سیدہ عائشہ رضی اللہ عنہم سے روایت کرتے ہیں۔ جبکہ ان سے روایت کرنے والے مندرجہ ذیل افراد ہیں: ایوب، جریر بن حازم، عوف الاعرابی، مہدی بن میمون، عمران القصیر، ابوالاشہب اور الجعد ابوعثمان۔ ابن سعد کا قول ہے: انہیں علم، قرآن اور روایت حاصل تھی وہ معتبر ہیں۔ اپنی قوم کی چالیس سال امامت کی اور عمر بن عبدالعزیز کی خلافت میں فوت ہوئے۔ واقدی کا قول ہے: ۷اھ میں فوت ہوئے۔ جو وہم ہے۔ ذہلی فرماتے ہیں: حسن سے پہلے فوت ہوئے، میرے خیال میں ۷اھ کا سال ہے۔ یحییٰ بن معین، ابوزرعہ اور ابن عبدالبر نے انہیں ثقہ لکھا ہے اور یہ اضافہ نقل کیا ہے، البتہ ان سے کبھی غفلت ہو جاتی تھی۔","",{"fn":"(1) اسد الغابہ (۵۸۷۲) تجرید (۱۶۵/۲)"}],[8526,"§۹۹۱۵ ۔ ابورزین الاسدی\nمسعود بن مالک، تابعی ہیں۔ اس میں اختلاف ہے کہ آیا انہوں نے دور نبوت پایا ہے یا نہیں۔ قسم چہارم میں ان کا تذکرہ ہوگا۔"],[8527,"§۹۹۱۶ ۔ ابوالرقاد\nان کا نام شولیس ہے۔"],[8528,"§۹۹۱۷ ۔ ابورمح الخزاعی\nدعبل بن علی نے طبقات الشعراء میں ان کا تذکرہ کیا ہے کہ اہل حجاز کے مخضرمی ہیں۔ انہوں نے ہی سیدنا حسین بن علی رضی اللہ عنہما کا مندرجہ ذیل اشعار میں مرثیہ کہا۔ میں آل محمد کے گھرانوں سے گزرا تو وہ مجھے ایسے نظر نہ آئے جیسے آباد تھے۔ اللہ تعالیٰ ان گھروں اور مکینوں کو دور نہ کرے اگرچہ وہ اپنے مکینوں سے خالی ہو گئے۔"],[8529,"§۹۹۱۸ ۔ ابورہم السمعی\nبقول بعض الظہر کی۔ نام احزاب بن اسید تھا۔ ناموں میں تذکرہ ہوا ہے۔"],[8530,"§۹۹۱۹ ۔ ابورزین(1)\nمسعود بن مالک اسدی، ان کے مولا ہیں۔ بقول بعض: سیدنا علی رضی اللہ عنہ کے مولا ہیں۔ نام عبید ہے، کوفہ فروکش ہوئے، ابن ام مکتوم، علی بن ابی طالب، ابوموسیٰ اشعری، ابوہریرہ رضی اللہ عنہ وغیرہ سے روایت کرتے ہیں۔ جبکہ ان سے ان کا بیٹا عبداللہ، اسماعیل بن ابی خالد، عطاء بن السائب، اعمش، منصور، موسیٰ بن ابی عائشہ اور مغیرہ بن مقسم روایت کرتے ہیں۔ ابوحاتم فرماتے ہیں: بقول بعض: صفین میں سیدنا علی رضی اللہ عنہ کا ساتھ دیا۔ امام بخاری رحمہ اللہ نے اپنی صحیح کے باب الطہارۃ میں ان کا فعل تعلیقاً ذکر کیا ہے اور \"الادب المفرد\" میں ان کی سند سے روایت کی ہے۔ اور امام مسلم اور چاروں نے ان کی روایت سے بحوالہ صحابہ رضی اللہ عنہم حدیث نقل کی ہے۔ ابن شاہین کا بیان ہے صحابی ہیں۔ ابوموسیٰ نے ان کا تعاقب کرتے ہوئے لکھا ہے: یہ صحابی نہیں اور نہ انہوں نے دور نبوی پایا ہے۔ پھر بطریق عاصم بن ابی وائل روایت کی ہے، انہیں ابورزین پر تعجب نہیں ہوتا جو بوڑھے ہو گئے۔ وہ عہد فاروقی میں لڑکے تھے اور میں مرد تھا۔ بقول بعض: وہ ابووائل سے بڑے تھے۔ عالم سمجھدار تھے۔ ایسا ہی تہذیب میں المزی کے قلم سے لکھا ہے مغلطائی ان کا تعاقب کرتے ہوئے لکھتے ہیں: \"فهما\" فاء سے غلط ہے \"بھما\" ہے۔ ایسا ہی امام بخاری رحمہ اللہ نے یحییٰ قطان سے بحوالہ ابوبکر نقل کیا ہے: ابورزین مجھ سے بڑے ہیں۔ یحییٰ فرماتے ہیں: وہ دونوں کا علم رکھتے تھے، ابوزرعہ اور عجلی وغیرہ نے انہیں ثقہ لکھا ہے۔ میں کہتا ہوں: ان کی سیدنا معاذ بن جبل رضی اللہ عنہ سے روایت ہے جو مرسل ہے، ابوالحسن بن قطان نے انکار کیا ہے کہ انہوں نے ابن ام مکتوم کا دور پایا ہو شعبہ کا قول ہے جو ابن ابی حاتم نے بحوالہ ان کے مراسیل میں نقل کیا ہے، انہوں نے ابن مسعود سے سماع حدیث نہیں کیا ہے۔ بقول بعض: عبیداللہ بن زیاد نے ۶۰ھ کے بعد انہیں قتل کر دیا تھا۔ ایک قول ہے جماجم تک ۸۰ھ کے بعد زندہ رہے جس کی تاریخ ابن قانع نے پچانوے(۹۵) لکھی ہے۔","",{"fn":"(1) اسد الغابہ (۵۸۷۶) استیعاب (۳۰۰۰) تجرید (۱۶۵/۲)"}],[8531,"§۹۹۲۰ ۔ ابورہم الانماری(1)\nابوبکر بن علی نے صحابہ رضی اللہ عنہم میں ان کا ذکر کیا ہے اور یہ روایت(2) نقل کی ہے کہ ابورہم انماری نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم جب لیٹنے لگتے تو فرماتے: بسم اللہ اللھم اغفر لی ذنبی واخس شیطانی وفک رھانی۔ (حدیث)(3) ابوموسیٰ نے اپنے استدراک میں ان کا ذکر کیا ہے جو غلط ہے اور تحریف و تصحیف کا نتیجہ ہے، یہ نام تو زہیر انماری تھا ایسا ہی ابن ابی عاصم نے لکھا ہے جو ان کی کتاب الدعاء میں ہے اور طبرانی نے یہ دعا نقل کی ہے۔","",{"fn":"(1) اسد الغابہ (۵۸۸۹) تجرید (۱۶۶/۲)\n(2) الاحاد والمثانی (۲۸۷۸)\n(3) ابوداؤد کتاب الادب باب ما یقال عند النوم (۵۰۵۴) کنز العمال (۱۸۲۳۶) مرقاۃ (۲۴۰۹)"}],[8532,"§۹۹۲۱ ۔ ابورہم الظہری(1)\nابو بکر بن علی نے ان کا تذکرہ کیا ہے اور ابوموسیٰ نے اپنے استدراک میں ان کا ذکر کیا ہے جو غلط ہے یہ اسمعی ہیں اور ان کا نام احزاب ہے۔ صحابی نہیں ہیں۔ ابن ابی عاصم(2) نے بحوالہ یحییٰ بن سعید العطار ان کا ذکر کیا ہے کہ حمص میں دوسو میں انہیں وظیفہ ملتا تھا، بہت بوڑھے تھے، پیلا خضاب لگاتے تھے، ان کا عمارہ نامی بیٹا یزید بن المہلب کے ساتھ شہید ہوا۔","",{"fn":"(1) اسد الغابہ (۵۸۹۱) تجرید (۱۶۶/۲)\n(2) الاحاد والمثانی (۳۳۳/۵)"}],[8533,"§۹۹۲۲ ۔ ابورہیمہ الشجاعی(1)\nابوموسیٰ نے اپنے استدراک میں ان کا ذکر کیا ہے اور حوالہ جعفر مستغفری کا دیا ہے جو غلط ہے شجاعی سماعی کی بگڑی ہوئی صورت ہے اور جو حدیث مستغفری نے ذکر کی ہے وہ وہی حدیث ہے جو قسم اوّل میں بطریق سلیمان بن داؤد کی ان کے اتباع میں گزری ہے۔","",{"fn":"(1) اسد الغابہ (۵۸۹۵) تجرید (۱۶۷/۲)"}],[8534,"§۹۹۲۳ ۔ ابوریحانہ(1)\nعبداللہ بن مطر۔ ابو نعیم نے ان کا ذکر کیا ہے جو غلط ہے۔ کیونکہ ابوریحان صحابی کا نام شمعون ہے، رہے عبداللہ بن مطر تو یہ تابعی ہیں، خادم نبی صلی اللہ علیہ وسلم سیدنا سفینہ سے روایت کرتے ہیں۔","",{"fn":"(1) اسد الغابہ (۵۸۹۷) تجرید (۱۶۷/۲)"}],[8535,"§۹۹۲۴ ۔ ابوریطہ مذحجی(1)\nابوموسیٰ نے ان میں اور ابورائطہ میں فرق کیا ہے جبکہ دونوں ایک ہیں اور حدیث بھی ایک ہے۔ بقول بعض: ابورائطہ سے اور بقول بعض: ابوریطہ سے مروی ہے جس کی وضاحت قسم اوّل میں کر چکا ہوں۔","",{"fn":"(1) اسد الغابہ (۵۹۰۲) تجرید (۱۶۷/۲)"}],[8536,"§۹۹۲۵ ۔ ابوریمہ\nقسم اول میں ان کے متعلق کلام ہو چکا ہے۔"],[8537,"§۹۹۲۶ ۔ ابوزرارہ انصاری\nابن ابی خیثمہ نے صحابہ رضی اللہ عنہم میں ان کا ذکر کیا ہے۔ ابو عمر لکھتے ہیں: اس میں تامل ہے۔ بغوی کا قول ہے: ان کا نام معلوم نہیں، اور نہ میں یہ جانتا ہوں آیا صحابی ہیں یا نہیں؟ پھر انہوں نے اور ابن ابی خیثمہ نے یہ روایت نقل کی ہے کہ نبی صلی اللہ علیہ وسلم نے فرمایا: ”جس نے تین بار منادی (مؤذن) کی آواز سنی اور جواب نہیں دیا اسے منافقوں میں شمار کیا جائے گا“۔(1) یہی روایت دوسرے شیخ سے بحوالہ ابان مرسل نقل کی ہے۔ بعض نے یہ امکان ظاہر کیا ہے کہ ابوزرارہ، عبدالرحمن بن سعد بن زرارہ ہی ہیں۔ قسم ثانی حرف عین میں ان کا تذکرہ ہو چکا ہے۔","",{"fn":"(1) جامع المسانید (۶۹/۱۴)"}],[8538,"§۹۹۲۷ ۔ ابوزرارہ نخعی(1)\nانہیں آنے کی سعادت حاصل ہے۔ ابن کلبی کا قول ہے: یہ بات ابن الاثیر نے بحوالہ ابن دباغ نقل کی ہے، جبکہ جمہرہ میں زرارہ نام ہے نہ کہ کنیت۔ میں کہتا ہوں: بات یہی ہے، ناموں میں تذکرہ ہو چکا ہے، میں نے صرف احتمال کی وجہ سے ذکر کر دیا ہے۔","",{"fn":"(1) اسد الغابہ (۵۹۰۳) تجرید (۱۶۷/۲) ایضا"}],[8539,"§۹۹۲۸ ۔ ابوزعراء(1)\nابن مندہ نے ان کا ذکر کیا ہے کہ اہل مصر میں شمار ہوتے ہیں، پھر ان کی روایت نقل کی ہے، فرماتے ہیں: میں رسول اللہ صلی اللہ علیہ وسلم کے ساتھ ایک سفر میں نکلا رسول اللہ صلی اللہ علیہ وسلم ہم سواریوں پہ تھے۔ میں نے سنا، آپ صلی اللہ علیہ وسلم نے فرمایا: مجھے دجال سے زیادہ بڑے فتنے کا اپنی امت کے بارے میں خوف ہے۔۔۔۔ (حدیث)(2) اس میں ہے گمراہ حکمرانوں کا خوف ہے۔ محمد بن ربیع جیزی نے اُن صحابہ رضی اللہ عنہم میں ان کا ذکر کیا ہے جو مصر میں داخل ہوئے کہ اہل مصر کی ان سے ایک حدیث مروی ہے پھر مذکورہ سند سے اسے بیان کیا۔","",{"fn":"(1) اسد الغابہ (۵۹۰۳) تجرید (۱۶۷/۲) السلسلۃ الصحیحۃ (۱۵۸۲) (۱۹۸۹) جامع المسانید (۷۱/۱۴) کنز العمال (۲۹۰۴۳)\n(2) اسد الغابہ (۵۹۰۷) استیعاب (۳۰۰۸) تجرید (۱۶۷/۲)"}],[8540,"§۹۹۲۹ ۔ ابوزعنہ(1)\nشاعر۔ نام میں اختلاف ہے۔ عامر بن کعب بن عمرو بن خدیج/ عبداللہ بن عمرو/ کعب بن عمرو، طبری فرماتے ہیں: بدر میں شریک ہوئے، یہی ابو عمر کا بیان ہے۔ میں کہتا ہوں: ابن اسحاق(2) کا بیان ہے: اُحد میں شریک ہوئے، پھر فرماتے ہیں بنی جشم بن خزرج کے ایک شخص ابوزعنہ بن عبداللہ بن عمرو بن عتبہ نے اُحد کے روز کہا، میں ابوزعنہ ہوں، بڑھاپا مجھے باز رکھتا ہے۔ باعث رسوائی و شرمندگی کے کام سے صرف درد کی وجہ سے بچا جا سکتا ہے۔ خزرجی جو جشم سے ہے اپنے علاقوں کی حفاظت کرتا ہے۔","",{"fn":"(1) اسد الغابہ (۵۹۰۸) استیعاب (۳۰۰۹) تجرید (۱۶۸/۲)\n(2) السیرۃ النبویۃ (۱۳۱/۳)"}],[8541,"§۹۹۳۰ ۔ ابوزمعہ بلوی\nعسکری نے ان کا نام عبید ابن ارقم بتایا ہے، ابو موسیٰ کی کتاب میں یہ نام بغیر تصغیر عبید اور والد کے نام کے بغیر لکھا ہے۔ بغوی اور ابن السکن وغیرہ نے صحابہ رضی اللہ عنہم میں ان کا ذکر کیا ہے اور بطریق ابن لہیعہ بحوالہ ابو قیس مولا بنی صیح روایت کی ہے کہ میں نے ابوزمعہ بلوی کو فرماتے سنا (اور وہ بیعت رضوان کے شرکاء میں سے تھے) ایک دن فسطاط تشریف لائے میدان میں کھڑے ہوئے انہیں عبداللہ بن عمرو کی بعض سختیوں کا علم ہوا تھا، فرمانے لگے: لوگوں پر سختی نہ کرو کیونکہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا ہے: بنی اسرائیل کے ایک شخص نے ننانوے(۹۹) قتل کیے تھے۔(1) حدیث طویل ہے۔ یہ حدیث میں نے معجم بغوی میں حرف قاف کے آخر میں دیکھی ہے، مجھے اس کا سبب معلوم نہ ہو سکا پھر میں نے دوسرا نسخہ دیکھا۔ بقول بعض: ان کا نام عبید بن آدم ہے۔","",{"fn":"(1) المعجم الکبیر (۷۸۸/۲۲) مجمع الزوائد (۲۱۳/۱۰) جامع المسانید (۷۳/۱۴)"}],[8542,"§۹۹۳۱ ۔ ابوزہراء بلوی(1)\nصحابی ہیں۔ فتح مصر میں شریک تھے۔ ابن مندہ نے بحوالہ ابن یونس ان کا ذکر کیا ہے، مجھے یہ لفظی غلطی لگتی ہے۔ یہ نام تو ابوزعراء ہے، کیونکہ تاریخ ابن یونس میں ابوزعراء کے علاوہ اور کوئی نہیں۔ ایسا ہی ابن ربیع جیزی کی کتاب ”مصر میں داخل ہونے والے صحابہ رضی اللہ عنہم“ میں ہے۔","",{"fn":"(1) اسد الغابہ (۵۹۱۰) تجرید (۱۶۸/۲)"}],[8543,"§۹۹۳۲ ۔ ابوزہراء قشیری\nقسم ثالث میں ان کا ذکر ہوگا، ممکن ہے اس قسم میں سے ہوں، کیونکہ ان کے حالات میں آتا ہے کہ ان لوگوں میں سے تھے جنہیں سیدنا یزید بن ابی سفیان رضی اللہ عنہ نے شام کی بعض فتوحات میں امیر مقرر کیا تھا، اور بارہا گزر چکا ہے کہ فتوحات میں صرف صحابہ کرام رضی اللہ عنہم ہی امیر بنائے جاتے تھے۔ اور اس واقعہ میں دحیہ بن خلیفہ کے ساتھ ملا دیا ہے۔"],[8544,"§۹۹۳۳ ۔ ابوزہیر بن اسید\nبن جعونہ۔ قرہ بن دعموص کے حالات میں ان کا ذکر ہو چکا ہے۔"],[8545,"§۹۹۳۴ ۔ ابوزہیر الانماری\nابوالزہیر نامی حضرات میں ذکر ہوا ہے۔"],[8546,"§۹۹۳۵ ۔ ابوزہیر ثقفی(1)\nابن حبان ”الصحابہ“ میں لکھتے ہیں: وفد میں شامل تھے۔ بقول بغوی: طائف کے رہائشی تھے۔ بقول ابن ماکولا: نبی صلی اللہ علیہ وسلم کے پاس آئے۔ ابو احمد نے ”الکنیٰ“ میں ابوزہیر بن معاذ اور ابوزہیر ثقفی میں فرق کیا ہے۔ ثقفی کے متعلق لکھتے ہیں: ان کا نام عمارہ بن حمید تھا اور یہ ابوبکر بن ابی زہیر کے والد ہیں اور حدیث ابوزہیر مسند احمد ابن ماجہ اور الدارقطنی نے الافراد میں حسن غریب سند سے بطریق نافع بن عمر حجی بحوالہ ابوزہیر ثقفی سے نقل کی ہے کہ نبی صلی اللہ علیہ وسلم نے طائف کے علاقے نجادہ میں ہم سے خطاب کیا، فرمایا: ”عنقریب تمہیں جہنمیوں سے جنتی علیحدہ نظر آئیں گے“۔ لوگوں نے عرض کی: اللہ کے رسول صلی اللہ علیہ وسلم؟ کس طرح؟ آپ صلی اللہ علیہ وسلم نے فرمایا: ”اچھی اور بری تعریف سے، تم ہی ایک دوسرے کے گواہ ہو“۔(2) الدارقطنی کا قول ہے: امیہ بن صفوان اس میں منفرد ہے اور حاکم نے یہ روایت بطریق سفیان بن عیینہ نقل کی ہے جو سنداً صحیح ہے۔ حدیث معاذ ناموں میں گزر چکی ہے۔ المزی نے یہ بھی نقل کیا ہے کہ انہیں عمارہ بن رویبہ بھی کہا جاتا ہے۔","",{"fn":"(1) اسد الغابہ (۵۹۱۳) تجرید (۱۶۸/۲)\n(2) ابن ماجہ کتاب الزہد باب الثناء الحسن (۴۲۲۱) مسند احمد (۴۱۶/۲)"}],[8547,"§۹۹۳۶ ۔ ابوزہیر(1)\nبن معاذ بن ریاح ثقفی۔ بقول حسین بن محمد قبانی: صحابی ہیں۔ ایک قول ہے: معاذ ان کا نام ہے، حاکم ابواحمد کا قول ہے: ابراہیم حربی کا بیان ہے: ابوزہیر بن معاذ ان صحابہ رضی اللہ عنہم سے ہیں جن کے ناموں سے زیادہ ان کی کنیت مشہور ہے۔ اور پھر ان کی یہ حدیث نقل کی: ”جب تم نام رکھو تو عبداللہ اور عبد الرحمن جیسے نام رکھو“۔(2) یہی حدیث طبرانی نے معاذ ثقفی کے حالات میں نقل کی ہے میں نے وہیں اس کی علت بیان کی ہے اور المزی نے ابوزہیر ثقفی کے حالات میں درج کی ہے، فرماتے ہیں: بقول بعض: ابوزہیر بن معاذ۔","",{"fn":"(1) اسد الغابہ (۵۹۱۴) تجرید (۱۶۸/۲)\n(2) مجمع الزوائد (۵۰/۸) المعجم الکبیر (۳۸۳/۲۰) کنز العمال (۴۰/۹۶) اتحاف السادۃ المتقین (۳۸۷/۵)"}],[8548,"§۹۹۳۷ ۔ ابوزہیر النمیری(1)\nبقول بعض: ابوزہیر الانماری جنہیں ابوزہر بھی کہا جاتا ہے، راجح یہی ہے کہ وہ اور ہیں۔ ابن مندہ صبیح بن مخرمہ کے طریق سے بحوالہ ابو صبح مقبری روایت کرتے ہیں، فرمایا: ہم ابوزہیر نمیری کے پاس بیٹھا کرتے تھے جو صحابی تھے۔ وہ بہت اچھی گفتگو کرتے اور جب ہم میں سے کوئی شخص دعا کرتا تو فرماتے: آمین کہہ کر ختم کرنا، کیونکہ دعا میں آمین ایسے ہی ہے جیسے خط پر مہر۔ پھر ابوزہیر کہنے لگے: میں تمہیں اس کے متعلق بتاتا ہوں ایک رات ہم لوگ رسول اللہ صلی اللہ علیہ وسلم کے ساتھ چلتے ہوئے باہر نکلے، ایک خیمہ میں ایک شخص کے پاس ٹھہر گئے جس نے دعا کرنے میں اصرار کیا اور رسول اللہ صلی اللہ علیہ وسلم اس کی بات سنتے جا رہے تھے۔ آپ صلی اللہ علیہ وسلم نے فرمایا: ”اگر اس نے مہر لگا دی تو اس کی دعا قبول ہے“۔ لوگوں میں سے ایک شخص عرض کرنے لگا: کس چیز سے مہر لگائے؟ آپ صلی اللہ علیہ وسلم نے فرمایا: ”آمین سے، اگر اس نے آمین سے دعا ختم کی تو قبول ہوئی۔ چنانچہ جس شخص نے آپ صلی اللہ علیہ وسلم سے یہ بات سنی وہ اس دعا کرنے والے) کے پاس پہنچا اور کہنے لگا: ”مبارک ہو،(2) بھائی ہر دعا آمین پر ختم کیا کرو“۔ پھر فرماتے ہیں: یہ غریب حدیث ہے، جس میں فریابی صبح سے نقل کرنے میں منفرد ہے۔ بغوی اور طبرانی نے مسند شامیین میں بطریق ضمضم بن زرعہ بواسطہ شریح بن عبید حضرمی بحوالہ ابوزہیر نمیری (جو صحابی ہیں) روایت کی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ٹڈیوں (جو سبزہ کھاتی ہیں، گھریلو نجاست کھانے والی ٹڈیاں مراد نہیں) کو قتل نہ کرو، کیونکہ یہ اللہ کے لشکروں میں سے ایک بڑی فوج ہے۔(3) بقول بغوی: شام کے رہائشی تھے۔ یحییٰ بن نفیر کے حالات میں اس کا کچھ تذکرہ ہوا ہے۔ احتمال ہے یہ ابوزہیر بن جعونہ ہوں جن کا ذکر ہو چکا ہے کیونکہ وہ بھی نمیری ہیں۔","",{"fn":"(1) اسد الغابہ (۵۹۱۵) تجرید (۱۶۸/۲)\n(2) ابوداؤد کتاب الصلاۃ باب التامین وراء الامام (۹۳۸) کنز العمال (۳۲۳۳) مرقاۃ المصابیح (۸۴۶۵)\n(3) المعجم الکبیر (۷۵۷/۲۲) مجمع الزوائد (۳۹/۴) جامع المسانید (۷۵/۱۴)"}],[8549,"§۹۹۳۸ ۔ ابوزوائد یمانی(1)\nمطین اور الکنی میں دولابی نے صحابہ رضی اللہ عنہم میں ان کا ذکر کیا ہے۔ فاکہی اور جعفر فریابی نے کتاب النکاح میں ابراہیم بن میسرہ سے صحیح سند کے ساتھ نقل کیا ہے کہ ہم طواف کر رہے تھے تو طاؤس مجھ سے کہنے لگے: یا تمہیں نکاح کرنا ہی پڑے گا یا میں تمہیں وہ بات کہوں جو سیدنا عمر رضی اللہ عنہ نے ابوزوائد سے کہی تھی: ”کیا تم عاجزی یا زنا کی وجہ سے نکاح نہیں کر رہے؟“ اور طبرانی بطریق زیاد بن نصر بواسطہ سلیم بن مطین بحوالہ اپنے والد وہ ابوزوائد سے روایت کرتے ہیں، فرمایا: حجتہ الوداع(2) کے موقعہ پر میں رسول اللہ صلی اللہ علیہ وسلم کے ساتھ تھا، پھر لمبی حدیث ذکر کی جس کا کچھ حصہ ابوداؤد نے اسی سند سے نقل کیا ہے جس کی طرف حرف ذال میں اشارہ ہو چکا ہے۔ ان میں سے کسی کا کہنا ہے: ابوزوائد وہی ذوالزوائد ہیں جن کا امام بخاری رحمہ اللہ نے گمنتیوں میں ذکر کیا ہے اور اسی سند سے اس حدیث کا ایک گوشہ نقل کیا ہے۔","",{"fn":"(1) اسد الغابہ (۵۹۰۹) تجرید (۱۶۹/۱)\n(2) ابوداؤد کتاب الخراج والامارۃ باب فی کراہیۃ الافتراض فی آخر الزمان (۲۹۵۹) التاریخ الکبیر (۲۶۵/۳) الاحاد والمثانی (۱۱۸/۵) المعجم الکبیر (۸۹۴/۲۲) جامع المسانید (۷۸/۱۴)"}],[8550,"§۹۹۳۹ ۔ ابوزیاد(1)\nمولا بنی تج۔ یہ صدیق اکبر رضی اللہ عنہ سے اور ان سے خالد بن معدان روایت کرتے ہیں۔ ایسا ہی تجرید میں ہے(2) شاید ان کے نزدیک یہ محضرمی ہیں مجھے ان کی ایک اور مرفوع حدیث مل گئی ہے جو طبرانی نے مسند شامیین میں بطریق سفیان بن حبیب، ثور بن زید سے بواسطہ خالد بن معدان بحوالہ ابوزیاد نقل کی ہے۔ فرمایا: ”میں اس بات کو نہیں بھولا کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو دیکھا جب آپ صلی اللہ علیہ وسلم نماز پڑھتے تو دایاں ہاتھ بائیں ہاتھ کے اوپر رکھتے تھے“۔","",{"fn":"(1) تجرید (۱۶۹/۲)\n(2) تجرید (۱۶۱)"}],[8551,"§۹۹۴۰ ۔ ابوزید انصاری\nناموں میں زرارہ میں تذکرہ ہوا ہے۔"],[8552,"§۹۹۴۱ ۔ ابوزید(1)\nجنہوں نے قرآن جمع کیا تھا۔(2) (صحیح بخاری میں حدیث انس میں بغیر نام کے ان کا ذکر آتا ہے سیدنا انس رضی اللہ عنہ فرماتے ہیں: میرے چچاؤں میں سے ایک ہیں۔ ان کے نام کے بارے اختلاف ہے۔ اوس/ ثابت بن زید/ معاذ/ سعد بن عبید/ قیس بن السکن یہی راجح ہے، جیسا کہ میں نے حرف قاف میں بیان کیا ہے۔","",{"fn":"(1) اسد الغابہ (۵۹۱۷) تجرید (۱۶۹/۲)\n(2) اسد الغابہ (۴۵۶/۴)"}],[8553,"§۹۹۴۲ ۔ ابوزید(1)\nبن اخطب۔ نام عمرو بن اخطب بن رفاعہ بن محمود بن بشر بن عبداللہ بن الضیف بن احمد بن عدی بن ثعلبہ بن حارثہ بن عمرو بن عامر انصاری خزرجی۔ ابوزید کنیت سے مشہور ہیں۔ عزرہ بن ثابت کے نانا ہوتے ہیں۔(2) ترمذی نے ان کی روایت نقل کی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے میرے چہرے پر ہاتھ پھیرا اور میرے لیے دعا فرمائی۔(3) امام احمد رحمہ اللہ کی صرف اس حدیث میں ہے اس سے میرا حسن و جمال بڑھ گیا۔ فرماتے ہیں: مجھے کئی لوگوں نے بتایا کہ ان کی عمر سو(۱۰۰) سے زائد کی ہوگئی پھر بھی ان کے سر اور داڑھی کے بال سیاہ تھے۔ امام احمد رحمہ اللہ کی روایت میں دوسری سند سے ہے جو ابو نہیک سے مروی ہے کہ مجھ سے ابو زید نے بیان کیا۔ رسول اللہ صلی اللہ علیہ وسلم نے پانی طلب کیا تو میں ایک برتن میں پانی لے کر حاضر ہوا، اس میں کہیں سے ایک بال پڑ گیا، میں نے وہ بال نکال پھینکا۔ آپ صلی اللہ علیہ وسلم نے فرمایا: ”اے اللہ! اسے حسن و جمال عطا فرما“۔(4) فرماتے ہیں: میں نے انہیں چورانوے(۹۴) برس کی عمر میں دیکھا، ان کی داڑھی میں ایک بھی سفید بال نہ تھا۔ ابن حبان اور حاکم نے اسے صحیح قرار دیا ہے۔ مسلم میں اسی سند سے ہے: ہمیں رسول اللہ صلی اللہ علیہ وسلم نے فجر کی نماز پڑھائی اور خطاب کرنے منبر پر تشریف لے گئے، اور ظہر تک خطاب کیا۔۔۔۔ (حدیث) شمائل ترمذی میں مذکورہ طریق سے بحوالہ ابوزید مروی ہے مجھ سے رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”ابوزید میرے قریب آکر میری پشت پر ہاتھ پھیرنا۔ میں نے آپ کی پشت مبارک پر ہاتھ پھیرا اور مہر نبوت پر انگلی رکھی۔۔۔۔ (حدیث)(5) ابن حبان اور حاکم نے اسے بھی صحیح لکھا ہے۔","",{"fn":"(1) اسد الغابہ (۵۹۲۲) استیعاب (۳۰۱۶) تجرید (۱۶۹/۲)\n(2) جامع المسانید (۸۱/۴)\n(3) مسند احمد (۳۴۰/۵) جامع المسانید (۸۳/۱۴)\n(4) مسند احمد (۳۴۱/۵) المستدرک (۱۳۹/۴) المصنف لعبد الرزاق (۱۹۴۶۲) مجمع الزوائد (۳۷۸/۹) المعجم الکبیر (۲۸/۱۷)\n(5) مسند احمد (۳۴۱/۵) جامع المسانید (۸۳/۱۴)"}],[8554,"§۹۹۴۳ ۔ ابوزید بن الضحاک\nنام ثابت ہے۔"],[8555,"§۹۹۴۴ ۔ ابوزید بن عُبید\nنام سعد ہے۔"],[8556,"§۹۹۴۵ ۔ ابوزید بن عمرو بن حدیدہ\nنام قطبہ ہے۔"],[8557,"§۹۹۴۶ ۔ ابوزید بن غرزہ\nنام عمرو ہے۔ ناموں میں ان حضرات کا تذکرہ ہو چکا ہے سب کا تعلق انصار سے ہے۔"],[8558,"§۹۹۴۷ ۔ ابوزید انصاری خزرجی(1)\nابوزید نحوی بصری کے دادا، بقول حاکم ابو احمد صحابی ہیں اور نحوی کا نام سعید بن اوس بن ثابت بن بشیر بن ابی زید ہے۔ واقدی کا قول ہے: یہ قرآن جمع کرنے والے کے علاوہ ہیں، پہلے بیان ہو چکا ہے کہ ان کی اولاد نہ تھی۔","",{"fn":"(1) اسد الغابہ (۵۹۱۷) استیعاب (۳۰۱۹)"}],[8559,"§۹۹۴۸ ۔ ابوزید بن عمرو الجذامی(1)\nابن اسحاق نے جذامی میں وفد میں ان کا ذکر کیا ہے۔","",{"fn":"(1) تجرید (۱۶۹/۲)"}],[8560,"§۹۹۴۹ ۔ ابوزید الارحبی\nنام عمرو بن مالک ہے۔ ناموں میں تذکرہ ہوا ہے۔"],[8561,"§۹۹۵۰ ۔ ابوزید انصاری (دوسرے)\nبغوی نے ان کا ذکر کیا ہے اور یہ روایت نقل کی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: یعنی خوارج، اللہ تعالیٰ کی طرف بلاتے ہیں، لیکن اللہ تعالیٰ کے کسی حکم کے تابع نہیں، جو ان سے جنگ کرے گا وہ ان سے زیادہ اللہ تعالیٰ کے عہد کو پورا کرنے والا ہوگا۔(1)","",{"fn":"(1) المستدرک (۱۴۷/۲) المعجم الکبیر (۲۹/۱۷) کنز العمال (۳۱۲۵۱) (۳۱۶۰۰)"}],[8562,"§۹۹۵۱ ۔ ابو زید انصاری (دوسرے)\nابن کلبی کا بیان ہے اُحد میں شہید ہوئے۔ ابن فتحون نے اپنے استدراک میں ان کا ذکر کیا ہے۔"],[8563,"§۹۹۵۲ ۔ ابوزید (بے نسبت)\nبغوی نے ان کا ذکر کیا ہے اور بحوالہ غنم بن حویص روایت کی ہے فرمایا: میں نے ابوزید کو فرماتے سنا: میں نے نبی صلی اللہ علیہ وسلم کی معیت میں تیرہ غزوے کیے(1) لیکن امام احمد نے یہ روایت مسند ابوزید بن اخطب انصاری میں نقل کی ہے لیکن ان کی روایت میں لکھا ہے شعبہ بواسطہ تمیم نقل کرتے ہیں میں نے ابوزید کو فرماتے سنا، پھر ان کا ذکر کیا اور نسب نہیں بیان کیا۔","",{"fn":"(1) مسند احمد (۳۴۰/۵)"}],[8564,"§۹۹۵۳ ۔ ابوزید\nفاطمہ بنت قیس اپنی طویل حدیث میں فرماتی ہیں جو مطلقہ (طلاق یافتہ) کے خرچ اور رہائش کے متعلق ہے پھر اللہ تعالیٰ نے مجھے ابوزید یعنی اسامہ بن زید (جو ان کی کنیت ہے) کی بیوی ہونے کا شرف بخشا، اسے مسلم نے بطریق ابوبکر بن ابی جہم بحوالہ فاطمہ نقل کیا ہے۔"],[8565,"§۹۹۵۴ ۔ ابوزید الجرمی(1)\nبقول ابواحمد: صحابی ہیں۔ اس کی سند میں کلام ہے۔ بغوی فرماتے ہیں: مجھے ان کا صحابی ہونا، نہ ہونا معلوم نہیں۔ میں کہتا ہوں: ان کی حدیث بغوی اور طبرانی نے نقل کی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: والدین کا نافرمان، احسان جتلانے والا اور شراب کا عادی جنت میں نہیں جائے گا۔(2) عبید بن اسحاق عطار بے حد ضعیف راوی ہے۔ دارقطنی کا قول ہے، العلل میں لکھتے ہیں: اسے یزید بن ابی زیاد نے مجاہد سے نقل کیا ہے کہ ابوسعید خدری سے مروی ہے اور عبدالکریم کا قول ہے: مجاہد سے بحوالہ عبداللہ بن عمرو منقول ہے۔","",{"fn":"(1) اسد الغابہ (۵۹۲۰) تجرید (۱۶۹/۲)\n(2) المعجم الکبیر (۹۳۱/۲۲)"}],[8566,"§۹۹۵۵ ۔ ابوزید الغافقی\nابن مندہ(1) نے ان کا ذکر کیا ہے کہ اہل مصر میں شمار ہوتے ہیں۔ پھر بطریق عمرو بن شراحیل معافری بحوالہ ابوزید غافقی یہ روایت نقل کی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: مسواکیں تین قسم کی ہیں۔ پیلو، اگر پیلو نہ ہو تو زیتون یہ بھی نہ ہو تو بہن۔ ابووہب کا قول ہے جو اس روایت کے راوی ہیں تم(2) سے مراد زیتون ہے۔ ابن مندہ فرماتے ہیں: غریب ہے ہم اسی سند سے جانتے ہیں۔","",{"fn":"(1) اسد الغابہ (۵۹۲۳) تجرید\n(2) جامع المسانید (۸۹/۱۴) اسد الغابہ (۴۵۸/۴)"}],[8567,"§۹۹۵۶ ۔ ابوزید\nنبی صلی اللہ علیہ وسلم سے سماع کیا ہے ان سے حسن بصری نے سنا ہے۔ ابن مندہ نے اس بات کا جواز پیش کیا ہے یہ عمرو بن اخطب ہیں۔"],[8568,"§۹۹۵۷ ۔ ابو زید (بے نسبت)\nطبرانی نے الاوسط میں بطریق حسن بن دینار بواسطہ یزید الرشک روایت کی کہ میں نے ابوزید جو صحابی ہیں۔ کو فرماتے سنا: میں نبی صلی اللہ علیہ وسلم کے ساتھ تھا آپ نے ایک شخص کو تہجد میں سورۃ فاتحہ پڑھتے سنا تو کھڑے ہو کر غور سے سننے لگے یہاں تک کہ اس نے سورۃ ختم کر لی پھر فرمایا: پورے قرآن میں اس جیسی سورت نہیں۔ بقول بعض ممکن ہے یہ عمرو بن اخطب ہوں۔"],[8569,"§۹۹۵۸ ۔ ابو زید (بے نسبت)\nابومسلم کجی نے اپنی کتاب السنن میں ان کی حدیث نقل کی ہے ابوزید صحابی رسول صلی اللہ علیہ وسلم نے فرمایا: نبی صلی اللہ علیہ وسلم کا ارشاد ہے ”مسافر اپنے موزوں پر تین دن تین راتیں مسح کرے اور مقیم رات دن مسح کرے“۔"],[8570,"§۹۹۵۹ ۔ ابوزینب بن عوف انصاری(1)\nبقول ابو موسیٰ: ابوالعباس بن عقدہ نے کتاب الموالاۃ میں بطریق علی بن حسن العبدی، سعد سے جو اسکاف ہیں بحوالہ اصبغ بن نباتہ روایت کی ہے کہ سیدنا علی نے کھلے میدان میں لوگوں سے پوچھا: رسول اللہ صلی اللہ علیہ وسلم سے غدیر کے روز جس نے سنا وہ اٹھ کھڑا ہو چنانچہ دس بارہ آدمی کھڑے ہوئے ان میں ابوایوب اور ابوزینب بن عوف بھی تھے، ان سب نے کہا: ہم گواہی دیتے ہیں کہ ہم نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: انہوں نے آپ کا ہاتھ پکڑ کر بلند کر کے فرمایا: کیا تم لوگ گواہی نہیں دیتے کہ میں نے حق پہنچا دیا ہے؟ ہم نے عرض کی: ہم ضرور گواہی دیتے ہیں۔ تو آپ نے فرمایا: جس کا میں دوست اس کا علی دوست(2) اس کی سند میں کئی ایک ایسے راوی ہیں جو رفض کی جانب منسوب ہیں۔","",{"fn":"(1) اسد الغابہ (۵۹۲۶) تجرید (۱۷۰/۲)\n(2) مسند احمد (۴۱۹/۵) المعجم الکبیر (۴۰۵۲) مجمع الزوائد (۱۰۴/۹) جامع المسانید (۹۰/۱۴)"}],[8571,"§۹۹۶۰ ۔ ابوزرعہ بن زنباع\nوہی روح الجذامی ہیں ناموں میں تذکرہ ہوا ہے۔"],[8572,"§۹۹۶۱ ۔ ابو زبید الطائی\nمشہور شاعر ہیں دور نبوی پایا ہے۔ ان کے اسلام لانے میں اختلاف ہے نام حرملہ بن منذر ہے بقول بعض: منذر بن حرملہ بن معدیکرب۔۔۔۔ طائی بقول طبری ابوزبید جاہلیت میں بنی تغلب میں اپنے ماموؤں کے پاس جزیرہ میں مقیم تھا اور دور اسلام میں ولید بن عقبہ بن ابی معیط کی جزیرہ اور کوفہ پر ولایت کے دور میں اس کے پاس چلا گیا تھا۔ ولید اس کے ساتھ دوستی یاری رکھتا رہا یہاں تک کہ وہ مسلمان ہو گیا۔ اسلام میں اس کی حالت اچھی ہو گئی۔ ابو مورع اور اس کے ساتھی ولید پر جاسوس مقرر کرتے، کسی نے ان سے کہہ دیا کہ ولید ابھی ابوزبید کے ساتھ شراب پی رہا ہے یہ لوگ جھٹ سے پہنچے، ولید نے اپنے سامنے رکھی کوئی چیز چار پائی تلے چھپا دی، انہوں نے چار پائی پر جھپٹا مارا اور اس کے نیچے سے ایک صراحی نکال لی جس میں انگور کا رس تھا جسے دیکھ کر یہ لوگ شرمندہ ہو گئے۔ ابن قتیبہ لکھتے ہیں: ابوزبید مسلمان نہیں ہوا تھا بلکہ اپنے مذہب نصرانیت پر ہی مرا تھا۔ مرزبانی کا قول ہے: نصرانی تھا، لمبی عمر پائی تھی بقول بعض ڈیڑھ سو(۱۵۰) سال زندہ رہا، اسلام کا زمانہ پایا لیکن مسلمان نہیں ہوا۔ سیدنا عمر نے اسے اس کی قوم کے صدقات زکوۃ وصول کرنے پر مقرر کیا تھا آپ نے اس کے علاوہ کسی غیر مسلم کو یہ ڈیوٹی نہیں سونپی تھی۔ امیر معاویہ کے دور تک زندہ رہا۔ کوفہ میں ولید بن عقبہ بن ابی معیط کا ہم نشین تھا۔ جب ولید پر یہ تہمت لگائی گئی کہ اس نے شراب پی ہے اور کوفہ کی گورنری سے ہٹا دیا گیا، تو ابو زبید نے کہا: ش معبود (برحق) کی قسم! اگر تلوار کی دھار اور زبان کی گفتگو ہوتی تو نہ میرے صاف گھر کی تلاشی ہوتی اور نہ وہ وہاں آتے اور نہ تیرے درمیان شور و شغب حائل ہوتا”۔ سیدنا علی رضی اللہ عنہ کی شہادت پر مرثیہ کہا: ش ”معزز لوگ جن اخلاق و اوصاف کے مالک ہوتے ہیں وہ ایسے شخص کا خاندان ہے جو دین کا جامع اور پسندیدہ ہے مردوں کی قسموں میں کیا ہی خوب صاحب بصیرت انسان تھا رسول اللہ صلی اللہ علیہ وسلم کے پسندیدہ کے برابر اچھے لوگ نہیں ہو سکتے“۔ یہ اشعار ابوالفرج اصبہانی نے بحوالہ مبرد نقل کیے ہیں مرزبانی نے ان میں سے کچھ بھی نقل نہیں کیا۔ اصبہانی فرماتے ہیں۔ ابوزبید کا فقط تیرہ(۱۳) بالشت لمبا تھا اس کا بھائی اعور عجمی بادشاہوں کا خاص بندہ تھا جب اس کی وفات ہوئی تو ولید بن عقبہ کی قبر کے پاس دفن کیا گیا: جب اشجع سلمی کا وہاں سے گزر ہوا تو اس نے یہ اشعار کہے: ش ”میں ابوزبید کی ہڈیوں کے پاس سے گزرا، جو کھلے میدان میں سرد پڑی تھیں۔ ولید اس کا سچا دوست تھا، اب اس کی قبر ولید کی قبر کی ہم نشین ہے۔“ ابوزبید اپنے اشعار میں شیر کی تعریف کرنے میں بڑی دلچسپی لیتا تھا۔ جس کا سیدنا عثمان رضی اللہ عنہ کے ساتھ ایک واقعہ بھی ہے بقول بعض: اس کی قوم اسے کہنے لگی: ہمیں خدشہ ہے کہ تمہاری شیر کی تعریف کی وجہ سے عرب ہمیں گالیاں دیں گے۔ چنانچہ اس نے شیر کی تعریف میں اشعار کہنے چھوڑ دیے۔ مرزبانی لکھتے ہیں: ولید کی وفات اس سے پہلے ہو گئی تو یہ اس کی قبر پر سے گزرا تو کہا: ش ”اے قبر والے سلام ہو جس کی ملاقات کے درمیان قبر حائل ہو گئی ہے اے مجھے چھوڑنے والے! جب میں تیری ملاقات کے لئے آتا تھا تو تیری عادت بے رخی کی تو نہ تھی“۔"],[8573,"§۹۹۶۲ ۔ ابوزبیر (بیت المقدس کے مؤذن)\nدور نبوی صلی اللہ علیہ وسلم پایا ہے، دور فاروقی میں اذان دیتے تھے ابواحمد الحاکم نے الکنی میں روایت کی ہے کہ ابوزبیر کا قول ہے: ہمارے پاس عمر بن خطاب رضی اللہ عنہ آئے، مجھ سے فرمانے لگے: جب اذان دیا کرو تو تسلسل سے دیا کرو اور جب اقامت کہا کرو تو جلدی سے کہا کرو۔"],[8574,"§۹۹۶۳ ۔ ابوزہراء قشیری(1)\nابن عساکر نے الکنی میں ان کا ذکر کیا ہے کہ ان لوگوں میں سے ہیں جنہوں نے دور نبوی صلی اللہ علیہ وسلم پایا ہے اور فتح دمشق میں شریک ہوئے۔ اور اہل ثنیہ اور حوران کی صلح کے لئے سیدنا یزید بن ابی سفیان رضی اللہ عنہ کی جانب سے دور فاروقی میں مامور ہوئے پھر بطریق سیف بن عمر فتوح میں یہ روایت نقل کی ہے کہ یزید بن ابی سفیان رضی اللہ عنہ نے فتح دمشق کے بعد ایک لشکر میں دحیہ بن خلیفہ کلبی اور ابوزھراء کو ثنیہ اور حوران کی طرف دمشق کی صلح کے لئے تذمر بھیجا۔ اور اس مہم کی فتح کا بندوبست بھی انہی کے سپرد ہوا۔ ابوزھراء کے بھائی کا پاؤں فتح دمشق کے معرکہ میں کٹ چکا تھا۔ جب بنو قشیر نے بنی جعدہ کی ہجو کی تو اس پر فخر کیا۔ جس کا جواب انہیں نابغہ جعدی نے دیا پھر وہ اشعار نقل کیے۔ پھر سیف نے دمشق میں شراب پینے والوں کا واقعہ نقل کیا کہ سیدنا عمر نے انہیں حد لگائی۔ جس کے بارے میں ابوزھراء نے کہا: ش ”میں نے صبر سے کام لیا بے صبری نہیں کی اگرچہ میرے بھائی مر گئے حالانکہ میں تو ایک دن بھی شراب سے باز نہ رہ سکتا تھا امیر المومنین نے اسے موت کے گھاٹ اتار دیا، اب اس کے یار انگور کا رس نکالنے والوں کے پاس بیٹھ کے روتے ہیں۔“","",{"fn":"(1) تجرید (۱۶۸/۲)"}],[8575,"§۹۹۶۴ ۔ ابو زیاد(1)\nمولا آل دراج الجمحیین۔ دور نبوی پایا ہے مسدد نے اپنی مسند کبیر میں صحیح سند سے بواسطہ خالد بن معدان بحوالہ ابوزیاد مولا آل درّاج روایت کی ہے فرمایا: مجھے یہ بات نہیں بھولتی کہ صدیق اکبر جب نماز پڑھنے لگتے، تو اپنی داہنی ہتھیلی سے بائیں کلائی کو ہاتھ کے جوڑ (گٹے) کے ساتھ ملا کر پکڑتے۔ ابن عساکر نے یہ جواز پیش کیا ہے کہ یہ ربیعہ بن دراج کے مولا ہو سکتے ہیں۔ پھر اس ربیعہ کا نسب بیان نہیں کیا۔ میں کہتا ہوں: میں نے ربیعہ بن دراج کا تذکرہ اور ان کا نسب حرف راء کی قسم اول میں بیان کیا ہے۔","",{"fn":"(1) تجرید (۱۶۹/۲)"}],[8576,"§۹۹۶۵ ۔ ابوزید قیس بن عمرو ہمدانی\nناموں ذکر ہوا ہے۔"],[8577,"§۹۹۶۶ ۔ ابوزرعہ فزعی(1)\nابو موسیٰ نے ذیل میں ان کا ذکر کیا ہے کہ ابن طرخان نے صحابہ میں ان کا ذکر کیا ہے اور ان کی یہ حدیث نقل کی ہے کہ نبی صلی اللہ علیہ وسلم نے انہیں جھنڈا باندھ کر دیا تھا۔(2) (حدیث) یہ غلطی لفظی تبدیلی سے پیدا ہوئی درست ابو زویبعہ ہے۔ حرف راء میں ان کا نسب بھی قلمبند ہوا ہے، ان کا نام عبداللہ بن عبدالرحمن ہے۔","",{"fn":"(1) اسد الغابہ (۵۹۰۴) تجرید (۱۶۸/۲)\n(2) جامع المسانید (۷۰/۱۴) اسد الغابہ (۴۵۲/۴)"}],[8578,"§۹۹۶۷ ۔ ابوزرعہ(1)\nمولا مقداد بن اسود، بقول ابو عمر ان کا نام عبد الرحمن ہے، جو تابعی ہیں اور ان کی حدیث مرسل ہے۔ امام بخاری رحمہ اللہ(2) فرماتے ہیں: ان کی حدیث منقطع ہے۔ میں کہتا ہوں: ابو عمر سے پہلے مجھے کسی کا حوالہ نہیں ملا کہ اس نے ان کا صحابہ رضی اللہ عنہم میں ذکر کیا ہو۔ ان سے ابو ہلال راسبی نے روایت کی ہے جو قتادہ اور ان کے طبقہ سے روایت کرتے ہیں۔","",{"fn":"(1) اسد الغابہ (۵۹۰۵) تجرید (۱۶۹/۲)\n(2) التاریخ الکبیر (۳۵۶/۵)"}],[8579,"§۹۹۶۸ ۔ ابوزید عامر (عمر) بن حدیدہ\nابو عمر نے انصار میں سے ابوزید کنیتوں والوں میں ان کا ذکر کیا ہے جبکہ یہ وہ ابوزید ہیں جن کا نام قطبہ بن عامر بن حدیدہ ہے۔"],[8580,"§۹۹۶۹ ۔ ابوزید انصاری\nبغوی نے ان میں اور ابوزید عمرو بن اخطب میں فرق کیا ہے جو عروہ (عزرہ) بن ثابت کے دادا ہیں، پھر ان کے حالات میں حدیث تمیم بن حویص روایت کی ہے کہ میں نے ابوزید کو فرماتے سنا: میں نے رسول اللہ صلی اللہ علیہ وسلم کی معیت میں تیرہ(۱۳) غزووں میں شرکت کی۔ اور عروہ (عزرہ) کے دادا کے حالات میں یہ حدیث نقل کی ہے: ”ہمیں نبی صلی اللہ علیہ وسلم نے نماز پڑھائی پھر منبر پر تشریف فرما ہوئے اور ظہر تک خطبہ دیا“۔ (حدیث) امام احمد رحمہ اللہ نے یہ دونوں حدیثیں مسند ابی زید عمرو بن خطب میں نقل کی ہیں۔"],[8581,"§۹۹۷۰ ۔ ابوزبید بن الصلت(1)\nابن مندہ نے ان کا ذکر کیا ہے اور مراد زبید کے والد کو لیا ہے، اس وقت عنوان صلت بن معدیکرب کندی کا ہوگا۔ مناسب تھا جب انہوں نے انہیں حرف کنیت سے تعبیر کیا ہے تو ابوزبید الصلت کہتے ہیں لیکن ابن مندہ کا یہ اکثر استعمال ہے جسے میں کئی بار بیان کر چکا ہوں۔","",{"fn":"(1) اسد الغابہ (۵۹۲۸) تجرید (۱۷۰/۲)"}],[8582,"§۹۹۷۱ ۔ ابوسالم حنفی ثمّ سُحَیمی\nابن السکن نے صحابہ رضی اللہ عنہم میں ان کا ذکر کیا ہے اور پھر ام سالم سے بحوالہ ان کے خاوند ابو سالم سے روایت نقل کی ہے کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو تین بار فرماتے سنا: فلاں کی اولاد کے لیے ہلاکت ہے۔"],[8583,"§۹۹۷۲ ۔ ابوسائب\nعثمان بن مظعون جمحی، نام سے مشہور ہیں، سابقین اولین سے ہیں۔ ناموں میں تذکرہ ہو چکا ہے۔"],[8584,"§۹۹۷۳ ۔ ابوسائب(1)\nیزید عمر کے بھانجے، ناموں میں ذکر ہوا ہے۔","",{"fn":"(1) اسد الغابہ (۵۹۲۹) تجرید (۱۷۰/۲)"}],[8585,"§۹۹۷۴ ۔ ابوسائب انصاری\nبقول بعض ثقفی گردم کے والد، ان کے بیٹے کے حالات میں ان کا ذکر ہوا ہے۔"],[8586,"§۹۹۷۵ ۔ ابوسائب ثقفی\nنام مالک ہے، بقول بعض: زید یا یزید ہے، میم میں ان کا ذکر ہوا ہے۔"],[8587,"§۹۹۷۶ ۔ ابوسائب(1)\nصحابہ رضی اللہ عنہم میں ان کا ذکر ملتا ہے، لیکن میں انہیں نہیں جانتا یہ ابوعمر کا قول ہے۔ مسند بقی بن مخلد میں ابو سائب بے نسبت کی دو حدیثیں ہیں، لگتا ہے انہی میں کے ایک ہیں۔","",{"fn":"(1) اسد الغابہ (۵۹۳۲) استیعاب (۳۰۲۴)"}],[8588,"§۹۹۷۷ ۔ ابوسائب(1)\nمولا غیلان بن سلمہ ثقفی۔ ابو علی جیانی نے اپنے استدراک میں ان کا ذکر کیا ہے کہ عروہ بن سلمہ کا بیان ہے کہ ان کے والد ابو سائب مولا غیلان نے انہیں حدیث سنائی۔","",{"fn":"(1) اسد الغابہ (۵۹۳۰)"}],[8589,"§۹۹۷۸ ۔ ابوسائب(1)\nایک صحابی رسول صلی اللہ علیہ وسلم ہیں۔ ابن مندہ نے ان کا ذکر کیا ہے کہ اہل مدینہ میں شمار ہوتے ہیں، پھر بطریق عیاش سند بحوالہ ابو سائب ایک صحابی کی روایت نقل کی ہے، فرمایا: ایک شخص نے آ کر نماز پڑھی اور رسول اللہ صلی اللہ علیہ وسلم اسے دیکھ رہے تھے جب وہ نماز مکمل کر چکا آپ نے تین بار فرمایا: جاؤ نماز پڑھو۔ (حدیث)(2) ابونعیم ان کا تعاقب کرتے ہوئے لکھتے ہیں: محفوظ اسحاق بن عبد اللہ بن ابی طلحہ کی روایت ہے۔ داؤد بن قیس اور محمد بن غیلان سب علی بن یحییٰ سے وہ اپنے والد سے وہ اپنے چچا رفاعہ بن رافع کے حوالہ سے نقل کرتے ہیں۔ ممکن ہے اس حدیث میں علی بن یحییٰ کے دو شیخ (استاد) ہوں۔","",{"fn":"(1) اسد الغابہ (۵۹۳۱)\n(2) ابوداؤد کتاب الصلاۃ (۸۵۷، ۸۵۸) ترمذی کتاب الصلاۃ (۳۰۲) نسائی کتاب السہو (۱۳۱۲) ابن ماجہ کتاب الطہارۃ (۴۹۰) مسند احمد (۳۴۰/۴) جامع المسانید (۹۶/۱۴)"}],[8590,"§۹۹۷۹ ۔ ابوسبرہ الجعفی(1)\nوہی یزید بن مالک۔ محمد بن عبد اللہ بن نمیر نے ان کا نام نقل کیا ہے اور ان کی حدیث ان کے بیٹے عبدالرحمن بن سبرہ کے حالات میں بیان ہو چکی ہے۔","",{"fn":"(1) اسد الغابہ (۵۹۳۳) تجرید (۱۷۰/۱)"}],[8591,"§۹۹۸۰ ۔ ابوسبرہ بن حارث(1)\nبقول بعض: ابو سبرہ سین کے بجائے ھاء۔ الف میں ان کا ذکر ہو چکا ہے اور بعض کا انہیں ابواسیرہ کا کہنا بھی بیان ہوا ہے۔","",{"fn":"(1) تجرید (۱۷۱/۱)"}],[8592,"§۹۹۸۱ ۔ ابوسبرہ بن ابی رہم(1)\nبن عبد العزی بن ابی قیس بن عبدود۔۔۔ قرشی عامری۔ اسلام کی طرف سبقت کرنے والوں میں سے ہیں۔ دوسری مرتبہ کی ہجرت میں حبشہ گئے ان کے ساتھ ام کلثوم بنت سہیل بن عمرو بھی تھیں۔ سب کا اتفاق ہے کہ بدر میں شریک ہوئے والدہ کا نام برد بنت عبدالمطلب ہے جو رسول اللہ صلی اللہ علیہ وسلم کی پھوپھی ہیں۔ اور ابو سلمہ بن عبد الاسد کے ماں شریک بھائی ہیں۔ زبیر بن بکار کا بیان ہے رسول اللہ صلی اللہ علیہ وسلم کی وفات کے بعد مکہ مقیم ہو گئے جہاں سیدنا عثمان رضی اللہ عنہ کی خلافت میں فوت ہوئے۔ زبیر لکھتے ہیں: ہمیں معلوم نہیں کہ ان کے علاوہ کوئی بدری صحابی مکہ آکر بس گیا ہو۔","",{"fn":"(1) اسد الغابہ (۵۹۳۵) استیعاب (۳۰۲۵)"}],[8593,"§۹۹۸۲ ۔ ابوسبرہ (بے نسب)(1)\nابن مندہ نے ان کا ذکر کیا ہے اور بطریق یوسف بن سفر روایت کی ہے کہ اوزاعی نے فرمایا مجھ سے قزعہ نے بیان کہ ہمارے پاس صحابی رسول صلی اللہ علیہ وسلم ابوسیرہ تشریف لائے۔ میں نے ان سے عرض کی: اللہ آپ پر رحم فرمائے مجھے نبی صلی اللہ علیہ وسلم سے سنی ہوئی کوئی حدیث سنائیے۔ انہوں نے فرمایا: میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا ہے: ”جس نے فجر کی نماز پڑھ لی وہ اللہ تعالیٰ کی ذمہ داری میں ہے سو اللہ تعالیٰ سے ڈرو وہ تم سے اپنی ذمہ داری کا مطالبہ کرے۔“(2)","",{"fn":"(1) اسد الغابہ (۵۹۳۷) تجرید (۱۷۱/۱)\n(2) جامع المسانید (۱۰۰/۱۴) اسد الغابہ (۴۶۲/۴)"}],[8594,"§۹۹۸۳ ۔ ابوسبرہ الجہنی\nمعبد بن عوسجہ، تذکرہ ہو چکا ہے۔"],[8595,"§۹۹۸۴ ۔ ابوسبرہ\nعیسیٰ بن سبرہ کے دادا۔ حبان میں ذکر ہوا ہے۔ بغوی فرماتے ہیں: میرے خیال میں مدینہ کے رہائشی ہیں، پھر ان کی حدیث بطریق ابن انیس، بواسطہ عیسیٰ بن سبرہ انہوں نے اپنے والد سے بحوالہ اپنے دادا نقل کی۔"],[8596,"§۹۹۸۵ ۔ ابوالسبع بن عبدقیس انصاری\nبدر میں شریک تھے، ان کا نام ذکوان ہے، پہلے بیان ہو چکا ہے۔"],[8597,"§۹۹۸۶ ۔ ابوسرَوعہ نوفلی(1)\nعقبہ ابن عامر ہیں، یہ اکثریت کا قول ہے ناموں میں ان کا ذکر ہوا ہے۔ بقول بعض ان کے بھائی ہیں، ان کا نام رث ہے یہ عدوی کا قول ہے ان کا بیان ہے: فتح مکہ میں مسلمان ہوئے، ایسا ہی زبیر وغیرہ کا کہنا ہے۔ سروعہ کے سین میں لاف ہے، اکثریت فتح (زبر) کی قائل ہے ایک قول زیر کا ہے را ساکن ہے ادھر حمیدی کا گمان ہے کہ انہوں نے الدارقطنی کے قلم عین پر پیش لکھا دیکھا ہے۔ شاید عدم نقطہ (نقطہ نہ ہونے) کی علامت تھی جسے وہ پیش سمجھ بیٹھے۔","",{"fn":"(1) اسد الغابہ (۵۹۳۹) استیعاب (۲۰۲۸) تجرید (۱۷۱/۲)"}],[8598,"§۹۹۸۷ ۔ ابوشریحہ(1)\nبروزن عظیمہ، حذیفہ بن اسید، پہلے ذکر ہو چکا ہے۔","",{"fn":"(1) اسد الغابہ (۵۹۴۰) استیعاب (۳۰۲۹) تجرید (۱۷۱/۲)"}],[8599,"§۹۹۸۸ ۔ ابوسعاد جہنی(1)\nبقول بعض: ان کا نام جابر بن اسامہ ہے، ناموں میں ذکر ہو چکا ہے کہ ابن ماکولا(2) نے ان کا نام بتایا ہے۔ ایک قول کا یہ بعد والے ہیں۔","",{"fn":"(1) اسد الغابہ (۵۹۴۲) استیعاب (۳۰۳۰) تجرید (۱۷۱/۲)\n(2) الاکمال (۳۰۶/۴)"}],[8600,"§۹۹۸۹ ۔ ابوسعاد الحمصّی(1)\nابوزرعہ نے کتاب الزھد میں روایت نقل کی ہے کہ ابن ابی عوف کا قول ہے: سیدنا ابودرداء ابوسعاد کے پاس سے گزرے، جو صحابی رسول صلی اللہ علیہ وسلم تھے۔ ابو سعاد فرمانے لگے: سبحان اللہ! نہ کچھ بیچتے ہیں اور نہ خریدتے ہیں۔ ابودرداء بولے: ”جس نے اپنی دنیا کی چیزیں جمع کیں اس نے اپنی آخرت کو نقصان پہنچایا“۔ ابو عمر نے ان میں اور جھنی میں فرق کیا ہے کہ یہ حمص فروکش ہوئے اور ان کی حدیث نقل کی۔","",{"fn":"(1) اسد الغابہ (۵۹۴۲) تجرید (۱۷۱)"}],[8601,"§۹۹۹۰ ۔ ابوسعاد(1)\nیہ جہینہ کے ہیں۔ روح بن قاسم بواسطہ اسمعیل بن امیہ اسی سند سے بحوالہ عقبہ بن عامر روایت کرتے ہیں۔ میں کہتا ہوں: عقبہ بن عامر مشہور صحابی ہیں جن کا تذکرہ ناموں میں ہوا۔ اس کی کنیت کے بارے میں اختلاف ہے، ابوحماد اکثریت کا قول ہے۔ ابو عمر/ابوعامر/ابوسعاد وغیرہ مختلف اقوال ہیں۔ واللہ اعلم","",{"fn":"(1) اسد الغابہ (۵۹۴۱) تجرید (۱۷۱/۲)"}],[8602,"§۹۹۹۱ ۔ ابوسعدان (شامی، بے نام و نسب)(1)\nابو عمر نے ان کا ذکر کیا کہ محمول نے ان سے ہجرت کے بارے میں مرفوع حدیث روایت کی ہے۔(2) ذہبی رحمہ اللہ کا قول ہے: اس کی سند کمزور ہے۔","",{"fn":"(1) اسد الغابہ (۵۹۴۹) استیعاب (۳۰۳۵) تجرید (۱۷۲/۱)\n(2) اسد الغابہ (۱۶۲)"}],[8603,"§۹۹۹۲ ۔ ابوسعد انصاری ثم حارثی\nمحیصہ بن مسعود۔"],[8604,"§۹۹۹۳ ۔ ابوسعد عیاض بن زہیر الفہری"],[8605,"§۹۹۹۴ ۔ ابوسعد سلمہ بن اسلم بن حریش\nسلمہ بن اسلم بن حریش، ان سب کا ذکر ناموں میں ہوا ہے۔"],[8606,"§۹۹۹۵ ۔ ابوسعد الخیر(1)\nبقول بعض: ابوسعید الخیر۔ ابن السکن: صحابی ہیں۔ بقول بعض: نام عمرو ہے۔ ابواحمد الحاکم: مجھے ان کا نام ونسب معلوم نہیں۔ پھر بیان کرتے ہیں: یہ ابوسعید الانماری ہیں، حالانکہ ایسا نہیں۔ کیونکہ ان کی دو حدیثیں اس حدیث کے علاوہ ہیں جس میں انماری کے حالات میں اختلاف ہے۔ بلکہ یہ ابوسعد یا ابوسعید ہیں چنانچہ ترمذی ”العلل المفردہ“ ابن ابی داؤد ”الصحابہ“ میں اور ابواحمد الحاکم ان سے ایک اور طریق سے پھر یہ سب بطریق ابو فروہ رہاوی، معقل کندی، عبادہ بن نسی بحوالہ ابوسعید روایت کرتے ہیں۔ فرمایا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”اللہ تعالیٰ نے رات میں روزہ رکھنا فرض نہیں کیا ہے جس نے رکھا اس نے مشقت کی اس کا کوئی اجر نہیں ہے“۔(2) یہی روایت دولابی نے الکنی میں ایک اور سند سے بحوالہ ابوفروہ نقل کی ہے کہ ابوسعید الخیری سے مروی ہے، حاکم کی روایت میں ہے ابوسعد الخیری سے منقول ہے ابن مندہ نے یہ روایت نقل کر کے کہا: غریب ہے، ہمیں اسی سند سے معلوم ہے۔ ترمذی کا قول ہے: میں نے محمد یعنی امام بخاری رحمہ اللہ سے پوچھا تو انہوں نے فرمایا: میں اس عبادہ بن نسی سے ناواقف ہوں جس نے ابو سعد الخیر سے یہ حدیث سنی ہے اور دولابی الکنی میں بطریق ابو فراس شعبانی روایت کرتے ہیں کہ یہ لوگ امیر معاویہ کے دور میں غزوہ قسطنطنیہ میں تھے اور یزید بن شجرہ ہمارے امیر تھے۔ ہمارے پاس سے ابوسعد الخیر صحابی رسول صلی اللہ علیہ وسلم گزرے پھر ایک واقعہ نقل کیا۔ ابوسعد الخیر نے فرمایا: میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا ہے: ”جن چیزوں کو آگ پر پکایا گیا ہو ان کے کھانے سے وضو کر لیا کرو“۔۔۔۔ (حدیث)(3) اسے امام حاکم رحمہ اللہ نے اسی سند سے نقل کیا ہے، اس کے سیاق میں فرماتے ہیں: میں ابوسعد الخیر کے پاس تھا، اور پھر فرماتے ہیں: ابوسعید الخیر۔ اکثریت ابوسعد بلا شک کہتی ہے۔","",{"fn":"(1) اسد الغابہ (۵۹۴۴) جمع الجوامع (۴۹۶۹) تجرید (۱۷۲/۲)\n(2) کنز العمال (۲۳۹۲۵) جمع الجوامع (۴۹۶۹)\n(3) المعجم الکبیر (۷۷۶/۲۲) مجمع الزوائد (۲۴۹/۱۰) الکنی للدولابی (۳۵/۱) جامع المسانید (۱۱۹/۱۴)"}],[8607,"§۹۹۹۶ ۔ ابوسعد انصاری زرقی(1)\nسعید بن عبدالعزیز اور حاکم کا قول ہے: صحابی ہیں، ابن ماجہ بطریق یونس بن میسرہ یہ روایت کرتے ہیں کہ ہم لوگ ابوسعد زرقی صحابی رسول کے ساتھ قربانی کے جانور خریدنے گئے۔ پھر وہ حدیث ذکر کی۔(2) ابن ابی حاتم بحوالہ اپنے والد ان کے صحابی ہونے میں متردد ہے۔ طبرانی کی روایت میں یونس کے مذکورہ طریق سے مروی ہے میں ابوسعد الخیر کے ساتھ نکلا، اگر یہ روایت محفوظ ہے تو یہ سابقہ شخصیت ہیں، ابوسعید اسامہ بنت یزید کے خاوند کے حالات میں ان کا ذکر ہوگا۔","",{"fn":"(1) اسد الغابہ (۵۹۴۳) تجرید (۱۷۲/۲)\n(2) اسد الغابہ (۴۶۵/۴)"}],[8608,"§۹۹۹۷ ۔ ابوسعد الانماری\nبقول بعض: ابوسعید، تذکرہ ہونا ہے۔"],[8609,"§۹۹۹۸ ۔ ابوسعد ساعدی(1)\nابن ابی داؤد نے اور ان کے اتباع میں ابن شاہین نے صحابہ میں ان کا ذکر کیا ہے، اور ان سے بطریق ابو عمرو اوزاعی، یحییٰ بن ابی کثیر، قتادہ، ابی قتادہ روایت کی ہے کہ سعد ساعدی نے ایک شخص کو عصر کے بعد نفل پڑھتے دیکھا تو فرمایا: اس وقت (نماز نفل) نہ پڑھو، کیونکہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: ”عصر کی نماز کے بعد (نفل) نماز نہ پڑھا کرو“۔(2) الدارقطنی نے العلل میں ان کا نام درست لکھا ہے ابواسید ساعدی، ابن ابی داؤد ان کے بارے وہم ہوا ہے۔","",{"fn":"(1) اسد الغابہ (۵۹۴۶) تجرید (۱۷۲/۲)\n(2) جامع المسانید (۱۲۰/۱۴) اسد الغابہ (۴۶۵/۴)"}],[8610,"§۹۹۹۹ ۔ ابوسعد بن فضالہ انصاری(1)\nبقول بعض: ابن ابی فضال۔ ایک قول ہے: ابوسعید بن فضال بن ابی فضال۔ ابن سعد نے اہل خندق کے طبقہ میں ان کا ذکر کیا ہے۔ ابن السکن فرماتے ہیں: غیر معروف ہیں۔ ترمذی، ابن ماجہ، ابن خزیمہ، ابن حبان اور حاکم نے بطریق عبدالحمید بن جعفر، انہوں نے اپنے والد سے بواسطہ زیاد بن مینا بحوالہ ابوفضالہ جو صحابی ہیں روایت کی ہے علی بن مدینی کا قول ہے: اس کی سند بہتر ہے، اکثریت کے ہاں یہ نام عین کے سکون سے لکھا ہے، جس پر ابواحمد الحاکم کا بھروسہ ہے، فرماتے ہیں: یہ صحابی ہیں لیکن مجھے ان کا نام ونسب یاد نہیں۔ ابن ماجہ میں دونوں طرح ہے۔ ترمذی میں یاء کی زیادتی سے لکھا ہے تجرید میں ذہبی لکھتے ہیں: ابوسعد بن ابی فضالہ کی، ابواحمد کی کتاب الکنی میں ایک متصل حدیث ہے، پھر فرماتے ہیں: ابوسعید بن فضالہ۔ بقول بعض: ابوسعد، ترمذی نے ریاء میں ان کی اسی طرح ایک حدیث نقل کی ہے اور انہیں دو شخص قرار دیا ہے، باوجود یکہ جو حدیث حاکم نے روایت کی وہی ترمذی نے نقل کی ہے۔ اسی طرح حاکم کی کتاب الکنی میں عین کے سکون سے ہے، بغوی الکنی میں لکھتے ہیں: ابوسعد بن ابی فضالہ انصاری، مدینہ کے رہائشی تھے پھر ان کی حدیث بیان کی۔ فرمایا: میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: ”اللہ تعالیٰ جب اولین و آخرین کو قیامت کے روز جس میں کوئی شک نہیں جمع فرمائے گا تو ایک اعلان کرنے والا اعلان کرے گا جس نے کسی کو کسی عمل میں شریک کیا ہے وہ اس سے اس عمل کا ثواب مانگے اللہ تعالیٰ شریکوں کے شرک سے بے نیاز ہے۔“(2) ابن ابی خیثمہ نے ایسا ہی نقل کیا ہے، فوائد صولی میں لکھا ہے: یحیی بن معین اس سند سے بحوالہ ابوسعید بن فضالہ بن ابی فضالہ روایت کرتے ہیں۔ حافظ ابن عساکر کا قول ہے: یہ وہم ہے، درست پہلی سند ہے۔ ایسا ہی امام احمد نے محمد بن ابی بکر سے نقل کیا ہے۔ ان کی سہیل بن عمرو سے روایت ہے، اسے بھی ابن سعد نے نقل کیا ہے۔","",{"fn":"(1) اسد الغابہ (۵۹۴۷) تجرید (۱۷۳/۲)\n(2) ترمذی کتاب التفسیر باب من سورۃ الکہف (۳۱۵۴) ابن ماجہ کتاب الزھد باب الریاء والسمعۃ (۴۲۰۳) مسند احمد (۴۶۶/۳)"}],[8611,"§۱۰۰۰۰ ۔ ابوسعد بن وہب نضری(1)\nاز بنی نضیر، جو قریظہ کے بھائی ہیں۔ مغازی میں ابن اسحاق کا قول ہے: بنی نضیر میں سے سوائے دو آدمیوں کے کوئی مسلمان نہیں ہوا۔ یامین بن عمرو بن کعب اور ابوسعد بن وہب، ان دونوں نے اپنے مال محفوظ کر لیے۔ پھر ابن سعد نے بسند واقدی ان کی حدیث نقل کی ہے، فرمایا: میں اس وقت موجود تھا جب رسول اللہ صلی اللہ علیہ وسلم نے مہروز کے پانی کی تقسیم کی تھی کہ اوپر والا ٹخنوں تک پہنچنے پر پانی کو روکے، پھر چھوڑ دے۔(2) ابو عمر کے کلام میں ہے وہ معرکہ قریظہ کے روز رسول اللہ صلی اللہ علیہ وسلم کے پاس اتر آئے تھے۔ یہ غلط ہے جس کا تعاقب رشاطی نے کیا ہے کیونکہ بنی نضیر کا واقعہ بنی قریظہ کے واقعہ سے بہت مدت پہلے کا ہے۔","",{"fn":"(1) اسد الغابہ (۵۹۴۸) تجرید (۱۷۳/۲)\n(2) ابوداؤد کتاب الاقضیۃ باب ابواب من القضاء (۳۶۳۸) ابن ماجہ کتاب الرھون باب الشرب فی الادویۃ (۲۴۸۱) جامع المسانید (۱۱۶/۱۴) اسد الغابہ (۴۶۶/۴)"}],[8612,"§۱۰۰۰۱ ۔ ابوسعد انصاری(1)\nابن ابی فدیک نے ان کی حدیث بواسطہ یحیی بن ابی خالد بحوالہ ابوسعد نقل کی ہے۔ ایسا ہی ابوعمر کا مختصر قول ہے۔ ابن مندہ فرماتے ہیں: اسے محمد بن اسمعیل بن فدیک نے یحییٰ بن ابی خالد سے بواسطہ ابن ابی سعد انصاری بحوالہ اپنے والد نبی صلی اللہ علیہ وسلم سے نقل کیا ہے: ”ندامت و پشیمانی بھی توبہ ہے۔“(2) میں کہتا ہوں: یہ روایت حکیم ترمذی حنفی نے ”نوادر الاصول“ میں بطریق ابن ابی فدیک اسی سند سے ان الفاظ میں نقل کی ہے: ”گناہ سے توبہ کرنے والا ایسا ہے جیسا بے گناہ اور ندامت خود توبہ ہے“۔ ابو نعیم اعتماد سے لکھتے ہیں: ”یہ پہلے والے نفری ہی ہیں“۔ جو بہتر نہیں، اور ابوبکر نے یقین سے لکھا ہے کہ انہوں نے ہی یہ حدیث نقل کی ہے: ”قربانی کا بہترین جانور کالی ناک والا دنبہ ہے“۔ یہ بھی صحیح نہیں۔","",{"fn":"(1) اسد الغابہ (۵۹۴۳) تجرید (۱۷۲/۲)\n(2) مجمع الزوائد (۱۹۹/۱۰) المعجم الکبیر (۱۷۷۵/۲۲) حلیۃ الاولیاء (۳۹۸/۱۰)"}],[8613,"§۱۰۰۰۲ ۔ ابوسعد بن اوس(1)\nبن معلی ابن لوذان بن حارثہ بن عدی انصاری اوسی۔ طبری نے ذیل میں ان کا ذکر کیا ہے کہ ۹۴ ھ میں فوت ہوئے، ان کا نام حارث ہے۔","",{"fn":"(1) اسد الغابہ (۵۹۵۵) تجرید (۱۷۳/۲)"}],[8614,"§۱۰۰۰۳ ۔ ابوسعید خدری\nسعد بن مالک بن سنان۔"],[8615,"§۱۰۰۰۴ ۔ ابوسعید عبشمی\nعبدالرحمن بن سمرہ۔"],[8616,"§۱۰۰۰۵ ۔ ابوسعید سعیدی\nخالد بن احیہ سعد بن عاص۔"],[8617,"§۱۰۰۰۶ ۔ ابوسعید انصاری\nیزید بن ثابت بن ودیعہ۔"],[8618,"§۱۰۰۰۷ ۔ ابوسعید مخزومی\nالمسیب ابن حزن بن ابی وہب۔"],[8619,"§۱۰۰۰۸ ۔ ابوسعید مخزومی\nعمرو بن حریث۔"],[8620,"§۱۰۰۰۹ ۔ ابوسعید کاتب وحی\nزید بن ثابت انصاری خزرجی۔"],[8621,"§۱۰۰۱۰ ۔ ابوسعید رافع بن المعلی بدری\nان سب حضرات کا تذکرہ ناموں میں ہو چکا ہے۔ بقول بعض: ابوسعید بن معلی کا نام حارث بن اوس بن معلی ہے۔ ایک قول ہے: حارث بن نفیح، بقول بعض: یہ سابقہ شخصیت کا نام ہے۔"],[8622,"§۱۰۰۱۱ ۔ ابوسعید بن معلی انصاری\nدوسرے ہیں۔ امام بخاری رحمہ اللہ نے ان کی حدیث نقل کی ہے جو بروایت حفص بن عاصم ان سے مروی ہے، ان سے عبید بن حنین بھی روایت کرتے ہیں۔ بقول ابو عمر: جس نے انہیں رافع بن معلی کہا اسے وہم ہوا ہے کیونکہ وہ بدر میں شہید ہوئے تھے۔ یہ بات حارث بن نفیح بن معلی کے بارے میں سب سے صحیح ہے۔ مؤرخین نے ان کی تاریخ وفات ۷۴ ھ یا ۷۵ ھ لکھی ہے۔ ان کا کہنا ہے: وہ چونسٹھ(۶۴) سال زندہ رہے۔(1) میں کہتا ہوں: یہ غلط ہے، کیونکہ اس سے یہ لازم آتا ہے ان کا یہ واقعہ نبی صلی اللہ علیہ وسلم کے ساتھ بچپنے میں پیش آیا تھا جبکہ حدیث کا سیاق اس کے خلاف ہے۔ اس واسطے کہ صحیح میں ان کی حدیث میں ہے میں نماز پڑھ رہا تھا نبی صلی اللہ علیہ وسلم کا وہاں سے گزر ہوا، آپ صلی اللہ علیہ وسلم نے مجھے بلایا، میں آپ کے پاس اس وقت تو حاضر نہ ہو سکا نماز پڑھنے کے بعد آ گیا۔ (حدیث) ان کی ایک اور حدیث بھی ہے جس کا آغاز اس طرح ہے: ”ہم لوگ بازار جاتے“۔ ابوعمر کا قول ہے: ان کی والدہ کا نام امیمہ بنت قرط بن خنساء ہے۔ بنی سلمہ سے تعلق رکھتی ہیں۔","",{"fn":"(1) بخاری کتاب تفسیر القرآن باب ما جاء فی فاتحۃ الکتاب (۴۴۷۴) کتاب فضائل القرآن باب (۵۰۰۶) ابوداؤد کتاب الصلاۃ باب ما جاء فی فاتحۃ الکتاب (۱۴۵۸) نسائی کتاب الافتتاح (۹۱۲) ابن ماجہ کتاب الادب باب ثواب القرآن (۳۸۷۵) مسند احمد (۴۵۰/۳) (۲۱۱/۴)"}],[8623,"§۱۰۰۱۲ ۔ ابوسعید انصاری(1)\nاسماء بنت یزید بن السکن کے شوہر۔(2) ان کا نام سعید بن عمارہ/عمارہ بن سعید اور عامر بن مسعود بتایا جاتا ہے۔ حاکم نے آخری قول کو فضول لکھا ہے اور کہا ہے عامر بن مسعود دوسرے ہیں جو تابعی ہیں، ان کی کنیت ابوسعید ہے، ابن مندہ کی روایت ہے کہ ابوسعید انصاری مدینہ کے محاصرے کے دن مروان بن الحکم کے پاس سے گزرے تو وہ پچھڑے ہوئے تھے۔ آپ نے فرمایا: ابن الزرقاء اگر مجھے معلوم ہوتا کہ تم ہی وہ (فتنہ پرداز) ہو تو میں تمہارے خلاف چڑھ دوڑتا۔ تو عبد الملک بن مروان نے اس بات کی وجہ سے ان سے بغض رکھنا شروع کر دیا، جب وہ خلیفہ بنا تو انہیں بلا بھیجا، آپ نے فرمایا: ”مجھے اس بارے میں نبی صلی اللہ علیہ وسلم کی وصیت یاد ہے“۔ اس نے پوچھا: وہ کیا ہے؟ آپ نے فرمایا: ”ان کے محسنوں کی بات قبول کرو اور ان کے بروں سے درگزر کرو“۔(3) چنانچہ اس نے انہیں چھوڑ دیا۔ بقول بعض: یہ وہی ابوسعید زرقی ہیں جن کا تذکرہ ہوتا ہے۔ جس پر المزی کا اعتماد ہے، جبکہ ابن مندہ نے دونوں میں فرق کو یقینی کہا ہے، شاید یہی زیادہ درست ہے۔","",{"fn":"(1) نسائی کتاب المساجد (۳۹) باب صلاۃ الذی یمر علی المسجد (۷۲۸)\n(2) اسد الغابہ (۵۹۵۲) استیعاب (۳۰۴۰) تجرید (۱۷۲/۲)\n(3) المعجم الکبیر (۷۷۷/۲۲) مجمع الزوائد (۳۶/۱۰) جامع المسانید (۱۲۸/۱۴) اسد الغابہ (۴۶۷/۴)"}],[8624,"§۱۰۰۱۳ ۔ ابوسعید سعد بن عامر(1)\nبن مسعود زرقی۔ ابن السکن نے ان کا ذکر کیا ہے اور یہ روایت نقل کی ہے کہ عبدالملک بن مروان نے ابوسعید، سعد بن عامر زرقی کی طرف پیام بھیجا۔ بقول بعض ان کی نبی صلی اللہ علیہ وسلم سے ملاقات ہوئی اور آپ سے ہدی (قربانی حج) کے بارے میں پوچھا اور سیدہ عائشہ رضی اللہ عنہا سے روایت کی ہے۔ نسائی بطریق شعبہ بحوالہ ابوسعید زرقی عزل کی حدیث نقل کرتے ہیں۔ ان سے عبداللہ بن مرہ، یونس بن میسرہ اور مکحول شامی روایت کرتے ہیں۔ بقول سعید بن عبد العزیز، صحابی ہیں۔ ایک قول ہے: انہی کو سعید الخیر کہا جاتا ہے۔","",{"fn":"(1) ۹۹۹۱ میں ان کا تذکرہ ہو چکا ہے۔"}],[8625,"§۱۰۰۱۴ ۔ ابوسعید الانماری(1)\nبقول بعض: ابوسعد۔ خلیفہ کا قول ہے: یہ انمار مذحج سے تعلق رکھتے ہیں۔ ابواحمد فرماتے ہیں: مجھے ان کا نام ونسب یاد نہیں، اہل شام کے محدثین ان کی حدیث روایت کرتے ہیں۔ پھر ان کی یہ حدیث نقل کی کہ عبدالملک بن مروان نے کہا: مجھ سے ابوسعید انماری نے بیان کیا کہ انہوں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: ”اللہ تعالیٰ نے مجھ سے وعدہ کیا ہے کہ میری اُمت کے ستر ہزار افراد بغیر حساب جنت میں داخل فرمائے گا۔ پھر ان میں سے ہر ہزار ستر ہزار کی شفاعت کرے گا اور میرے لیے تین مٹھیاں (جیسا اس کے شایان شان ہے) بھرے گا“۔(2) قیس کا قول ہے: میں نے ابوسعید کے کپڑے پکڑ کر پوچھا: کیا واقعی آپ نے رسول اللہ صلی اللہ علیہ وسلم سے سنا ہے؟ انہوں نے فرمایا: ہاں! میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا ہے اور میرے دل نے یاد رکھا ہے۔ آپ نے تین بار ایسا کیا۔ ابوسعید کہتے ہیں: میں نے رسول اللہ صلی اللہ علیہ وسلم کے پاس بیٹھے بیٹھے اس کا حساب لگایا تھا۔ فرمایا: اللہ اکبر یہ تو ہمارے مہاجرین کو شامل ہے اور تھوڑی سی ہم اپنے اعرابیوں سے مدد طلب کر لیں گے۔ میں کہتا ہوں: اس کی سند صحیح ہے اور سارے صحیح کے رجال میں سوائے قیس بن حجر شامی کے جو ثقہ راوی ہیں۔ قیس بن حجر الکندی نے ولید بن عبدالملک سے بیان کیا کہ ابوسعید الخیر نے ان سے بیان کیا اور طبرانی نے بطریق ابوتوبہ بحوالہ معاویہ نقل کی ہے، فرمایا: ابوسعید انماری۔ بقول بعض قیس بن حارث۔ دوسری سند سے زبیدی سے بواسطہ عبداللہ بن عامر فرمایا: قیس بن حارث سے مروی ہے کہ ابوسعید الخیری انصاری ان سے بیان کرتے ہیں پھر اس کا ایک گوشہ نقل کیا۔ اس اختلاف کی وجہ سے اس سند کا صحیح ہونا غیر یقینی ہے۔(3) ابن ماکولا نے ان کا اتباع کیا ہے۔ یہ ابو سعد الخیر ہیں ان کا نام بخجیر ہے۔ خطیب سے پہلے یہ قول ابوالحسن بن سمیع نے طبقات الحمصیبین میں لکھا ہے۔ اسی طرح انہوں نے شام کے رہائشی صحابہ رضی اللہ عنہم میں ان کا ذکر کیا ہے، اسی طرح ابن جوصاء نے ان کی حدیث نقل کی ہے۔","",{"fn":"(1) اسد الغابہ (۵۹۵۴) تجرید (۱۷۲/۲)\n(2) الاحاد والمثانی (۲۲۵/۴) (۲۹۷/۵)\n(3) الاکمال (۴۲/۱)"}],[8626,"§۱۰۰۱۵ ۔ ابوسعید (بے نسب)(1)\nحاکم نے انہیں سابقہ شخصیت سے الگ ذکر کیا ہے، پھر حارث بن محمد اشعر سے بحوالہ ابوسعید کنیت والے شخص روایت کی ہے، فرمایا: میں بالائی حصے سے مدینہ آیا، میں ابھی پہنچا بھی نہ تھا کہ بھوک کی وجہ سے بے حد تھک گیا۔ اسی دوران جب میں مدینہ کے کسی بازار میں چل رہا تھا میں نے سنا ایک شخص اپنے ساتھی سے کہہ رہا تھا: کیا تمہیں معلوم ہے آج رات نبی صلی اللہ علیہ وسلم کی مہمان نوازی ہوئی ہے۔ میں نے جب مہمان نوازی کا سنا اور بھوک سے میری حالت غیر ہوتی جارہی تھی تو میں آپ کے پاس آ گیا میں نے عرض کی: اللہ کے رسول! کیا آج رات آپ کی ضیافت تھی؟ آپ صلی اللہ علیہ وسلم نے فرمایا: ہاں۔ میں نے عرض کی: کیا چیز تھی؟ آپ صلی اللہ علیہ وسلم نے فرمایا: ایک برتن کھانا تھا۔ میں نے عرض کی: اس کا باقیماندہ کیا ہوا؟ آپ نے فرمایا: اٹھا لیا گیا۔ میں نے عرض کی: آپ کی ابتدائی اُمت میں ہوگا یا آخری میں؟ آپ نے فرمایا: اول میں اور تم گروہ در گروہ میرا اتباع کرو گے۔ یعنی بعض بعض سے مل(2) جائیں گے۔ یہی روایت ابن مندہ نے دوسری سند کے ذریعہ بحوالہ ابن جابر نقل اور اس کے الفاظ نہیں بیان کیے اس کے رجال ثقہ ہیں۔","",{"fn":"(1) اسد الغابہ (۵۹۵۷) استیعاب (۳۰۳۷) تجرید (۱۷۳/۲)\n(2) کنز العمال (۳۱۳۷۹) اسد الغابہ (۴۶۹/۴)"}],[8627,"§۱۰۰۱۶ ۔ ابوسعید بن زید(1)\nمسند میں ایسا ہی لکھا ہے۔ شعبی سے مروی ہے کہ میں ابوسعید بن زید کے بارے میں گواہی دیتا ہوں کہ رسول اللہ صلی اللہ علیہ وسلم کے پاس سے ایک جنازہ گزرا تو آپ کھڑے ہو گئے۔ طبرانی کی روایت میں ہے ابوسعید خدری کے بارے میں گواہی دیتا ہے۔ ابن الاثیر(2) کا قول ہے: لگتا ہے یہ زیادہ صحیح ہے۔ میں کہتا ہوں: ایسا نہیں، بلکہ جو وہ سمجھے ہیں ان کا وہم ہے۔ بغوی نے عبداللہ بن احمد سے نقل کیا ہے جیسا کہ قطیعی کے ہاں مرقوم ہے پھر مجھے مسند سعید بن زید (جو عشرہ مبشرہ میں سے ایک ہیں) میں اور مسند بزار میں ایک حدیث مل گئی۔","",{"fn":"(1) اسد الغابہ (۴۶۹/۴)\n(2) اسد الغابہ (۵۹۵۳) تجرید (۱۷۳/۲)"}],[8628,"§۱۰۰۱۷ ۔ ابوسعید(1)\nبقول بعض: ابو سعد، نبی صلی اللہ علیہ وسلم سے روایت کرتے ہیں: ”نیکی اور صلہ رحمی، پڑوسی سے اچھا سلوک شہروں کی آبادی اور عمر میں اضافہ کا باعث ہے۔“(2) بقول ابو عمر: ان سے ابو ملیکہ نے روایت کی ہے، جس میں تامل ہے۔","",{"fn":"(1) اسد الغابہ (۵۹۵۸) تجرید (۱۷۳/۲)\n(2) اسد الغابہ (۴۶۹/۴)"}],[8629,"§۱۰۰۱۸ ۔ ابوسعید عبسّی\nواقدی کی نضر بن سعید عبسی سے وہ بواسطہ اپنے والد بحوالہ اپنے دادا روایت کرتے ہیں، فرمایا: نبی صلی اللہ علیہ وسلم نے بنی عبس کا شعار عشرہ قرار دیا ہے۔"],[8630,"§۱۰۰۱۹ ۔ ابوسفیان بن حارث(1)\nبن عبد المطلب بن ہاشم ہاشمی۔ رسول اللہ صلی اللہ علیہ وسلم کے چچا زاد اور رضاعی بھائی۔ دونوں کی رضاعی والدہ حلیمہ سعدیہ ہیں۔ بقول ابن المبارک اور ابراہیم بن المنذر ان کا نام مغیرہ تھا۔ بقول بعض: ان کی کنیت ہی ان کا نام ہے۔ مغیرہ ان کے بھائی ہیں، رسول اللہ صلی اللہ علیہ وسلم کے مشابہ تھے، عبداللہ بن امیہ کے ساتھ ان کا ذکر ہوا ہے۔ حاکم کی روایت ہے: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”ابوسفیان بن حارث جنتی نوجوانوں کے سردار ہیں“۔(2) فرماتے ہیں: ان کے سر میں رسولی تھی جسے حجام نے ان کا سر مونڈتے کاٹ دیا تو خون بہنے سے فوت ہو گئے۔ لوگ کہتے ہیں ان کی شہادت کی موت ہوئی ہے۔ یہ مرسل روایت ہے اس کے رجال ثقہ ہیں۔ ابوسفیان رسول اللہ صلی اللہ علیہ وسلم کی ایذاء رسانی اور آپ کی برائی بیان کرنے والوں میں سے تھے اور مسلمانوں کو تکلیف پہنچاتے تھے جس کی طرف سیدنا حسان بن ثابت رضی اللہ عنہ نے اپنے مشہور قصیدے میں اشارہ کیا ہے: ”تم نے (میرے محبوب) محمد کی برائی کی اور میں تمہیں اس کا جواب دیتا ہوں، جس کی اللہ تعالیٰ کے ہاں جزاء ہے“۔ بقول بعض: سیدنا علی رضی اللہ عنہ نے انہیں سمجھایا کہ رسول اللہ صلی اللہ علیہ وسلم کے روبرو جا کر کہو: ”اللہ کی قسم! اللہ تعالیٰ نے آپ کو ہم پر بڑی فضیلت بخشی“۔ چنانچہ انہوں نے ایسا ہی کیا، آپ نے ان کا عذر قبول کیا اور فرمایا: ”آج تم پر کوئی گرفت نہیں“۔ جس پر ابوسفیان بے ساختہ بول اٹھے: ش ”آپ کی زندگی کی قسم! جس دن میں محمد کے لشکر کی مغلوبیت کے لیے اور لات کے لشکر کے غالب ہونے کے لیے جھنڈا اٹھائے ہوئے تھا، تو میری مثال اس رات کے مسافر کی طرح تھی جس کی رات تاریک ہو۔ اب یہ وہ اوقات ہیں جن میں میری رہنمائی کی جارہی ہے تا کہ میں ہدایت یافتہ ہو جائیں“۔ ابوسفیان فتح مکہ کے موقعہ پر مسلمان ہوئے آپ صلی اللہ علیہ وسلم مکہ کی جانب روانہ تھے، انہوں نے ملاقات کی اور اسلام لے آئے۔ حنین میں شریک ہوئے اور آپ صلی اللہ علیہ وسلم کے ساتھ ثابت قدم رہے۔ مسلم کی روایت ہے، سیدنا عباس فرماتے ہیں: نبی صلی اللہ علیہ وسلم اپنے خچر کو کفار کی جانب ایڑ لگا رہے تھے، میں اس کی لگام پکڑے اسے روک رہا تھا اور ابوسفیان نے اس کا رکاب پکڑا ہوا تھا۔ آپ علیہ السلام نے فرمایا: چچا عباس! بیعت رضوان والوں کو آواز دیجئے۔۔۔۔ (حدیث) دولابی حدیث ابوسفیان بن حارث سے منقطع سند کے ذریعہ روایت کرتے ہیں، بقول بعض: انہوں نے مارے شرم کے رسول اللہ صلی اللہ علیہ وسلم کے سامنے سر نہیں اٹھایا۔ محمد بن اسحاق نے ان کا وہ قصیدہ بھی نقل کیا ہے جس میں نبی صلی اللہ علیہ وسلم کی وفات کے وقت آپ صلی اللہ علیہ وسلم کا مرثیہ کہا تھا: ش لقد عظمت مصیبتنا وجلّت عشیۃ قیل قد مات الرسول ”جس شام ہمیں بتایا گیا کہ رسول اللہ صلی اللہ علیہ وسلم وفات پاگئے ہیں اس وقت ہماری مصیبت دوبالا ہوگئی“۔ ان کی مسند وہ حدیث بھی نقل کی ہے جسے الدار قطنی نے کتاب الاخوۃ میں اور ابن قانع نے بطریق سماک بن حرب روایت کیا ہے کہ میں نے بحستان میں مدرک بن مہلب کے لشکر میں ایک بزرگ سے سنا جو ابوسفیان بن حارث سے روایت کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”اللہ تعالیٰ اس قوم کو پاک نہیں کرتا جس کا کمزور طاقتور سے اپنا حق وصول نہیں کر سکتا“۔ اس کی سند صحیح ہوتی اگر یہ بے نام شیخ نہ ہوتا۔ ابوالحسن نے حنین کے موقعہ پر ان کے اشعار میں سے چند یہ نقل کیے ہیں: ش ”آدمی کا چچا زاد اس کے چچاؤں میں سے ہے جو اس کے والد کے بیٹے اور اس کے آگے کی قوت ہے، آج یہ اس کے ایام میں سے ایک دن ہے جس میں رشتہ دار اپنی رشتہ داری کے اور مسلمان اپنے اسلام کے دفاع کے لیے جنگ کر رہا ہے“۔ عمر بن شبہ اخبار مدینہ میں عبدالعزیز بن عمران سے نقل کرتے ہیں کہ مجھے پتہ چلا عقیل بن ابی طالب نے ابوسفیان کو قبرستان میں گھومتے دیکھ کر پوچھا: عم زاد (کزن)! آپ یہاں کیا کر رہے ہیں؟ فرمایا: میں اپنی قبر کی جگہ دیکھ رہا ہوں تا کہ اسے اپنے گھر میں شامل کر لوں، اور اس کی کشادہ جگہ میں ایک قبر کھدوانے کا حکم دیا۔ قبر کھد گئی تو ابوسفیان اس کے پاس تھوڑی دیر بیٹھ کر لوٹ گئے۔ دو دن بھی نہ گزرے تھے ان کا انتقال ہو گیا اور اسی میں انہیں دفن کیا گیا۔ بقول بعض: خلافت فاروقی میں ۱۵ھ میں فوت ہوئے۔ آپ نے ہی ان کا جنازہ پڑھایا۔ ایک قول ہے: ۲۰ھ میں فوت ہوئے۔ یہ بات الدار قطنی نے کتاب الاخوۃ میں کی ہے۔ بغوی کی کتاب میں ان کے حالات میں لکھا ہے، عاصم الاعور کا قول ہے: درخت تلے سب سے پہلے ابوسفیان بن ح نے بیعت کی، جو درست نہیں۔ کیونکہ اوروں نے اسی سند سے لکھا ہے۔ ابوسنان بن وہب یہی درست ہے اور تمام اہل مغازہ کے ہاں یہی مشہور ہے ابوسنان کا نام عبداللہ ہے، عبادلہ میں ان کا ذکر ہو چکا ہے، عنقریب ابوسنان میں ان کا واقعہ بیان ہوگا۔","",{"fn":"(1) اسد الغابہ (۵۹۵۹) تجرید (۱۷۳/۲)\n(2) المستدرک (۲۵۵/۳) الطبقات (۳۶۱/۴)"}],[8631,"§۱۰۰۲۰ ۔ ابوسفیان\nصخر بن حرب بن امیہ بن عبد شمس، اپنے نام و کنیت سے مشہور ہیں۔ ان کی کنیت ابوحنظلہ بھی ہے ناموں میں تذکرہ ہوا۔"],[8632,"§۱۰۰۲۱ ۔ ابوسفیان\nسراقہ بن مالک نام سے شہرت رکھتے ہیں۔"],[8633,"§۱۰۰۲۲ ۔ ابوسفیان\nمدلوک دونوں کا تذکرہ ناموں میں ہوا ہے۔"],[8634,"§۱۰۰۲۳ ۔ ابوسفیان بن حارث\nان کا نام و نسب نہیں لیا گیا۔ بریدہ کے دوست ہیں۔ ابن اسحاق نے فرمایا: اُحد میں شہید ہوئے۔ مستغفری نے انہی طریق سے ان کا ذکر کیا ہے اور ابن فتحون نے اپنے استدراک میں ان کا ذکر کیا ہے، شاید یہ بعد والے ہیں۔"],[8635,"§۱۰۰۲۴ ۔ ابوسفیان بن حارث بن قیس(1)\nبن زید بن ضبیعہ بن زید بن مالک بن عوف انصاری اوسی۔ عدوی کا بیان ہے: اُحد میں شہید ہوئے ابن کلبی شرکا میں ان کا ذکر کرتے ہیں۔ بلاذری کا قول ہے: انہیں ابو البنات کہا جاتا ہے۔ جب اُحد کا معرکہ ہوا تو فرمانے لگے: میں جنگ کر اپنی بیٹیوں کے ہاں واپس جاؤں گا۔ جب مسلمانوں کے پاؤں اکھڑنے لگے تو کہنے لگے: اے اللہ! میں اپنی بیٹیوں کے پاس جانا چاہتا بلکہ تیری راہ میں قتل ہونا چاہتا ہوں، چنانچہ شہید ہو گئے تو اس کی وجہ سے نبی صلی اللہ علیہ وسلم نے ان کی تعریف فرمائی۔","",{"fn":"(1) اسد الغابہ (۵۹۶۰) استیعاب (۳۰۴۴)"}],[8636,"§۱۰۰۲۵ ۔ ابوسفیان (بے نسبت)(1)\nنبی صلی اللہ علیہ وسلم کی یہ حدیث بیان کرتے ہیں۔ رمضان کا عمرہ حج کے برابر ہے۔(2) ان سے ان کا بیٹا عبداللہ روایت کرتا ہے۔ ابوعمر نے ان کا ذکر کیا کہ اس کی سند مدنی ہے۔","",{"fn":"(1) اسد الغابہ (۵۹۶۲) تجرید (۱۷۴/۲)\n(2) بخاری کتاب العمرۃ باب عمرۃ فی رمضان (۱۷۸۲) مسلم کتاب الحج باب فضل العمرۃ فی رمضان (۲۰۲۸) نسائی کتاب الصیام (۲۱۰۹) مسند احمد (۲۲۹/۱) الصحیح لابن حبان (۳۷۰۰) اسد الغابہ (۴۷۳/۴)"}],[8637,"§۱۰۰۲۶ ۔ ابوسفیان(1)\nبن حویطب بن عبد العزیٰ قرشی عامری۔ بقول ابو عمر: فتح مکہ کے روز اپنے والد کے ساتھ مسلمان ہوئے اور جنگ جمل میں شہید ہوئے۔","",{"fn":"(1) استیعاب (۳۰۴۵) تجرید (۱۷۴/۲)"}],[8638,"§۱۰۰۲۷ ۔ ابوسفیان بن ابی وداعہ سہمی\nنام عبد اللہ ہے، تذکرہ ہوا ہے۔"],[8639,"§۱۰۰۲۸ ۔ ابوسفیان سدوسی\nبقول ابن مندہ: ابوموسیٰ محمد بن المثنیٰ، عمرو بن سفیان سے وہ اپنے والد سے بحوالہ اپنے دادا روایت کرتے ہیں کہ مشرک تھا پھر مسلمان ہو گیا۔"],[8640,"§۱۰۰۲۹ ۔ ابوسفیان بن محصن الاسدی(1)\nاحمد بن خازم کے نسخہ میں نقطوں سے لکھا ہے۔ ان کی روایت ہے نحر کے روز ہم نے رسول اللہ صلی اللہ علیہ وسلم کے ساتھ رمی جمرات کی پھر میں نے قمیص پہن لی تو رسول اللہ صلی اللہ علیہ وسلم نے ہم سے فرمایا: ”آج کے دن سے عرفات سے نکلنے تک قمیض (سلا ہوا کوئی بھی کپڑا) نہ پہننا“۔(2) ابن مندہ نے اسے نقل کیا ہے اور ابونعیم نے اس وجہ سے راجح قرار دیا ہے کہ یہ ابوسنان بن وہب بن محصن ہیں جس میں تردد ہے اس لیے کہ ابوسنان کے بارے میں کہا جاتا ہے وہ قریظہ کے محاصرے میں شہید ہو گئے جو حجۃ الوداع سے پہلے کا واقعہ ہے۔ بظاہر اول قول صحیح ہے لگتا ہے یہ ان کے چچا ہیں، اس میں کیا ممانعت ہے کہ دونوں ایک واقعہ نقل کریں۔","",{"fn":"(1) اسد الغابہ (۵۹۶۳)\n(2) جامع المسانید (۱۳۱/۱۴)"}],[8641,"§۱۰۰۳۰ ۔ ابوسفیان قرشی\nسیدنا عمر رضی اللہ عنہ کے گورنر اوس بن خالد بن یزید طائی کے حالات میں ان کا ذکر ہوا ہے کہ عہد فاروقی میں قتل ہو گئے تھے یہ پہلے بھی معلوم ہے کہ حجۃ الوداع میں جو قریشی بچا تھا وہ مسلمان بن کر حاضر ہوا تھا۔"],[8642,"§۱۰۰۳۱ ۔ ابوسفیان بن وہب بن ربیعہ ابن اسد بن صہیب\nبن مالک۔۔۔۔ اسدی۔ ابن حبان نے صحابہ رضی اللہ عنہم میں ان کا ذکر کیا ہے کہ بدر میں شریک ہوئے مستغفری نے ان کی پیروی کی ہے۔ احتمال ہے یہ ابوسنان بن وہب بن محصن ہوں ان کے نام میں لفظی غلطی اور نسب میں تبدیلی واقع ہوئی ہے ورنہ یہ ان کے رشتہ داروں میں سے دوسرے ہیں۔"],[8643,"§۱۰۰۳۲ ۔ ابوسکینہ(1)\nتصغیر ہے۔ بعض کا قول ہے: اس کے شروع میں فتحہ ہے، عبد الصمد بن سعید نے ان کا ذکر حمص میں آنے والے صحابہ رضی اللہ عنہم میں کیا ہے۔ فرماتے ہیں: ان کا نام محتم بن سوار ہے۔ بغوی کا قول ہے: شام میں سکونت اختیار کی، ابن مندہ کا قول ہے: یہ ثابت نہیں، پھر ان کی حدیث یزید بن ربیعہ کے طریق سے بحوالہ بلال بن سعد نقل کی ہے، میں نے ابو سکسینہ سے سنا وہ نبی کریم صلی اللہ علیہ وسلم کے اصحاب میں سے تھے۔ پھر عشق کی فضیلت کے بارے میں حدیث ذکر کی۔ اور اس طریق سے، اسے ابن جارود، باوردی اور ابراہیم بن سکن نے نقل کیا ہے، یزید ضعیف راوی ہے۔ ان سے کئی طرق سے بحوالہ یزید مروی ہے، اس میں یہ نہیں کہ وہ صحابہ رضی اللہ عنہم میں سے ہیں، اس میں سے ایک بغوی کے ہاں بحوالہ ابو توبہ مروی ہے۔ اسے ابو عمر نے طریقہ کے وزن پر ذکر کیا ہے، اس کے شروع میں الف لام کا اضافہ کیا، فرماتے ہیں: ابو سکینہ، ابن فتحون کا قول ہے، اس میں ابواحمد حاکم نے پیروی کی ہے۔","",{"fn":"(1) اسد الغابہ (۵۹۶۶) تجرید (۱۷۴/۲)"}],[8644,"§۱۰۰۳۳ ۔ ابوسلافہ\nیہ بعد والے ہیں۔"],[8645,"§۱۰۰۳۴ ۔ ابوسلالہ(1)\nاسلمی۔ بعض کا قول ہے ابو سلا، بعض نے کہا: ابوسلامہ، ابو عمر نے ابو حاتم کی اتباع میں فرمایا: ان کی حدیث حکام بن سلم کے ہاں بحوالہ عبداللہ بن عبداللہ، ان سے مروی ہے، یہ مفردہ کنیتوں میں بخاری کے کلام سے ماخوذ ہے۔ فرماتے ہیں: حکام بحوالہ ابو سلالہ اسلمی فرمایا، فرماتے ہیں: نبی کریم صلی اللہ علیہ وسلم نے فرمایا: ”عنقریب تم پر ایسے حکمران مقرر ہوں گے جو تمہارے سامنے حدیث بیان کریں گے اور جھوٹ بولیں گے“۔ اسے ابو احمد حاکم نے بخاری کے طریق سے نقل کیا ہے اور ابن مندہ نے بطریق ابوحاتم الرازی، بواسطہ یوسف بن موسیٰ بحوالہ حکام نقل کیا ہے اسی طرح اسے ابن جارود نے بحوالہ ابو حاتم رازی روایت کیا لیکن ان کا نسب سلمی بیان کیا ہے، ابوموسیٰ کا قول ہے: ابن مندہ نے ایک اور مرتبہ فرمایا: ابوسلامہ طبرانی کا قول ہے: ابو سلام اور ابوموسیٰ کی طرف اس کی نسبت کی ہے، انہوں نے اپنے استدراک میں ان کا ذکر کیا ہے۔ میں کہتا ہوں: بغوی، ابوعلی بن سکن نے یقین کیا ہے کہ وہ ابوسلامہ ہیں۔ ابن سکن کا قول ہے: انہیں شرف صحابیہ حاصل ہے، پھر ابن سکن نے عبدالرحمن بن شریک کے طریق سے بحوالہ عاصم بن عبید اللہ، انہوں نے اپنے والد سے نقل کیا ہے فرماتے ہیں: ہمارے ہاں ابوسلامہ سلمی آئے، ہم نے دو ماہ ان کی مہمانداری کی، انہوں نے ہم سے حدیث بیان کی کہ انہوں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا: ”عنقریب تم پر ایسے امیر ہوں گے کہ تمہارے رزق ان کے ذریعے ہوں گے، وہ تم پر اس میں سے روک لیں گے یہاں تک کہ تم ان کے جھوٹ کی تصدیق کرو گے اور ان کے ظلم پر ان کی مدد کرو گے، تو انہیں وہ حق دو جو وہ تم سے قبول کر لیں، اگر وہ حق کی خلاف ورزی کریں تو ان سے جنگ کرو، جو اس حالت میں مر گیا وہ شہید ہے“۔(2) اسے بغوی نے بحوالہ ابوسلامہ سلامی نقل کیا ہے، فرماتے ہیں: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”میں ہر شخص کو اس کی والدہ کے ساتھ حسن سلوک کی وصیت کرتا ہوں“۔(3) میں نے کتاب ابن سکن کے قابل اعتماد مجموعے میں اسے میم کے بدلے فا سے یعنی اسلمی کے بدلے سلمی میں دیکھا ہے، بغوی کے نسخے میں سلامی ہے۔ جنہوں نے کہا ہے کہ وہ ابوسلالہ دولام کے ساتھ ہیں۔ وہ ابو عبید اللہ مرزبانی ہیں۔ انہوں نے باب السیرۃ العادلہ میں ان کا ذکر کیا ہے، اور جنہوں نے کہا ہے وہ سلمی ہیں وہ باوردی ہیں۔","",{"fn":"(1) اسد الغابہ (۵۹۶۷) تجرید (۱۷۴/۲)\n(2) المعجم الکبیر (۹۳۴/۲۲) ابن ابوعاصم (۱۰۴/۲۲) مجمع الزوائد (۲۲۸/۵) جامع المسانید والسنن (۱۴۸/۱۴) الجرح والتعدیل (۳۸۷/۹)\n(3) ابن ماجہ (۳۶۵۷) احمد ..."}],[8646,"§۱۰۰۳۵ ۔ ابوسلامہ سلامی\nپہلے والے میں ان کا ذکر ہے۔"],[8647,"§۱۰۰۳۶ ۔ ابوسلام(1)\nرسول اللہ صلی اللہ علیہ وسلم کے خادم ہیں، ابواحمد حاکم نے کہا: رسول اللہ صلی اللہ علیہ وسلم کے موالی میں ان کا شمار ہے۔ انہیں شرف صحابیت مل ہے۔ خلیفہ بن خیاط نے صحابہ رضی اللہ عنہم کے ناموں میں ان کا ذکر کیا ہے۔ جو بنو ہاشم کے موالی ہیں۔ حاکم نے مسعر کے طریق سے بحوالہ ابوسلام خادم رسول اللہ صلی اللہ علیہ وسلم کی روایت نقل کیا ہے، فرماتے ہیں: ”جو مسلمان صبح اور شام کے وقت یہ دعا پڑھے ((رَضِیْتُ بِاللہِ ....))۔ (الحدیث)(2) اس میں ہے کہ اللہ تعالیٰ اس سے راضی ہو جاتے ہیں۔ اسے ابن ابو شیبہ نے بحوالہ مسعر اسی طرح روایت کیا ہے۔ بغوی نے بحوالہ ابوبکر نقل کیا ہے، اسے ابو داؤد اور نسائی نے شعبہ کے طریق سے بحوالہ ابوسلام نقل کیا ہے کہ وہ حمص کی مسجد ساتھ تھے، ان کے پاس سے ایک آدمی گزرا، لوگوں نے کہا: یہ نبی کریم صلی اللہ علیہ وسلم کے خادم ہیں، وہ ان کی طرف بڑھے اور کہا: مجھ سے حدیث بیان کیجئے، پھر یہ حدیث اسی طرح بیان کی۔ اسے نسائی اور بغوی نے اسی طرح ہشیم کے طریق سے بحوالہ ابو عقیل ہاشم بن بلال نقل کیا ہے، فرماتے ہیں: ہم سے ابق بن ناجیہ نے بحوالہ ابو سلام نقل کیا ہے، ہمارے پاس سے ایک شخص اشعث گزرا، لوگوں نے کہا: انہوں نے نبی کریم صلی اللہ علیہ وسلم کی خدمت کی ہے، میں نے ان سے کہا: آپ نے رسول اللہ صلی اللہ علیہ وسلم کی خدمت کی ہے، انہوں نے کہا: جی ہاں۔ میں نے اس سے کہا: مجھے آپ صلی اللہ علیہ وسلم کی ایسی حدیث سناؤ جو میرے اور تمہارے علاوہ کسی کے درمیان بیان نہ کی گئی ہو، انہوں نے کہا: میں نے آپ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا: ”جس نے صبح کے وقت کہا۔۔ (الحدیث) اسی طرح ابو سلام نے اس حدیث کو خادم سے روایت کیا ہے اور خادم مبہم ہیں۔ اسے ابوداؤد نے کتاب العلم میں شعبہ کے طریق سے نقل کیا ہے۔ دوسری حدیث میں فرماتے ہیں: شعبہ سے اس سند سے بحوالہ ایک شخص جو نبی کریم صلی اللہ علیہ وسلم کا خادم ہے مروی ہے، اس سند میں ایک اور غلطی ہوئی کہ یہ حرف سین کی آخری قسم میں سابقہ حالات میں بیان ہوئی، اور شعبہ کی اس بارے میں حدیث محفوظ ہے، اور مذکورہ ابوسلام ممطور حبشی ہیں اور وہ تابعی ہیں۔ میں نے ان کے حالات کو آخری قسم میں ذکر نہیں کیا کیونکہ رسول اللہ صلی اللہ علیہ وسلم کے موالی میں ابو سلام کا شمار ہے۔ شاید یہ آخری ہیں جنہوں نے صاحب ترجمہ کے خلاف کچھ بھی روایت نہیں کیا۔","",{"fn":"(1) اسد الغابہ (۵۹۶۸) تجرید (۱۷۴/۲)\n(2) ابوداؤد (۵۰۷۲) ابن ماجہ (۳۸۷۰) مسند احمد (۳۳۷/۴)"}],[8648,"§۱۰۰۳۷ ۔ ابوسلامہ ثقفی(1)\nصحابہ میں ان کا ذکر ہے۔ بعض نے کہا: ان کا نام عروہ ہے، اسی طرح ابن عبدالبر نے نقل کیا ہے۔","",{"fn":"(1) اسد الغابہ (۵۹۶۹) الاستيعاب (۳۰۵۲) تجرید (۱۷۵/۲)"}],[8649,"§۱۰۰۳۸ ۔ ابوسلامہ سلمی(1)\nبعض نے کہا: حبیبی، ان کا نام خداش ہے۔ وہ اس حدیث سے پہچانے جاتے ہیں۔ میں ایک شخص کو اپنی والدہ کے ساتھ حسن سلوک کرنے کی وصیت کرتا ہوں۔ (الحدیث)(2) یہ ابو عمر کا قول ہے۔ میں کہتا ہوں: احمد، ابن ماجہ وغیرہ نے منصور کے طریق سے بحوالہ ابوسلامہ حدیث کو روایت کیا ہے، میں نے حرف خا میں اس کی طرف اشارہ کر دیا ہے، اسے دولابی نے شیبان کے طریق سے بحوالہ منصور روایت کیا ہے۔ اور عبید اور ابوسلامہ کے درمیان عرفطہ سلمی کا اضافہ کیا ہے۔","",{"fn":"(1) اسد الغابہ (۵۹۷۰) تجرید (۱۷۵/۲)\n(2) ابن ماجہ (۳۶۵۷) مسند احمد (۳۱۱/۴) طبرانی (۴۱۸/۴) حاکم (۱۵۰/۴) ابن کثیر (۱۵۱/۴)"}],[8650,"§۱۰۰۳۹ ۔ ابوسلمہ بن سفیان\nبن عبد اسد جو ان کے بعد صحابی ہیں، ان کے بھتیجے ہیں۔ بدر سے پہلے ان کے والد وفات پاگئے۔ جیسا کہ ان کے بھائی اسود کے سوانح میں گزر چکا ہے، اور ان کی والدہ ام جمیل بنت مغیرہ بن ابو عاص بن امیہ ہیں۔ ان کی اولاد ہے۔ ان میں سے محمد بن عبد الرحمن بن ابو سلمہ بن سفیان ہیں جو اوقص کے نام سے معروف ہیں، موسیٰ ہادی کے زمانے میں مدینہ کے قاضی تھے، پھر رشید کے بعد بغداد کے قاضی بنے۔ زبیر بن بکار نے ان کا ذکر کیا ہے۔"],[8651,"§۱۰۰۴۰ ۔ ابوسلمہ بن عبد اسد(1)\nبن ہلال بن عبد اللہ بن عمر بن مخزوم مخزومی۔ جو اسلام میں سبقت حاصل کرنے والے ہیں۔ اسماء میں ان کا ذکر گزر چکا ہے۔","",{"fn":"(1) اسد الغابہ (۵۹۷۱) تجرید (۱۷۵/۲)"}],[8652,"§۱۰۰۴۱ ۔ ابوسلمہ (بے نسبت)(1)\nابواحمد حاکم نے فرمایا: انہیں شرف صحابیت حاصل ہے، اور اپنی خلافت میں ان کی تعریف کی، جب ان کی بیوی نے ان کی شکایت کی، ابوبکر بن ابو عاصم اور ابواحمد حاکم نے اسے دو طریق سے بحوالہ معاویہ بن قرۃ مزنی روایت کیا ہے۔ فرماتے ہیں: میں پنیہ اور گھی کے زمانے میں مدینہ آیا، اور دیہاتی گندم لا رہے تھے، تو ایک شخص بھر پور نظروں سے لوگوں کو دیکھ رہا تھا۔ میں نے خیال کیا کہ وہ غریب ہے، میں اس کے قریب گیا اور اسے سلام کیا، اس نے سلام کا جواب لوٹایا، اس نے مجھ سے کہا تم اس ملک کے ہو؟ میں نے کہا: جی ہاں! اور اس کے پاس بیٹھ گیا، میں نے کہا: تم کون ہو؟ اس نے کہا: بنو ہلال سے ہوں۔ میرا نام ھمس ہے، پھر مجھ سے کہنے لگا: کیا تم سے وہ حدیث بیان نہ کروں جسے میں نے اس وقت سنا تھا جب سیدنا عمر بن خطاب رضی اللہ عنہ موجود تھے۔ میں نے کہا: کیوں نہیں۔ اس نے کہا: اسی اثناء میں کہ ہم ان کے پاس بیٹھے تھے کہ ان کے پاس ایک عورت آئی اور بیٹھ گئی، اس نے کہا امیر المومنین! میرے شوہر کا شر بڑھ گیا ہے۔ اور اس کی خیر کم ہوگئی ہے۔ انہوں نے پوچھا: تمہارا شوہر کون ہے؟ کہنے لگی: ابوسلمہ ں نے کہا: اس شخص کو شرف صحابیت حاصل ہے اور وہ شخص مسیحا ہے۔(2) پھر سیدنا عمر رضی اللہ عنہ نے اپنے پاس بیٹھے ہوئے آدمی سے پوچھا: کیا ایسا نہیں ہے؟ اس نے کہا: اے امیر المومنین! جو آپ نے فرمایا، ایسا ہی ہے۔ پھر حدیث بیان کی، اس میں سے بعض لمس کے سوانح میں گزر چکا ہے۔","",{"fn":"(1) اسد الغابہ (۵۹۷۲) تجرید (۱۷۵/۲)\n(2) الجرح والتعدیل (۱۵۱/۱)"}],[8653,"§۱۰۰۴۲ ۔ ابوسلمہ (بے نسبت)\nیہ دوسرے ہیں، حاکم ابواحمد نے پہلے والے سے جدا ان کا ذکر کیا ہے اور احمد بن عبداللہ بن حکیم کے طریق سے نقل کیا، فرماتے ہیں: ابراہیم خزاعی فرماتے ہیں: ابوسلمہ نے نبی کریم صلی اللہ علیہ وسلم سے حدیث روایت کی، فرماتے ہیں: ”شیطان کہتا ہے، مجھے صاحب مال بچ نہیں سکتا۔ (الحدیث)"],[8654,"§۱۰۰۴۳ ۔ ابوسلمہ(1)\nعبد حمید بن سلمہ کے دادا ہیں، بغوی نے کنیوں میں ان کا ذکر کیا ہے، انہوں نے اور ابن ماجہ نے عثمان لیثی کے طریق سے بحوالہ عبدالحمید بن سلمہ، انہوں نے اپنے والد سے، انہوں نے اپنے دادا سے روایت کیا ہے کہ ان کے ماں باپ اپنا جھگڑا لے کر نبی کریم صلی اللہ علیہ وسلم کے پاس گئے، ان میں سے ایک مسلمان تھا اور دوسرا کافر تھا، آپ نے اسے اختیار دیا وہ مسلمان کی طرف متوجہ ہوا۔ حرف سین میں سلمہ کے حالات میں وضاحت سے یہ گزر چکا ہے، بغوی کے ہاں یہ دوسرے طریق سے ہے۔ بحوالہ عبدالحمید بن ابوسلمہ، انہوں نے اپنے والد کے حوالے سے، انہوں نے اپنے دادا کے حوالے سے نقل کیا ہے۔ انہوں نے ابوسلمہ کے مر کا عنوان قائم کیا ہے، جو صحیح نہیں محفوظ روایت یہ ہے کہ اس میں عبدالحمید بن سلمہ ہیں، اور جس نے عبدالحمید بن ابوسلمہ کہا یعنی ابو کی زیادتی کی تو یہ محض غلط ہے۔","",{"fn":"(1) اسد الغابہ (۵۹۷۲) تجرید (۱۷۵/۲)"}],[8655,"§۱۰۰۴۴ ۔ ابوسلمی راعی(1)\nرسول اللہ صلی اللہ علیہ وسلم کے خادم ہیں، بعض کا قول ہے کہ ان کا نام حریث ہے۔ ابن مندہ وغیرہ کے نزدیک ان کا نام ہے جو اسماء میں گزر چکا ہے۔ بغوی کے ہاں عالی سند سے ان کی حدیث ہے جس میں نہ ان کا نام ہے نہ کنیت ہے۔ پھر اسے ابوسلام اسود کے طریق سے نقل کیا ہے۔ فرماتے ہیں: ہم سے ابو سلمی نے روایت کیا۔","",{"fn":"(1) اسد الغابہ (۵۹۷۴) تجرید (۱۷۵/۲)"}],[8656,"§۱۰۰۴۵ ۔ ابوسلمی (بے نسبت)\nابن ابو حاتم نے ان کا ذکر کیا ہے، فرماتے ہیں: میں نے اپنے والد سے کہا: سری بن یحیی نے روایت کیا، فرماتے ہیں: میں نے فرمایا: میں نے رسول اللہ صلی اللہ علیہ وسلم کو صبح کی نماز میں پڑھتے ہوئے سنا: ﴿جب سورج لپیٹ دیا جائے گا﴾۔(1) انہوں نے کہا: میں نے حسان بن عبداللہ سے پوچھا: کیا سری اس شیخ سے ملے ہیں؟ انہوں نے کہا: جی ہاں۔ اسی طرح ابو عمر نے ان کا ذکر کیا۔ جو کہ کتاب ابن ابو حاتم میں ہے، ابو احمد حاکم نے ان کا ذکر کیا ہے، فرماتے ہیں: ابوسلیمان یا ابوسلمی، پھر فرمایا: ابوسلیمان یا ابو سلمی اس حدیث میں ذکر وہم ہے، مجھے معلوم نہیں کس سے مروی ہے، مجھے سری بن یحیی کی سماعت معلوم نہیں، نہ کسی صحابی کے حوالہ سے روایت کرنا معلوم ہے۔ اس حدیث کو ابو ولید طیالسی نے روایت کیا ہے کہ ہم سے سری بن یحیی نے بحوالہ عنبرہ کے ایک شخص کہ انہوں نے نبی کریم صلی اللہ علیہ وسلم سے یہ سنا: مجھے ابراہیم بن محمد فرائضی نے ابو ولید کے حوالے سے خبر دی، پھر اسے ذکر کیا وہی صحیح ہے۔ بعض کا قول ہے: مضموم ہیں، بخلاف پہلے کے جن کا ذکر گزر چکا ہے۔","",{"fn":"(1) اسد الغابہ (۵۹۷۵) تجرید (۱۷۵/۲) سورۃ الشمس (۱)"}],[8657,"§۱۰۰۴۶ ۔ ابوسلیط انصاری بدری(1)\nبعض نے کہا: ان کا نام اسید ہے، بعض نے کہا: ان کا نام انس ہے، بعض کا قول ہے: سبرہ جو اپنی کنیت سے مشہور ہیں۔ بدری صحابہ رضی اللہ عنہم میں ان کا ذکر ہے، ان کی روایت کو احمد اور بغوی رحمہما اللہ نے ابن اسحاق کے طریق سے بحوالہ والد عبداللہ بن ابوسلیط نقل کیا ہے۔ فرماتے ہیں: ہمارے پاس نبی کریم صلی اللہ علیہ وسلم کی طرف سے منع کرنے والا آیا اور ہمیں پالتو گدھے کے گوشت کھانے سے منع فرمایا اور جوش مارتی ہوئی ہانڈی سے تو ہم نے انہیں انڈیل دیا۔","",{"fn":"(1) اسد الغابہ (۵۹۷۷) الاستيعاب (۳۰۵۹) تجرید (۱۷۵/۲)"}],[8658,"§۱۰۰۴۷ ۔ ابوسلیمان\nخالد بن ولید مخزومی، سیف اللہ۔"],[8659,"§۱۰۰۴۸ ۔ ابوسلیمان\nمالک بن حویرث لیثی، اسماء میں ان دونوں کا ذکر گزر چکا ہے۔"],[8660,"§۱۰۰۴۹ ۔ ابوسمح(1)\nرسول اللہ صلی اللہ علیہ وسلم کے مولیٰ ہیں۔ بعض کا قول ہے: ان کا نام ابوذر ہے۔ بغوی کا قول ہے: نبی کریم صلی اللہ علیہ وسلم کے خادم ہیں۔ نبی کریم صلی اللہ علیہ وسلم سے روایت کیا، ان سے محل بن خلیفہ نے روایت کیا، ابو زرعہ کا قول ہے: مجھے ان کا نام معلوم نہیں، مجھے ان کی ایک حدیث کے علاوہ معلوم نہیں۔ ابن خزیمہ، ابو داؤد اور نسائی، ابن ماجہ، بغوی نے ان کی حدیث نقل کی ہے۔ بطریق یحیی بن ولید، بحوالہ ابو سمح، فرماتے ہیں: میں نبی کریم صلی اللہ علیہ وسلم کی خدمت کرتا تھا، جب آپ صلی اللہ علیہ وسلم غسل کرنا چاہتے تو فرماتے: ”میری طرف پیٹھ کرلو“۔ بزار کا قول ہے: اس طریق کے علاوہ ہمیں حدیث ابو سمح کا علم نہیں۔ ابو عمر کا قول ہے: انہیں قتل کر دیا گیا، وہ نہیں جانتے انہوں نے کہاں وفات پائی۔","",{"fn":"(1) اسد الغابہ (۵۸۷۸) تجرید (۱۷۵/۲)"}],[8661,"§۱۰۰۵۰ ۔ ابو السمح\nشرحبیل بن سمط کندی، اسماء میں ان کا ذکر گزر چکا ہے۔"],[8662,"§۱۰۰۵۱ ۔ ابوسنابل بن بعکک(1)\nجعفر بن حارث بن عمیلہ کے وزن پر ہے ابن سباق بن عبد دار قرشی عبدری، ان کا نام صبہ ہے۔ بعض کا قول ہے: نون کے ساتھ ہے۔ بعض نے کہا: عمر، ایک قول ہے: عامر، ایک قول ہے: اصرم، ایک قول ہے: لبید اضافت کے ساتھ ہے۔ بغوی کا قول ہے کوفہ میں رہے۔ بخاری کا قول ہے: مجھے معلوم نہیں کیونکہ وہ نبی کریم صلی اللہ علیہ وسلم کے بعد رہے۔ انہوں نے نبی کریم صلی اللہ علیہ وسلم سے روایت کی اور ان سے اسود بن یزید نخعی، زفر بن اوس بن حدثان نصری نے روایت کی۔ ابن سعد(2) وغیرہ کا قول ہے: مکہ میں مقیم رہے یہاں تک کہ وفات پاگئے۔ فتح مکہ کے مسلمانوں میں سے ہیں۔ ترمذی، نسائی، ابن ماجہ نے ان کی حدیث بروایت منصور بحوالہ اسود نقل کی ہے۔ یہ حدیث سبیعہ کے قصے کے بارے میں ہے۔ ترمذی کا قول ہے: ہمیں اسود کا ابوسنابل سے سماعت کرنا معلوم نہیں، صحیحین میں بھی ان کا ذکر سبیعہ اسلمیہ کے قصے میں ہے، جب ان کے شوہر وفات پاگئے، پھر ان کے ہاں بچے کی ولادت ہوئی۔ پیغامات نکاح وصول کرنے کے لیے تیار ہوئیں۔ انہوں نے انہیں ڈانٹا، فرماتے ہیں: یہاں تک کہ چار ماہ دس دن کی عدت گزارو، انہوں نے نبی کریم صلی اللہ علیہ وسلم سے سوال کیا، انہوں نے انہیں بتایا کہ وہ عدت سے نکل چکی ہیں۔ یہاں بات پر دلالت کرتا ہے کہ ابوسنابل فقیہ تھے، ورنہ ان پر بغیر علم فتویٰ دینے لزام عائد ہوتا کہ انہوں نے تکیر کی تھی، لیکن ان کا عذر یہ ہے کہ انہوں نے عموم کو دلیل بنایا، جبکہ اس عموم سے حاملہ والی عورت بچہ جننے، مخصوص ہے۔ بغوی کے ہاں مغیرہ کے طریق سے بحوالہ ابوسنابل مروی ہے کہ سبیعہ کے ہاں اپنے شوہر کی وفات کے اٹھائیس راتوں کے بچے کی ولادت ہوئی، انہوں نے زیب و زینت اختیار کی اور نکاح کرنا چاہا، ان سے ابوسنابل نے کہا: تم ایسا نہیں کر سکتی، وہ نبی صلی اللہ علیہ وسلم کے پاس آئیں آپ صلی اللہ علیہ وسلم نے فرمایا: کیوں نہیں! اگرچہ ابوسنابل کی ناک خاک آلود ہو۔(3) ابن سعد نے نقل کیا ہے کہ وہ ان میں سے تھے جنہوں نے سبیعہ کو نکاح کا پیغام دیا تھا۔ ابن برقی نے ذکر کیا ہے کہ انہوں نے ان سے بعد سے نکاح کر لیا اور سے سنابل بن ابوسنابل پیدا ہوئے۔","",{"fn":"(1) اسد الغابہ (۵۹۷۹) الاستيعاب (۳۰۶۰) تجرید (۱۷۵/۲)\n(2) طبقات الکبریٰ (۳۳۲/۵)\n(3) مسند احمد (۳۰۵/۴)"}],[8663,"§۱۰۰۵۲ ۔ ابوسنان بن وہب(1)\nان کا نام عبداللہ ہے، بعض کا قول ہے: وہب بن عبداللہ اسدی، موسیٰ بن عقبہ کا قول ہے: بدر میں شریک ہونے والوں میں سے تھے، ابوسنان بن وہب اسدی۔ ان کا نام نہیں لیا۔ شعبی کا قول ہے: درخت کے نیچے بیعت کرنے والوں میں سے پہلے ابوسنان بن وہب ہیں، اور ان کا نام نہیں لیا، اسے عمر بن شبہ نے نقل کیا ہے۔ فرماتے ہیں: وہ ابوسنان بن محصن کے علاوہ ہیں، جو عکاشہ اور ام قیس کے بھائی ہیں، کیونکہ ابن محصن وفات پاگئے جبکہ نبی کریم صلی اللہ علیہ وسلم بنو قریظہ کا محاصرہ کئے ہوئے تھے۔ یہ بیعت رضوان جو درخت کے نیچے ہوئی تھی، اس سے پہلے کا واقعہ ہے۔ حاکم ابواحمد نے عاصم احول کے طریق سے بحوالہ شعبی روایت کیا، فرماتے ہیں: میرے پاس ایک عامر اور ایک اسدی آیا، وہ دونوں اپنے اپنے قبیلوں پر فخر کر رہے تھے۔ میں نے کہا: بنو اسد کی چھ خصلتیں ہیں جو عرب کے کسی قبیلے کو حاصل نہیں، بیعت رضوان میں سب سے پہلے بیعت کرنے والے ابوسنان عبد اللہ بن وہب اسدی ہیں۔ انہوں نے کہا: یا رسول اللہ! اپنا ہاتھ بڑھائیے میں آپ سے بیعت کروں، آپ صلی اللہ علیہ وسلم نے فرمایا: کس چیز پر؟ اس نے کہا: جو کچھ آپ کے دل میں ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا میرے دل میں کیا ہے؟ کہا فتح یا شہادت۔ آپ صلی اللہ علیہ وسلم نے فرمایا: ہاں۔ پھر ان سے بیعت لی، فرماتے ہیں: پھر لوگ ابوسنان کی بیعت پر آ کر بیعت کرنے لگے۔(2) اسے حسن بن علی حلوانی اور محمد بن اسحاق سراج نے اسماعیل بن ابو خالد کے کئی طرق سے بحوالہ شعبی اسے نقل کیا ہے، فرماتے ہیں: درخت کے نیچے سب سے پہلے بیعت کرنے والے ابوسنان بن وہب ہیں۔۔۔۔ پھر قصہ ذکر کیا۔ اسے ابن مندہ نے عاصم کے طریق سے بحوالہ زر بن حبیش نقل کیا ہے۔ فرماتے ہیں: درخت کے نیچے سب سے پہلے ابوسنان بن وہب نے بیعت کی۔ بغوی نے اس میں لفظی غلطی کی ہے جو ابوسفیان بن حارث بن عبدالمطلب کے سوانح میں گزر چکی ہے، اور ابونعیم فضل بن رکین کے طریق سے نقل کیا ہے، فرماتے ہیں: ابوسنان اسدی ان کا نام وہب بن عبد اللہ ہے، واقدی کا دعویٰ ہے کہ جن کا یہ قصہ پیش آیا وہ عکاشہ کے بھتیجے ہیں، فرماتے ہیں: رہے ابوسنان تو وہ بنو قریظہ کے حصار کے وقت فوت ہوئے۔ واللہ اعلم!","",{"fn":"(1) اسد الغابہ (۵۹۸۰) تجرید (۱۷۵/۲)\n(2) دلائل النبوۃ (۱۳۷/۴)"}],[8664,"§۱۰۰۵۳ ۔ ابوسنان بن محصن\nعکاشہ کے بھائی ہیں، ابن اسحاق(1) نے بدر میں حاضر ہونے والوں میں ان کا ذکر کیا ہے۔ میرے خیال میں وہ ابوسفیان بن محصن کے علاوہ ہیں جیسا کہ میں نے پہلے بیان کیا ہے اور ابوسنان بنو قریظہ کے محاصرے کے وقت فوت ہوئے۔ اور ابوسفیان حجۃ الوداع میں شریک تھے، میں نے بیان کیا ہے کہ وہ ان صحابی کے علاوہ کوئی اور ہیں جن کا ذکر ابھی گزرا ہے۔ واقدی رحمہ اللہ کا کلام اس کے خلاف ہے۔","",{"fn":"(1) السیرۃ النبویۃ (۲۴۲/۲)"}],[8665,"§۱۰۰۵۴ ۔ ابوسنان انصاری\nام سنان کے شوہر ہیں، صحیحین میں ان کا ذکر ثابت ہے۔ بطریق عطاء بحوالہ ابن عباس رضی اللہ عنہما کہ نبی کریم صلی اللہ علیہ وسلم نے انصار کی ایک خاتون سے جنہیں ام سنان کہا جاتا تھا، فرمایا: ”تمہیں کس نے روکا ہے کہ ہمارے ساتھ حج کرو“۔(1) فرماتی ہیں: ابوفلان کے شوہر کے دو اونٹ تھے، انہوں نے اور ان کے بیٹے نے ایک پر حج کیا اور دوسرا کھیتی کو سیراب کرتا تھا۔ آپ صلی اللہ علیہ وسلم نے فرمایا: ”رمضان میں عمرہ کرنا حج کے برابر ہے“۔ ایک روایت میں یہ الفاظ ہیں: ”جب رمضان کا مہینہ آئے تو عمرہ کرو“۔ مسلم میں ہے: ”رمضان میں عمرہ کرنا حج کے برابر ہے یا میرے ساتھ حج کے برابر ہے“۔","",{"fn":"(1) بخاری (۱۷۸۲) مسلم (۱۲۵۶) مسند احمد (۲۲۹/۱)"}],[8666,"§۱۰۰۵۵ ۔ ابوسنان اشجعی(1)\nجراح اشجعی کے سوانح میں ذکر ہے، بعض کا قول ہے: وہ معقل بن سنان ہیں، راجح یہ ہے کہ وہ اس کے علاوہ ہیں۔","",{"fn":"(1) اسد الغابہ (۵۹۸۱) تجرید (۱۷۶/۲)"}],[8667,"§۱۰۰۵۶ ۔ ابوسنان بن صیفی\nبن صخر بن خنساء بن سنان بن عبید بن عدی بن غنم بن کعب بن سلمہ انصاری مسلمی، ابن اسحاق(1) نے بدر میں حاضر ہونے والوں میں ان کا ذکر کیا ہے، خندق میں شہید ہوئے۔","",{"fn":"(1) السیرۃ النبویۃ (۲۵۷/۲)"}],[8668,"§۱۰۰۵۷ ۔ ابوسنان عبدی\nپھر صباحی، ابو عبیدہ معمر بن مثنیٰ کا قول ہے: وفد میں تھے، رسول اللہ صلی اللہ علیہ وسلم نے ان کے چہرے پر ہاتھ پھیرا۔ ان کی عمر طویل تھی کہ نوے سال تک جا پہنچے، وہ مسجد بنو صباح کے مؤذن تھے۔ ان کا چہرہ نبی صلی اللہ علیہ وسلم کے ہاتھ پھیرنے کی وجہ سے چمکتا تھا، اور با آبرو تھے۔"],[8669,"§۱۰۰۵۸ ۔ ابوسنان بن حریث مخزومی\nزبیر بن بکار نے شماس بن عثمان مخزومی کے سوانح میں ان کا ذکر کیا ہے، فرماتے ہیں: جب عثمان بن شماس کی وفات ہوئی حریث مخزومیہ نے یہ اشعار کہے گویا وہ ان کی زوجہ تھیں: ش ”اے میری آنکھ نہ رکنے والے آنسو بہا دے اور عثمان بن شماس کے صدمے پر رد، جو سخت حملے والا اور مبارک تھا کثرت سے جھنڈے اٹھاتا اور گھوڑوں پر سوار ہوتا تھا جب کوئی مصیبت ٹوٹتی تو وہ بے وطن ہو کر دشمن کو ڈرا دیتا ایسا تیر چلاتا کہ کھوپڑی قلم کر دیتا۔ میں نے یہ اشعار اس غم کی گھڑی میں کہے جب لوگ اس کی موت کی خبر دینے لگے، بہادر نے دیت دے دی اور کھانے والے اور پہننے والے کو مصیبت میں مبتلا کر دیا“۔ کہتے ہیں: غزوہ اُحد میں شہید ہوئے تھے۔ پھر ان کے بھائی ابوسنان بن حریث نے انہیں جواب دیا: ”اپنی شرم و حیاء کو پردے میں اور پوشیدہ رکھو، عثمان بھی انسان تھا اگر اس کی وفات کا وقت ہو گیا تھا تو اپنی جان کو مت کوسو، خوف و پریشانی کا دن بھی اللہ کی رضا میں گزارنا چاہیے۔ اللہ کا شیر حمزہ بھی فوت ہو گیا، لہذا صبر سے کام لو انہوں نے وہی جام چکھا ہے جو عثمان بن شماس نے چکھا تھا“۔"],[8670,"§۱۰۰۵۹ ۔ ابوسہل\nبریدہ بن حصیب اسلمی، اسماء میں ان کا ذکر گزر چکا ہے۔"],[8671,"§۱۰۰۶۰ ۔ ابوسہل (بے نسبت)(1)\nابو عمر کا قول ہے: صحابہ رضی اللہ عنہم میں ان کا ذکر ہے، میں انہیں نہیں جانتا۔ میں کہتا ہوں: تجرید(2) میں ذکر ہے کہ مسند بقی بن مخلد میں ان کی ایک حدیث ہے۔","",{"fn":"(1) اسد الغابہ (۵۹۸۵) الاستيعاب (۳۰۶۴) تجرید (۱۷۶/۲)\n(2) التجرید (۱۷۶/۲)"}],[8672,"§۱۰۰۶۱ ۔ ابوسہلہ(1)\nسائب بن خلاد، اسماء میں ان کا ذکر گزر چکا ہے۔","",{"fn":"(1) اسد الغابہ (۵۹۸۶) تجرید (۱۷۶/۲)"}],[8673,"§۱۰۰۶۲ ۔ ابوسود(1)\nبعض کا قول ہے: وہ وکیع بن ابوسود کے دادا ہیں جنہوں نے خراسان پر حملہ کیا، بعض کا قول ہے: ان کا نام حسان بن قیس ہے، یہ ابن قانع کا قول ہے۔ اس میں تردد ہے۔ ابن کلبی نے بنو تمیم کے نسب میں فرمایا ہے: بنوغدانہ بن سیر بوع بن حنظلہ وکیع بن ابوسود، وہ وکیع بن حسان بن قیس بن ابوسود بن کلب بن عوف بن نامل بن عوف بن غدانہ، یہ وہی ہے جس نے خراسان کے امیر قتیبہ بن مسلم کو قتل کیا، یہ سلیمان بن عبد الملک کی خلافت کی بات ہے۔ اس سے ظاہر ہوا کہ حسان وکیع کا والد ہے اور ابو سود حسان کے دادا ہیں، یہی قابل اعتماد ہیں۔ اسے احمد نے ابن مبارک کے طریق سے بحوالہ ابوسود نقل کیا ہے۔ فرماتے ہیں: میں نے نبی کریم صلی اللہ علیہ وسلم سے فرماتے ہیں: یمین فاجرہ سے مراد یہ ہے کہ کوئی شخص کسی مسلمان کے مال کو ہتھیا لے اور رشتہ داری ختم کر لے۔(2) اسے حسن بن سفیان، بغوی، ابن مندہ، ابن مبارک کے طریق سے، اسے ابوعلی بن سکن نے بطریق عبدالرزاق، انہوں نے معمر سے روایت کیا، ابن درید کا قول ہے۔ ابوسود وکیچ کا دادا مجوسی ہے۔ اسی طرح ابن کلبی نے کتاب المناقب میں فرمایا: ابوعمر کا قول ہے: یہ بعید نہیں، کیونکہ وہ بنو تمیم کے گھر فرس کے گھروں کے قریب ہیں۔ میں کہتا ہوں: حاجب کے قصہ میں جو عطارد کے والد ہیں، اس کی تائید ہوتی ہے کہ ان ابوسود کے نسب میں ہے جو اس پر دلالت کرتا ہے۔ بابک مجھی نام ہے، شاید وہ مجوسی ہو گئے تھے۔ اس کے بیٹوں نے اس کی پیروی کی، ابوسود کی نبی کریم صلی اللہ علیہ وسلم سے سماعت کی تصریح اور آپ سے روایت اس کے بعد ہے۔ تابعین کا ان کی حدیث روایت کرنا اس بات کا پتہ دیتا ہے کہ وہ مسلمان ہوئے اور شرف صحابیت سے سرفراز ہوئے تھے۔ ابواحمد حاکم نے بحوالہ بخاری بیان کیا ہے کہ انہوں نے فرمایا: یہ مرسل حدیث ہے: احتمال ہے کہ ان کے مرسل ہونے سے مراد وہ شخص ہو کہ سند میں ان کا نام نہیں لیا گیا، اور وہ اکثر محدثین کے نزدیک مرسل ہے، بلکہ یہ ان کے حکم میں ہے۔ احتمال ہے کہ وہ عنعنہ ہو اور ان کے نزدیک ان کا صحابی ہونا ثابت نہ ہوا ہو۔ بغوی کا قول ہے: مجھے ابوسود کی اس حدیث کے علاوہ کوئی حدیث معلوم نہیں، اور میں نہیں جانتا کہ معمر کے علاوہ کسی نے روایت کیا ہو۔","",{"fn":"(1) اسد الغابہ (۵۹۸۳) تجرید (۱۷۶/۲)\n(2) مسند احمد (۷۶/۵) مجمع الزوائد (۱۷۹/۴)"}],[8674,"§۱۰۰۶۳ ۔ ابوسوید انصاری\nبعض کا قول ہے جھنی، اسماء میں سوید جھنی کے سوانح میں گزر چکے ہیں۔"],[8675,"§۱۰۰۶۴ ۔ ابوسوید(1)\nبغوی نے اور ابو علی بن سکن نے صحابہ رضی اللہ عنہم میں ان کا ذکر کیا ہے۔ اور ابو بشر دولابی نے کنیوں میں ان کے علاوہ سے راویوں نے ہشام بن سعد کے طریق سے طوالہ اصحاب رسول صلی اللہ علیہ وسلم میں سے ایک شخص ابوسوید سے روایت کیا ہے کہ نبی کریم صلی اللہ علیہ وسلم نے سحری کھانے والوں کے لیے دعا مانگی۔(2) اسی طرح جنہوں نے صحابہ رضی اللہ عنہم کے بارے میں کتابیں لکھیں، انہوں نے دال کے ساتھ لکھا ہے۔","",{"fn":"(1) اسد الغابہ (۵۹۸۴) تجرید (۱۷۶/۲)\n(2) المعجم الکبیر (۸۴۵/۲۲) مجمع الزوائد (۱۵۱/۳) جامع المسانید والسنن (۱۴۷/۱۴) کشف (۹۷۴)"}],[8676,"§۱۰۰۶۵ ۔ ابوسیارہ متعی(1)\nبغوی کا قول ہے: شام میں رہے، بعض نے کہا: ان کا نام عمر ہے، کسی نے کہا: عمیر بن اعلم، ایک قول یہ ہے کہ ان کا نام بن مسلم ہے۔ بقول بعض: عامر بن ہلال۔ ابن سکن وغیرہ نے صحابہ رضی اللہ عنہم میں ان کا ذکر کیا ہے۔ احمد، بغوی، ابن ماجہ وغیرہ نے سلیمان بن موسیٰ کے طریق سے بحوالہ ابو سیارہ متعی روایت کیا ہے، فرماتے ہیں: میں نبی کریم صلی اللہ علیہ وسلم کے پاس کھجور کی زکوۃ لے کر آیا۔ سلیمان نے صحابہ رضی اللہ عنہم میں سے کسی کا زمانہ نہیں پایا، اس وجہ سے یہ سند منقطع ہے۔ بعض لوگوں کا گمان ہے کہ ابو سیارہ لوگوں میں سے تھے جو لوگوں کے ساتھ جاہلیت میں عرفات سے لوٹتے تھے جبکہ ایسا نہیں ہے۔ فاکہی نے ذکر کیا ہے کہ ابو سیارہ پر قصی کے غالب ہونے سے پہلے تھے، یہ اس پر دلالت کرتا ہے کہ زمانہ نبوت سے پہلے ان کا زمانہ گزر چکا تھا، ان دونوں کے ان اس تفریق سے اس کو تقویت ملتی ہے کہ یہ متّعی ہیں اور وہ عدوانی ہیں۔ بعض کا قول ہے: عامری، بنو عامر بن لوی سے ہیں۔ کا نام عمر و یا عمیر یا عامر ہے۔ اور ان کا نام عمیلہ بنت اعزل عدوانی ہے، بعض نے کہا: بنوعبد بن بغیض بن عامر بن لوی سے ہیں۔ وہ عرفہ سے قیس کے پاس ہوتے ہوئے گزرتے کیونکہ وہ ان کے ماموں تھے۔ اسے زبیر بن بکار نے نقل کیا ہے، اور محمد بن مخزومی سے بھی نقل کیا ہے کہ ابو سیارہ گدھے پر سوار ہو کر عرفات سے لوٹتے تھے، ان کے گدھے نے بیمار ہوئے بغیر چالیس سال کی عمر پائی، یہاں تک کہ ضرب المثل بن گئی۔ لوگ کہنے لگے: ابوسیارہ کی سواری سے زیادہ صحت مند، وہ شخص جو عرفات سے واپس آتا تھا وہ بعثت سے قبل فوت ہو گیا وہ مکھی کے علاوہ کوئی اور ہے، جنہوں نے کھجور کے عشر و زکوۃ کے بارے میں پوچھا تھا۔ واللہ اعلم","",{"fn":"(1) اسد الغابہ (۵۹۸۷) تجرید (۱۷۶/۲)"}],[8677,"§۱۰۰۶۶ ۔ ابوسیف القین(1)\nوہ لوہار ہیں، انصار میں سے ہیں، ام سیف کے شوہر ہیں جو نبی کریم صلی اللہ علیہ وسلم کے صاحبزادے سیدنا ابراہیم علیہ السلام کو دودھ پلاتی تھیں۔ صحیحین میں ثابت کے طریق سے بحوالہ انس ان کا ذکر ثابت ہے۔ فرماتے ہیں: نبی کریم صلی اللہ علیہ وسلم نے فرمایا: آج میرے ہاں لڑکا پیدا ہوا، میں نے اس کا نام اپنے والد ابراہیم کے نام پر رکھا اور اسے ام سیف جو مدینہ میں ایک لوہار جسے ابوسیف کہا جاتا تھا، اس کی بیوی کے حوالہ کیا ہے۔(2) فرماتے ہیں: ہم ابوسیف کے پاس پہنچے وہ اپنی بھٹی میں پھونک رہا تھا۔ گھر دھوئے سے بھر گیا تھا۔ میں جلدی سے ابوسیف کے پاس گیا، میں نے کہا: ابوسیف رُک جاؤ! رسول اللہ صلی اللہ علیہ وسلم تشریف لائے ہیں، پھر حدیث ذکر کی۔ یہ مسلم کے الفاظ ہیں، بخاری کی روایت میں ہے ہم نبی کریم صلی اللہ علیہ وسلم کے ساتھ ابوسیف لوہار کے پاس آئے، وہ نبی کریم صلی اللہ علیہ وسلم کے صاحبزادے سیدنا ابراہیم علیہ السلام کے رضاعی باپ تھے، آپ صلی اللہ علیہ وسلم نے اسے اٹھایا اور بوسہ دیا۔۔۔۔ (الحدیث) براء بن اوس کے سوانح میں گزر چکا ہے کہ نبی کریم صلی اللہ علیہ وسلم نے اپنے صاحبزادے سیدنا ابراہیم کو ام بردہ بنت منذر کے سپرد کیا جو براء بن اوس کی زوجہ تھیں، وہ انہیں دودھ پلاتی تھیں، نبی کریم صلی اللہ علیہ وسلم ان کے پاس آتے، ان سے ملاقات کرتے، یہاں قیلولہ فرماتے۔ اسے واقدی نے نقل کیا ہے، اگر یہ ثابت ہے تو اس کا احتمال ہے کہ ام بردہ نے انہیں دودھ پلایا، پھر ام سیف کے حوالہ کر دیا، اگر ایسا نہیں تو جو صحیح میں ہے وہی قابل اعتماد ہے۔","",{"fn":"(1) اسد الغابہ (۵۹۸۸) تجرید (۱۷۶/۲)\n(2) بخاری (۱۳۰۳) مسلم (۵۹۷۹) مسند احمد (۱۹۴/۳)"}],[8678,"§۱۰۰۶۷ ۔ ابوسیلان\nابن حبان نے صحابہ رضی اللہ عنہم میں، کنیتوں میں ان کا ذکر کیا ہے۔ جو حرف سین میں ہے۔ فرماتے ہیں: بعض نے کہا کہ انہیں شرف صحابیت حاصل ہے یہ عبادلہ عبداللہ بن سیلان میں گزر چکا ہے۔ احتمال ہے کہ یہ ان کی کنیت ہے۔"],[8679,"§۱۰۰۶۸ ۔ ابوسعد\nمالک بن اوس بن حدثان نصری، اسماء میں ان کا ذکر گزر چکا ہے۔"],[8680,"§۱۰۰۶۹ ۔ ابوسعد\nیا ابوسعید بن حارث... مخزومی، ابو الفرج اصبہانی نے ذکر کیا ہے کہ خالد بن عاص بن ہشام نے ان کی بیٹی فاطمہ سے نکاح نا سے حارث بن خالد پیدا ہوئے، جنہیں مکہ کا امیر بنایا گیا۔ عاص بن ہشام بدر میں قتل ہوا، اس کے بیٹے کو شرف صحابیت ہے، حارث بن ہشام مشہور صحابی ہیں۔ خلافت عمر میں شہید ہوئے۔ ابو سعد نبی کریم صلی اللہ علیہ وسلم کے زمانے میں کم عمر تھے۔ زبیر بن بکار نے ذکر کیا ہے کہ صحرہ بنت ابو جہل بن ہشام ان ابوسعد کی زوجہ تھیں، ان سے اولاد ہوئی۔"],[8681,"§۱۰۰۷۰ ۔ ابوساسان\nبن منذر، رقاشی، اسماء میں ان کا ذکر گزر چکا ہے حاکم نے عشرہ مبشرہ سے سماعت کرنے والوں میں انہیں شمار کیا ہے۔"],[8682,"§۱۰۰۷۱ ۔ ابوسعیف\nبن قیس بن حارث بن عباس، انہوں نے نبوت کا زمانہ پایا اور خلافت ابوبکر میں یرموک میں شامل ہوئے۔ مصر کی فتح میں تھے پھر وہاں سکونت اختیار کی، مروان بن حکم مصر میں خلافت کے سپرد کیے جانے کے بعد آئے وہاں کے لوگوں نے ان سے مانگا کیونکہ اس سے پہلے وہ ابن زبیر سے بیعت کر چکے تھے۔ وہ ان کے روکنے والے چند افراد میں سے تھے۔ خرسان سے تھے، وان غالب ہو گیا تو یہ ابو کیف طرابلس کی طرف بھاگ گئے اور اپنی وفات تک وہیں رہے۔"],[8683,"§۱۰۰۷۲ ۔ ابوسعید مقبری\nان کا نام کیسان ہے جیسا کہ اسماء میں گزر چکا ہے۔"],[8684,"§۱۰۰۷۳ ۔ ابوسعید(1)\nابواسید ساعدی کے موالی ہیں، ابن مندہ نے صحابہ میں ان کا ذکر کیا ہے۔ لیکن کوئی ایسی بات ذکر نہیں کی جو ان کے صحابی ہونے پر دلالت کرتی ہو۔ لیکن ثابت ہے کہ انہوں نے سیدنا ابو بکر صدیق رضی اللہ عنہ کا زمانہ پایا، تو یہ اس قسم میں سے ہیں۔ ابن مندہ کا قول ہے ابو نضرہ عبدی نے سیدنا عثمان رضی اللہ عنہ کی شہادت کا طویل قصہ روایت کیا ہے۔ وہ ان کی روایت کی ہے۔ ہم نے اسے اس طریق سے روایت کر دیا ہے۔ اس میں کوئی ایسی بات نہیں جو ان کے صحابی ہونے پر دلالت کرتی ہو۔","",{"fn":"(1) اسد الغابہ (۵۹۵۱) تجرید (۱۷۳/۲)"}],[8685,"§۱۰۰۷۴ ۔ ابو سلمہ\nتمیم بن حدیم، اسماء میں ان کا ذکر گزر چکا ہے۔"],[8686,"§۱۰۰۷۵ ۔ ابو سمال اسدی\nسمعان بن ہیرہ میں ان کا ذکر گزر چکا ہے۔"],[8687,"§۱۰۰۷۶ ۔ ابو سُوَید عبدی\nانہوں نے نبوت کا زمانہ پایا، بخاری نے کنیتوں میں ان کا ذکر کیا ہے۔ حاکم ابواحمد نے ان کی پیروی کی ہے، اور وکیع کے سے بحوالہ ابوسوید عبدی نقل کیا ہے۔ فرماتے ہیں: ہم سیدنا عمر رضی اللہ عنہ کے دروازے پر تھے۔ پھر قصہ ذکر کیا۔ اسے ابو عقیل نے بحوالہ ابوسوید عبدی نقل کیا ہے، فرماتے ہیں: ہم ابن عمر کے پاس آئے اور ان کے دروازے پر گئے... پھر قصہ ذکر کیا، حدیث کو احمد نے نقل کیا ہے، وکیع، ابو عقیل سے زیادہ حافظہ والے ہیں۔ واللہ اعلم"],[8688,"§۱۰۰۷۷ ۔ ابوسبرہ نخعی\nصحیح یہ ہے کہ یہ بھی ہیں جن کا ذکر قسم اول میں گزر چکا ہے۔ ابن مندہ نے لفظی غلطی کی ہے۔"],[8689,"§۱۰۰۷۸ ۔ ابو سعد اعمی\nتابعی ہیں، ان کی حدیث مرسل ہے۔ بعض نے صحابہ میں ان کا ذکر کیا ہے۔ حمیدی کا قول ہے: ہم سے سفیان نے \" ابو سعد اعمی نقل کیا ہے۔ رسول اللہ صلی اللہ علیہ وسلم نے ایک آزاد شخص کو قرض کی وجہ سے بیچ دیا۔ ابواحمد حاکم نے کنیتوں میں ان لوگوں میں کا ذکر کیا ہے جن کا نام معلوم نہیں، فرماتے ہیں: وہ سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت کرتے ہیں۔ (یعنی اس آزاد شخص پر اتنا ہو گیا کہ خود اس کی اپنی قیمت لگ گئی)۔"],[8690,"§۱۰۰۷۹ ۔ ابوسعید بن وہب قرظی(1)\nابن اثیر نے ان کا ذکر کیا ہے۔(2) ان کی کنیت میں وہم ہے۔ وہ ابوسعد ہیں۔ جیسا کہ گزر چکا ہے، وہ نفری ہیں۔ سے ہیں، بنو قریظہ سے ہیں۔","",{"fn":"(1) اسد الغابہ (۵۹۴۸) تجرید (۱۷۳/۲)\n(2) اسد الغابہ (۴۶۶/۴)"}],[8691,"§۱۰۰۸۰ ۔ ابوسعید(1)\nبے نسبت، ان سے مکمل نے روایت کی ہے، اسے ابن عبدالبر نے مختصر نقل کیا ہے۔ اسی طرح ابن اثیر(2) نے ان کا ذکر کیا ہے۔ جو استیعاب میں ہے۔ ابوسعدان ہیں، جیسا کہ گزر چکا ہے۔","",{"fn":"(1) اس نمبر میں ان کے سوانح گزر چکے ہیں (۹۹۸۶)\n(2) اسد الغابۃ (۴۶۶/۴)"}],[8692,"§۱۰۰۸۱ ۔ ابو سفینہ\nحارث بن عمرو اسلمی: اسی طرح عبد الغنی کے کمال میں واقع ہے، مزی نے اس کا اقرار کیا ہے، صحیح یہ ہے کہ ابو سفینہ میم میں ان کا ذکر آئے گا۔"],[8693,"§۱۰۰۸۲ ۔ ابو سلام اسلمی\nابو موسیٰ نے علیحدہ ان کا ذکر کیا ہے، انہیں وہم ہوا ہے جیسا کہ میں نے خبر دار کیا ہے۔"],[8694,"§۱۰۰۸۳ ۔ ابوسلمہ انصاری(1)\nعبدالحمید بن سلمہ کے دادا ہیں، نبی کریم صلی اللہ علیہ وسلم نے انہیں ان کے ماں باپ کے پاس جانے کا اختیار دیا، ان کا نام رافع ہے، اسی طرح ابو موسیٰ کا قول ہے، صحیح یہ ہے کہ عبدالحمید کے دادا کا نام سلمہ ہے، اور وہ اپنے دادا کی روایت میں عبدالحمید بن زید ہیں۔ رہے رافع عبدالحمید کے دادا تو وہ اس کے علاوہ ہیں وہ عبدالحمید بن جعفر ہیں۔","",{"fn":"(1) ۱۰۰۸۳ میں ان کے سوانح گزر چکے ہیں۔"}],[8695,"§۱۰۰۸۴ ۔ ابوسلمہ خدری\nبعض نے صحابہ میں ان کا ذکر کیا ہے، وہ خطا ہے جو ساقط کرنے سے پیدا ہوئی صحیح یہ ہے بحوالہ ابوسلمہ اور وہ ابن عبدالرحمن والہ خدری اور وہ ابوسعید ہیں، سند سے عن ساقط کر دیا گیا تھا۔ واللہ اعلم"],[8696,"§۱۰۰۸۵ ۔ ابوسلیمان\nجبیر بن مطعم کی اولاد میں سے ہیں۔ بغوی نے صحابہ میں ان کا ذکر کیا ہے۔ فرماتے ہیں: مدینہ میں سکونت اختیار کی، ان کے ان میں یہ غلط ہے کہ انہیں شرف صحابیت حاصل ہے، انہوں نے زہیر بن محمد کی روایت سے بحوالہ عثمان بن ابوسلیمان، انہوں نے اپنے والد سے نقل کیا ہے کہ انہوں نے مغرب کی نماز میں سورہ طور پڑھی۔ ابن سکن کا قول ہے صحیح یہ ہے جو سعید بن سلمہ بن ابو حسام نے بحوالہ والد نافع بن جبیر بن مطعم روایت کیا ہے۔ فرماتے ہیں: ابن جریج نے بحوالہ جبیر روایت کیا ہے، دار قطنی کا قول ہے: اگر زہیر نے عن ابیہ سے مراد اپنے قریب کا جد لیا ہے تو وہ ہے، کیونکہ ابوسلیمان وہ ابن جبیر بن مطعم ہیں، انہیں شرف صحابیت حاصل نہیں، اگر ان سے مراد دور کے جد ہیں تو وہ ابن جریج کی روایت کی طرح ہے، صحیح یہ ہے: سعید بن سلمہ کی روایت۔ واللہ اعلم"],[8697,"§۱۰۰۸۶ ۔ ابو سہلہ\nمولی عثمان، بعض کا قول ہے: ابو شہلہ۔ بعض نے کہا: انہیں شرف صحابیت حاصل ہے، ان سے خسیس بن ابوحازم نے روایت کی، اسی طرح تجرید میں ہے، ان کے ہونے پر کسی نے تنبیہ نہیں کی، انہوں نے اپنے مولیٰ عثمان سے اور سیدہ عائشہ رضی اللہ عنہا سے سیدنا عثمان رضی اللہ عنہ کے فضائل کے بارے میں حدیث روایت کی بعض نے اسے مرسل کہا ہے: جیسا کہ ابواحمد حاکم نے ان کے سوانح میں نقل کیا ہے، ترمذی، ابن ماجہ، مذکور، حدیث کو اسماعیل بن ابو خالد کے طریق سے بحوالہ سیدہ عائشہ رضی اللہ عنہا نقل کیا ہے۔ بخاری، ابن حبان، عجلی وغیرہ نے تابعین میں ان کا ذکر کیا ہے۔ دار قطنی نے ذکر کیا ہے کہ محمد بن بشر نے اسے اپنی سند میں بحوالہ اسماعیل بن ابو خالد نقل کیا ہے۔"],[8698,"§۱۰۰۸۷ ۔ ابوشاہ یمانی(1)\nبعض نے کہا: وہ کلبی ہیں، بعض نے کہا: وہ فارسی ہیں، ان لوگوں میں سے ہیں جو یمن سے سیف بن ذی یزن کی نصرت کے لئے آئے، اسی طرح جس نے سلفی کی تحریر میں دیکھا ہے، بعض نے کہا: فارسی میں اس کا مطلب بادشاہ ہے، فرماتے ہیں: جس نے گمان کیا کہ وہ شاہوں میں سے کسی کا نام ہے، اس نے وہم کیا۔ صحیحین میں ان کا ذکر حدیث ابو ہریرہ رضی اللہ عنہ سے ثابت ہے، جب نبی کریم صلی اللہ علیہ وسلم نے فتح کے دن خطبہ میں فرمایا: ایک شخص جسے ابوشاہ کہا جاتا تھا اس نے کہا: یا رسول اللہ صلی اللہ علیہ وسلم مجھ کو لکھ دیجئے، آپ صلی اللہ علیہ وسلم نے فرمایا: ”ابوشاہ کو لکھ کر دو۔“(2) یعنی مذکورہ خطبہ۔","",{"fn":"(1) اسد الغابہ (۵۹۸۹) الاستيعاب (۳۰۶۹) تجرید (۱۷۶/۲)\n(2) مسند احمد (۲۳۸/۸)"}],[8699,"§۱۰۰۸۸ ۔ ابوشبات\nان کا نام خدیج بن سلامہ ہے۔ ان کا ذکر گزر چکا ہے۔"],[8700,"§۱۰۰۸۹ ۔ ابوشبیب(1)\nبے نسبت۔ بے نام، تجرید میں اور مسند بقی بن مخلد میں ان کا ذکر ہے۔","",{"fn":"(1) اسد الغابۃ (۵۹۹۱) تجرید (۱۷۷/۲)"}],[8701,"§۱۰۰۹۰ ۔ ابوشجرہ سلمی(1)\nعمرو بن عبد العزی میں ان کا ذکر گزر چکا ہے، بعض نے کہا: ان کا نام سلیم بن عبد العزی ہے، ان کی والدہ خنساء شاعرہ ہیں، وہ دیہات میں رہتے تھے۔ زبیر بن بکار نے خالد بن ولید کے سوانح میں ذکر کیا ہے۔ فرماتے ہیں: ابوشجرہ بن عبدالعزی سلمی نے خالد کے مرتدین سے قتال کے بارے میں فرمایا: ش ”اگر سلمی جنگ کی صبح پوچھے، جیسے اگر میں اس سے دور ہو جاؤں تو اس سے پوچھوں، لوی بن غالب کے خاندان میں جنگ کی صبح نیزہ بازی میری ایک ضرورت تھی جو میں نے پوری کر دی، اسی طرح کہتے ہیں میں نے خالد کے لشکر سے اپنے نیزے کو سیراب کر دیا، اور اس کے بعد مجھے امید ہے کہ میں لمبی عمر جیوں گا۔“ میں کہتا ہوں: اس شعر تک اس کا قصہ عمر کے ساتھ ہے، مبرد نے کامل میں ان کا ذکر کیا ہے، ابو شجرہ عمر کے پاس سواری کا اونٹ مانگنے آئے، انہوں نے پوچھا: تم کون ہو؟ اس نے کہا: میں ابو شجر مسلمی ہوں، آپ نے فرمایا: اے اپنی جان کے دشمن! کیا تم نے یہ شعر نہیں کہے پھر شعر کا ذکر کیا، پھر ڈرے کو اٹھانے کے لئے جھکے تو وہ بھاگ نکلے، اور اپنی اونٹنی پر سوار ہو گئے وہ کہہ رہے تھے: ش ”ابو حفص نے ہمیں ہدیہ دینے میں بخل کیا، ہر زور سے مارنے والے کا ایک دن پتہ ہوتا ہے۔“ میں نے ان کا اس قسم میں ذکر کیا ہے کیونکہ خنساء اور ان کی اولاد اسلام لائی، جیسا کہ میں عنقریب ان کے سوانح میں ذکر کروں گا۔ مرز بانی نے فرمایا: بعض نے کہا: ان کا نام عمرو ہے بعض نے کہا: عبداللہ بن عبدالحری... بن سلیم، بعض نے کہا: عمرو بن حارث بن مخضرم، بہت زیادہ شعر کہنے والے تھے، ان کا سیدنا عمر کے ساتھ قصہ مشہور ہے یعنی ماضی کی خبر، ان کے عباس بن مرداس کے بارے میں اشعار ہیں وہ ان میں کہتے ہیں: ش ”عباس میرے لئے آرزوئیں چلاتا ہے اور میں نے صحر کے علاوہ کوئی گناہ نہیں کیا۔“ باقی خبر عمرو بن عبد العزی کے سوانح میں واقدی کی کتاب الردۃ میں ہے۔","",{"fn":"(1) الکامل (۳۸۸/۱) تجرید (۱۷۷/۲)"}],[8702,"§۱۰۰۹۱ ۔ ابوشجرہ کندی\nان کا نام معاویہ بن محصن ہے، ان کا ذکر گزر چکا ہے۔"],[8703,"§۱۰۰۹۲ ۔ ابوشجرہ رہاوی\nیزید بن شجرہ، ان کا ذکر گزر چکا ہے۔"],[8704,"§۱۰۰۹۳ ۔ ابوشراک فہری(1)\nبنوضبہ بن حارث بن فہر سے ہیں، واقدی اور ابو معشر نے اہل بدر میں ان کا ذکر کیا ہے، ان کا نام عمرو بن ابو عمرو ہے، محمد بن سعد نے یہ جائز قرار دیا ہے کہ وہ عمرو بن حارث ہیں جن کا ذکر پہلے گزر چکا ہے، کہ موسیٰ بن عقبہ نے ان کا ذکر کیا، واقدی کا قول ہے، ابوشراک ۳۶ ھ میں فوت ہوئے۔(2)","",{"fn":"(1) اسد الغابہ (۵۹۹۵) تجرید (۱۷۷/۲)\n(2) طبقات الکبریٰ (۳۰۴/۳)"}],[8705,"§۱۰۰۹۴ ۔ ابوشریح خزاعی(1)\nپھر کبھی، خویلد بن عمرو، بعض کا قول ہے، عمرو بن خویلد، بعض نے کہا: ھانی، کسی نے کہا: کعب بن عمرو، ایک قول ہے عبدالرحمن۔ پہلا قول زیادہ مشہور ہے، ابو عمیر اور ابو خیمہ نے کعب کا یقین کیا ہے۔ ھارون العمال نے خویلد اور کعب میں تردد کیا ہے۔ طبری(2) کا قول ہے: وہ خویلد بن عمرو بن صحر بن عبد عزی بن معاویہ بن بنو عدی بن عمرو بن ربیعہ سے ہیں، فتح سے پہلے اسلام لائے، ان کے پاس فتح کے دن خزاعہ کا جھنڈا تھا۔ انہوں نے نبی کریم صلی اللہ علیہ وسلم سے کئی احادیث روایت کیں۔ سیدنا ابن مسعود رضی اللہ عنہ سے بھی روایت کی، ان سے نافع بن جبیر بن مطعم، ابوسعید مقبری، ان کے بیٹے سعید بن ابوسعید، فضیل والد حارث، سفیان بن ابو عوجاء نے روایت کی۔ ابن سعد(3) کا قول ہے: مدینہ میں ۶۸ ھ میں وفات پائی۔ طبقات نے خندقین میں ان کا ذکر کیا ہے، فرماتے ہیں: فتح سے پہلے اسلام لائے، اسی طرح کئی ایک نے ان کی وفات کی تاریخ کے بارے میں کہا۔ ان کا عمرو بن سعید اشدق کے ساتھ ایک واقعہ پیش آیا جب وہ یزید بن معاویہ کی طرف سے مدینہ کے امیر تھے، صحیحین میں ہے کہ ابو شریح نے عمرو سے کہا: وہ مکہ کی طرف لشکر کشی کرنے والے تھے، مجھے اجازت دیجئے اے امیر المؤمنین! کہ آپ سے ایک حدیث بیان کروں... پھر حدیث کا ذکر کیا کسی کے لئے جائز نہیں کہ مکہ میں خون بہائے... اس میں عمرو بن سعید کا قول ہے: حرم کسی گنہگار کو پناہ نہیں دیتا، طبری(4) کا قول ہے، ۶۸ ھ میں مدینہ میں وفات پائی۔","",{"fn":"(1) اسد الغابہ (۵۹۹۷) الاستيعاب (۳۰۷۲) تجرید (۱۷۷/۲)\n(2) تاریخہ (۳۳۹/۵)\n(3) طبقات الکبریٰ (۳۲/۴)\n(4) تاریخہ (۳۳۶/۵)"}],[8706,"§۱۰۰۹۵ ۔ ابوشریح حارثی\nان کا نام ھانی بن یزید ہے، اسماء میں ان کا ذکر گزر چکا ہے، آپ صلی اللہ علیہ وسلم نے ان کے سب سے بڑے بیٹے پر ان کی کنیت رکھی۔"],[8707,"§۱۰۰۹۶ ۔ ابوشریح انصاری(1)\nابو عمر کا قول ہے۔ میں ان کی کنیت کے بغیر انہیں نہیں جانتا، اور اسی طرح ان کا ذکر کیا ہے، انہوں نے صحابہ میں ان کا ذکر کیا ہے۔ میں کہتا ہوں: مستغفری کی کتاب میں ہے: ابو شریح، بے نسبت ہیں۔ اور ان کی انصار کی طرف نسبت نہیں کی، مجھے معلوم نہیں، وہ ایک ہیں یا دو ہیں، پھر مجھے معلوم ہوا کہ وہ جن کا مستغفری نے ذکر کیا ہے وہ ابوشریح خزاعی ہے۔ انہوں نے ان کا ذکر کیا کہ وہ کہتے ہیں: وہ خزاعی ہیں، انہوں نے ذکر کیا ہے کہ انہوں نے نبی کریم صلی اللہ علیہ وسلم سے روایت کی ہے کہ آپ فرماتے ہیں: وہ اللہ تعالیٰ کے ہاں سب سے سرکش شخص وہ ہے جو اپنے (مقتول) کے قاتل کے علاوہ کسی اور کو قتل کر دے۔(2) یہ ابو شریح خزاعی کی حدیث ہے، اسے عبداللہ بن احمد نے مسند کی زیادات میں عبدالرحمن بن اسحاق کے طریق سے بحوالہ ابو شریح، مسند ابو شریح خزاعی میں نقل کیا ہے۔","",{"fn":"(1) اسد الغابہ (۶۰۰۳) الاستيعاب (۳۰۷۳) تجرید (۱۷۷/۲)\n(2) مسند احمد (۳۲/۴) مجمع الزوائد (۱۷/۷)"}],[8708,"§۱۰۰۹۷ ۔ ابوشعیب لحام(1)\nانصار سے ہیں، صحیح میں حدیث ابو مسعود بدری میں ان کا ذکر ہے۔ فرماتے ہیں: انصار کا ایک شخص جس کی کنیت ابوشعیب تھی، آیا، اس نے اپنے غلام لحام سے کہا: میرے لئے کھانا بناؤ جو پانچ آدمیوں کو کفایت کرے، پھر نبی کریم صلی اللہ علیہ وسلم کو بلایا۔ امالی الحاملی کے جزء نو میں ہمیں یہ روایت ملی اور بغوی کی کتاب میں، ابن سکن، ابن مندہ کے ہاں عبداللہ بن نمیر کے طریق سے بحوالہ انصار کے ایک شخص جسے ابوشعیب کہا جاتا ہے فرماتے ہیں: میں نبی کریم صلی اللہ علیہ وسلم کے پاس آیا، میں نبی کریم صلی اللہ علیہ وسلم کے پاس آیا، اور آپ کے چہرے پر بھوک کے اثرات دیکھے... پھر حدیث ذکر کی۔ ابن مندہ کا قول ہے: اسے ثوری اور شعبہ اور عباس نے روایت کیا ہے، اور بحوالہ ابوشعیب نہیں لکھا، فرماتے ہیں: ابوشعیب نامی ایک شخص سے روایت ہے، پھر زہیر بن معاویہ اور عمار بن زریق کے طریق سے بحوالہ جابر کہ ایک شخص جسے ابوشعیب کہا جاتا ہے.... پھر حدیث ذکر کی۔","",{"fn":"(1) اسد الغابۃ (۶۰۰۱) تجرید (۱۷۷/۲)"}],[8709,"§۱۰۰۹۸ ۔ ابوشقرہ تمیمی(1)(2)\nان سے مخلد بن عقبہ نے روایت کی، ابوعمر نے مختصر ان کا ذکر کیا ہے۔ ابو موسیٰ فرماتے ہیں، بیٹی بن مندہ نے اپنے دادا پر استدراک میں ان کا ذکر کیا ہے اور ان کی حدیث بیان کی ہے، ان کے دادا نے ان کا ذکر کیا ہے مگر یہ کہ ان کی حدیث کا ذکر نہیں کیا۔ اسے ابونعیم نے حسن بن سفیان کے طریق سے پھر حماد بن یزید منقری کی روایت سے بحوالہ ابوشقرہ روایت کیا ہے۔ فرماتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ”جب تم سائے کو اس طرح دیکھو کہ ان کے سروں پر اونٹوں کی کوہانوں کی طرح ہے تو انہیں بتاؤ کہ ان کی نماز قبول نہیں۔“(3) بعض راویوں نے کہا: الفی سے مراد فرع (شاخ) ہے۔","",{"fn":"(1) اسد الغابہ (۶۰۰۲) تجرید (۱۷۷/۲)\n(2) المعجم الکبیر (۳۷۰/۲۲) مجمع الزوائد (۱۳۷/۵)\n(3) جامع المسانید والسنن (۱۷۳/۱۴)"}],[8710,"§۱۰۰۹۹ ۔ ابوشماس بن عمر جذامی(1)\nابن اسحاق نے جذام کے وفد میں ان کا ذکر کیا ہے، جو لوگ نبی علیہ السلام کے پاس اپنی قوم کے اسلام کے لئے آئے اور اپنے قیدیوں کو واپس مانگا جنہیں زید بن حارثہ نے قیدی بنایا تھا۔","",{"fn":"(1) تجرید (۱۷۸/۲)"}],[8711,"§۱۰۱۰۰ ۔ ابو شمر ضبابی\nوہ ذوالجوشن ہیں، جن کا ذکر پہلے گزر چکا ہے۔"],[8712,"§۱۰۱۰۱ ۔ ابو شمر بن ابرہہ\nبن شرحبیل بن ابرہہ بن صباح حمیری پھر ابرھی، رشاطی نے بحوالہ ہمدانی حمیر کے انساب میں ان کا ذکر کیا ہے۔ وہ نبی کریم صلی اللہ علیہ وسلم کے پاس وفد کی صورت میں آئے اور سیدنا علی رضی اللہ عنہ کے ساتھ صفین میں شہید ہوئے۔ رشاطی کا قول ہے: ابن عبدالبر نے اور ابن فتحون نے اس کا ذکر نہیں کیا، ابن مندہ کا قول ہے: ابو شمر بن ابرہہ بن صباح اصحی، بعض نے کہا: انہیں شرف صحابیت حاصل ہے۔ اخبار میں ان کا ذکر ہے۔ میں کہتا ہوں: ان دونوں کے علاوہ راویوں نے ذکر کیا ہے کہ وہ سیدنا عمر رضی اللہ عنہ کے عہد میں وفد کے ساتھ آئے تو ان سے بنت ابوموسیٰ اشعری نے نکاح کیا یہ بھی احتمال ہے کہ پہلے یہ وفد آیا ہو پھر اپنے ملک کی طرف لوٹ گیا ہو، پھر دوبارہ وفد آیا یا ہو جب سیدنا عمر رضی اللہ عنہ نے لوگوں کو جہاد کی طرف بلایا، پھر میں نے اسے تاریخ دمشق میں پایا، فرماتے ہیں: ابو شمر بن ابرہہ بن صباح بن لہیعہ بن شیبہ بن مرہ، پھر فرماتے ہیں: کریب بن ابرہہ کے بھائی، پھر فرماتے ہیں وہ مصری ہیں۔ پھر فرمایا: بعض کا قول ہے: وہ رسول اللہ صلی اللہ علیہ وسلم کے پاس وفد آیا پھر کئی طرق سے حدیث روایت کی: بحوالہ ابن وہب، انہوں نے حارث بن یزید سے روایت کی کہ سیدنا عبداللہ بن سعد نے اساور میں ۳۱ ھ میں جہاد کیا، معاویہ بن خدیج کی آنکھ شہید ہو گئی، ابو شمر بن ابرہہ، جندل بن شریح شہید ہو گئے، ان کا نام غزوہ خندق کے تیر اندازوں میں لیا جاتا ہے۔ یجی بن بکیر کے طریق سے بحوالہ لیث مروی ہے کہ وہ ان لوگوں کے ساتھ تھے جو ابن ابو حذیفہ کے ساتھ معاویہ کے پاس رہن رکھئے گئے، پھر انہوں نے قید خانے کو توڑا اور نکلے، ابو شمر رک گئے، انہوں نے کہا، میں اس میں قیدی بن کر داخل نہیں ہوں گا، وہ وہاں سے فرار ہوئے اور اقامت پذیر ہوئے۔ پھر میں نے مقدمہ کتاب انساب میں جو سمعانی کی کتاب ہے۔ اس میں ان کا ذکر بطریق ابن لہیعہ، بحوالہ ربیعہ بن قیس پایا۔ سیدنا علی رضی اللہ عنہ کو فرماتے ہوئے سنا، تین قبائل کہتے ہیں کہ وہ عرب ہیں۔ وہ عرب سے بھی قدیم ہیں، جرھم وہ عاد کے بقیہ لوگ ہیں، ثقیف وہ خمود کے بقیہ لوگ ہیں، ابو شمر بن ابرہہ آگے بڑھے اور فرمایا: اور یہ قوم وہ تبع کے باقی لوگ ہیں۔"],[8713,"§۱۰۱۰۲ ۔ ابوشموس بلوی(1)\nابن سکن کا قول ہے: انہیں شرف صحابیت اور روایت حاصل ہے۔ ان کا نام معلوم نہیں، بغوی کا قول ہے: شام میں رہے، ابن حبان کا قول ہے۔ بعض نے کہا: انہیں شرف صحابیت حاصل ہے۔ میں کہتا ہوں: بخاری رحمہ اللہ نے ان کی تعلیقاً حدیث ذکر کی ہے اور کتاب الکنی المفردہ میں اسے موصولاً نقل کیا ہے۔ ہمیں طبرانی کی معجم کبیر میں یہ عالی سند سے ملی ہے لیکن اس سند میں ضعف ہے۔ وہ سلیمان بن مطیر کے طریق سے بحوالہ ابو شموس بلوی مروی ہے کہ نبی کریم صلی اللہ علیہ وسلم نے اپنے ساتھیوں کو بئر حجر سے روکا ہے۔۔۔۔۔ الحدیث۔ بغوی کا قول ہے: ابو شموس کی اس حدیث کے علاوہ کوئی روایت مروی ہے۔ اس کی سند میں ضعف ہے۔","",{"fn":"(1) اسد الغابہ (۶۰۰۳) تجرید (۱۷۷/۲)"}],[8714,"§۱۰۱۰۳ ۔ ابوشمیلہ شنی(1)\nابوسعید بن اعرابی اور مستغفری وغیرہ نے صحابہ میں ان کا ذکر کیا ہے، اور محمد بن اسحاق کے طریق سے بحوالہ ابن عباس نقل کیا ہے۔ فرماتے ہیں: ابو شمیلہ، شنوءۃ کے ایک شخص تھے، ان پر شراب کا نشہ غالب تھا، ایک روایت میں یہ الفاظ ہیں: ابو شمیلہ کو نشے کی حالت میں لایا گیا، وہ کئی بار پی چکے تھے، آپ صلی اللہ علیہ وسلم نے مٹی کی ایک مٹھی لی، اور ان کے چہرے پر مارا، آپ صلی اللہ علیہ وسلم نے فرمایا: ”اسے مارو“(2) لوگوں نے اسے کپڑوں، جوتوں، ہاتھوں اور میخ یعنی ہلکی لاٹھی سے یا تر ٹہنی سے مارا، ابن فتحون نے اپنے استدراک میں ان کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابہ (۶۰۰۴) الاستيعاب (۳۰۷۸) تجرید (۱۷۸/۲)\n(2) السنن الکبریٰ (۳۲۰/۸) (۳۲۱) اسد الغابۃ (۹/۵)"}],[8715,"§۱۰۱۰۴ ۔ ابوشہم\nقسم ثالث میں ان کا ذکر آئے گا۔"],[8716,"§۱۰۱۰۵ ۔ ابوشہم(1)\nصاحب جیدہ، ان کا نام اور نسب معلوم نہیں۔ بغوی کا قول ہے: کوفہ میں رہے، ابن سکن نے ذکر کیا ہے کہ ان کا نام زید یا یزید بن ابوشیبہ ہے، نسائی، بغوی نے یزید بن عطا کے طریق سے بحوالہ ابو شھم ان کی حدیث روایت کی ہے وہ بہت بہادر شخص تھے۔ ان کے پاس سے ایک لونڈی گزری انہوں نے اس کی کمر پر اپنا ہاتھ رکھ دیا۔ فرماتے ہیں: میں نبی کریم صلی اللہ علیہ وسلم کے پاس اگلے دن گیا آپ صلی اللہ علیہ وسلم لوگوں سے بیعت لے رہے تھے، آپ صلی اللہ علیہ وسلم نے ہاتھ پیچھے کر لیا، فرمایا: ”کیا جبیذہ والے سے ہاتھ ملاؤں۔“ میں نے کہا: میں دوبارہ ایسا نہ کروں گا، آپ صلی اللہ علیہ وسلم نے فرمایا: ”ہاں اب اب پھر اس سے بیعت لے لی، اس کی اسناد قوی ہے۔ بعض کا قول ہے: ابو مہم کا نام عبید بن کعب ہے، تابعین میں ابو شہم ہیں جو سیدنا عمر رضی اللہ عنہ سے روایت کرتے ہیں، ان سے اسماعیل بن ابو خالد نے روایت کی، ابو احمد نے صحابہ کے بعد کنتیوں میں ان کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابہ (۶۰۲۴) تجرید (۱۷۸/۲)"}],[8717,"§۱۰۱۰۶ ۔ ابوشیبہ انصاری خدری(1)\nابوزرعہ کا قول ہے: انہیں شرف صحابیت حاصل ہے، ان کا نام معلوم نہیں، ابن سکن کا قول ہے، ان کی ایک حدیث ہے، ان کا نام معلوم نہیں، بغوی کا قول ہے: رومی تھے۔ ابن سعد نے انصار کے تیسرے طبقے میں فرمایا: ابوشیبہ خدری، ہمیں ان کا نام نہیں بتایا، ہمیں ان کا نام، اور نسب انصار کی کتاب میں نہیں ملا، ابن مندہ کا قول ہے، اہل حجاز میں ان کا شمار ہے، طبرانی کا قول ہے: ابوسعید کا بھائی ہے، ابن سکن، طبرانی، بغوی، دولابی اور ابن مندہ نے یونس بن حارث کے طریق سے ان کی حدیث نقل کی ہے، فرماتے ہیں مجھ سے شرس نے بحوالہ اپنے والد نقل کیا ہے، فرماتے ہیں، میں قسطنطنیہ کے غزوے میں سیدنا معاویہ رضی اللہ عنہ کے ساتھ نکلا، جب ہم پہنچے ہم نے پڑاؤ کیا تو ہم نے غیبی آواز سنی، ہم اس کی طرف متوجہ ہوئے، وہ کہنے لگے: میں ابو شیبہ خدری ہوں میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا: ”جس نے اخلاص کے ساتھ گواہی دی کہ اللہ کے سوا کوئی معبود نہیں تو وہ جنت میں داخل ہوگا۔“(2) محمد اسی طرح فرمایا صحیح یہ ہے یزید بن معاویہ ہیں، طبرانی نے قصہ ذکر نہیں کیا، اور سند میں یہ نہیں کہا بحوالہ ان کے والد، ابواحمد حاکم نے دو طریق سے اسے نقل کیا ہے، ابو عمر نے اس کی پیروی کی ہے، ابن عائذ، دولابی، ابن مندہ نے سلیمان بن موسیٰ کوفی کے طریق سے بحوالہ یونس بن حارث نقل کیا ہے، میں نے شرس کو بحوالہ ان کے والد حدیث روایت کرتے ہوئے سنا: فرماتے ہیں: ابوشیبہ خدری وفات پاگئے اور ہم قسطنطنیہ کا محاصرہ کئے ہوئے تھے۔ جب ابو شیبہ کی غیبی آواز آئی، کہنے لگے: اے لوگو! بہت سے لوگوں کے ساتھ میں بھی ان کی طرف متوجہ ہو گیا، تو اس نے سر جھکایا ہوا تھا، انہوں نے کہا: میں رسول اللہ صلی اللہ علیہ وسلم کا ساتھی ہوں، میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا: ”جس نے اخلاص کے ساتھ گواہی دی کہ اللہ کے سوا کوئی معبود نہیں تو وہ جنت میں داخل ہوگا۔“ عمل کرتے رہو اور امید پر نہ بیٹھے رہو، اور فوت ہو گئے ہم نے انہیں اسی جگہ دفن کر دیا۔ ابو حاتم رازی نے کہا: شرس اور ان کے والد دونوں مجہول ہیں۔","",{"fn":"(1) اسد الغابہ (۶۰۰۶) تجرید (۱۷۸/۲)\n(2) المعجم الکبیر (۳۱۳/۱۲) مجمع الزوائد (۱۸/۱)"}],[8718,"§۱۰۱۰۷ ۔ ابوشیبہ\nدوسرے ہیں، بے نسبت، دار قطنی نے علل میں ذکر کیا ہے کہ حماد بن مسلمہ نے بحوالہ ابوشیبہ روایت کیا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”جب تمہارے پاس تمہاری قوم میں سے کوئی آئے تو اس کا مسلمان بھائی اس کے لئے جگہ کشادہ کرے تا کہ وہ بیٹھ جائے۔۔۔ الحدیث۔ اس میں تین چیزیں ہیں جو تمہارے بھائی کی محبت کو خالص کر دیں گی۔ فرماتے ہیں: اسے ابو مطرف بن ابو وزیر نے بحوالہ شیبہ بن عثمان، انہوں نے اپنے چا سے روایت کیا اگر انہوں نے اسے یاد رکھا ہے تو بہت اچھا کیا۔"],[8719,"§۱۰۱۰۸ ۔ ابوشیخ بن ابوثابت(1)\nانصاری خزرجی، حسان بن ثابت کے بھتیجے ہیں، ابن اسحاق نے اُحد و بدر میں شریک ہونے والوں میں ان کا ذکر کیا ہے۔(2) بئر معونہ پر شہید ہوئے، ان کے والد ابی جاہلیت میں فوت ہو گئے تھے۔ واقدی اور ابن کلبی کا قول ہے: وہ ابی بن ثابت حسان کے بھائی ہیں۔ ان کی کنیت ابو شیخ ہے۔ ابن اسحاق نے موسیٰ بن عقبہ کی موافقت کی ہے، فرماتے ہیں اہل بدر میں سے ہیں: ابو شیخ بن ابی بن ثابت، ابن کلبی اس میں موافق نہیں کہ وہ ابو حسان یحیی بن سعید اموی کے بھائی ہیں، بحوالہ ابن اسحاق۔(3)","",{"fn":"(1) اسد الغابہ (۶۰۰۷) الاستيعاب (۳۰۸۱) تجرید (۱۷۸/۲)\n(2) السیرۃ النبویۃ (۲۶۲/۲)\n(3) السیرۃ النبویۃ (۲۶۲/۲)"}],[8720,"§۱۰۱۰۹ ۔ ابوشحمہ\nبن عمر بن خطاب، ایک انتہائی ضعیف روایت میں ہے کہ ان کے والد نے انہیں زنا کی وجہ سے کوڑے مارے جس سے وہ فوت ہو گئے، جو ذقانی نے ان کا ذکر کیا ہے، اگر یہ ثابت ہے تو وہ اس قسم میں سے ہیں۔"],[8721,"§۱۰۱۱۰ ۔ ابوشجرہ\nکثیر بن مرہ، اسماء میں ان کا ذکر گزر چکا ہے۔"],[8722,"§۱۰۱۱۱ ۔ ابو شداد العمانی(1)\nانہوں نے نبی کریم صلی اللہ علیہ وسلم کا زمانہ پایا، اور ان کے سامنے آپ صلی اللہ علیہ وسلم کا خط پڑھا گیا، ایک سو بیس(۱۲۰) سال زندہ رہے بخاری، ابن ابوخیثمہ نے اور سمویہ نے اپنے فوائد میں اور ابن سکن وغیرہ نے ابوحمزہ، عبد العزیز بن زیاد حنظلی کے طریق سے نقل کیا ہے کہ مجھ سے ابوشداد نے جو اہل زمار میں سے ایک شخص ہیں: عمان کی بستیوں میں سے ایک بستی میں روایت کیا، فرماتے ہیں: ہمارے پاس نبی کریم صلی اللہ علیہ وسلم کا ایک خط چمڑے کے ٹکڑے میں آیا: ”محمد رسول اللہ صلی اللہ علیہ وسلم کی طرف سے اہل عمان کی طرف، سلامتی ہو! اما بعد اس گواہی کا اقرار کرو کہ اللہ کے سوا کوئی معبود نہیں اور میں اللہ کا رسول ہوں، زکوۃ دو، مساجد کی طرف قدم اٹھاؤ، اور فلاں فلاں کام کرو، ورنہ میں تم سے جنگ کروں گا“۔(2) ابو شداد کا قول ہے: ہمیں کوئی ایسا شخص نہ ملا جو ہمیں یہ خط پڑھ کر سنائے۔ حتی کہ ہمیں ایک لڑکا ملا، جس نے ہمیں پڑھ کر سنایا۔ میں کہتا ہوں: عمان کا ان دنوں حاکم کون تھا؟ فرماتے ہیں: کسری کے گورنروں میں سے ایک گورنر تھا۔ مطین نے ان ابوحمزہ حنظلی کے طریق سے نقل کیا ہے، فرماتے ہیں: میں نے عمان میں ایک شخص کو دیکھا جس کی کنیت ابو شداد تھی اس کی عمر ایک سو بیس سال تھی۔ ابو عمر کا قول ہے: ابو شداد عمانی زماری، انہوں نے تعاقب کیا ہے کہ زمار صنعاء میں ہے، عمان میں نہیں، اور عمان بحرین کا ضلع ہے، اور زمار اس کی ایک بستی ہے، بعض کا قول ہے: میم بے نقط، یہ رشاطی کا قول ہے، احتمال ہے کہ ابو عمر نے اسے یاد کیا ہے کہ اس کی اصل زمار میں ہے، عمان میں سکونت اختیار کی، اس طرح ابن فتحون نے استیعاب کے اوھام میں قول ابو عمر زماری کا تعاقب کیا ہے، اور ان سے روایت کرنے والے عبد العزیز بن شداد ہیں، وہ ابن زیاد ہیں۔","",{"fn":"(1) اسد الغابہ (۵۹۹۳) الاستيعاب (۳۰۷۰) تجرید (۱۷۷/۲)\n(2) اسد الغابہ (۶/۵) جامع المسانید والسنن (۱۶۰/۱۴) جمع الجوامع (۴۳۴۵)..."}],[8723,"§۱۰۱۱۲ ۔ ابوشدادہ(1)\nدوسرے ہیں، شامی ہیں، دولابی کا قول ہے: ان کا نام سالم ہے۔ ابن مندہ کا قول ہے: سالم بن سالم عیسی حمصی ہیں، ابواحمد حاکم نے کنیتوں میں معن بن عیسی کے طریق سے بحوالہ ابو شداد نقل کیا ہے، وہ نبی کریم صلی اللہ علیہ وسلم کی وفات کے وقت سمجھدار تھے، آپ صلی اللہ علیہ وسلم سے روایت نہیں کی، اور آپ کی ٹیم سے کچھ نہیں سنا، فرماتے ہیں: میں ابوامامہ کے پاس آیا تو وہ مشروب پی رہے تھے، اس کا دو تہائی پی چکے تھے اور ایک تہائی باقی تھا۔ اسے دولابی نے اور ابن مندہ نے اس طریق سے بحوالہ ایک شخص جسے ابوشداد کہا جاتا ہے، انہوں نے ابوامامہ سے روایت کی، ان سے معاویہ بن صالح نے روایت کی۔","",{"fn":"(1) اسد الغابہ (۵۹۹۴) تجرید (۱۷۷/۲)"}],[8724,"§۱۰۱۱۳ ۔ ابوشراحیل\nیا ابوشرحبیل وہ ذوالکلاع حمیری ہیں، اسماء میں ان کا ذکر گزر چکا ہے۔"],[8725,"§۱۰۱۱۴ ۔ ابوشریک(1)\nمستغفری نے صحابہ میں ان کا ذکر کیا ہے اور ابن اسحاق کے طریق سے نقل کیا ہے کہ سیدنا عمر رضی اللہ عنہ نے انہیں زمین عطا کی تھی۔","",{"fn":"(1) اسد الغابہ (۶۰۰۰) تجرید (۱۷۷/۲)"}],[8726,"§۱۰۱۱۵ ۔ ابوشعیب(1)\nبے نسبت، انہوں نے نبوت کا زمانہ پایا، اور بیت المقدس کی فتح میں حاضر ہوئے، احمد نے حماد بن سلمہ کے طریق سے بحوالہ عبید بن آدم، ابو مریم اور ابو شعیب نقل کیا ہے کہ سیدنا عمر بن خطاب رضی اللہ عنہ جابیہ میں تھے، پھر بیت المقدس کی فتح کا ذکر کیا۔ ابوسفیان بحوالہ عبید فرماتے ہیں: میں نے سیدنا عمر کو حضرت کعب سے فرماتے ہوئے سنا: تمہارا کیا خیال ہے کہ میں نماز کہاں پڑھوں... الحدیث، عمر کا قول ہے: جہاں رسول اللہ صلی اللہ علیہ وسلم نے نماز پڑھی تھی، میں وہاں نماز پڑھوں گا، یعقوب بن شیبہ نے اس طریق سے اسے نقل کیا ہے جو اس سے زیادہ مکمل ہے۔ فرماتے ہیں، عمر جابیہ میں تھے، سیدنا خالد بن ولید بیت المقدس آئے، پھر قصہ ذکر کیا، انہوں نے کہا: اسے عمر نے قیساریہ کی فتح کے بعد فتح کیا ہے، یہاں تک کہ کہنے لگے: عمر نے لوگوں کو مشورے میں شریک کیا۔ اور کہا: وہ اہل کتاب ہیں، ان کے پاس علم ہے، وہ قیساریہ کی طرف گئے اور اسے فتح کر لیا، پھر بیت المقدس کی طرف آئے اور ان سے صلح کی، اور مریم علیہا السلام کے عبادت خانے کے پاس نماز پڑھی، پھر انہوں نے اپنی قمیص کی دونوں آستینوں میں سے ایک میں تھوکا، ان سے کہا گیا اس میں تھو کیے، کیونکہ یہاں اللہ کے ساتھ شرک کیا جاتا ہے، انہوں نے فرمایا: اگر اس میں اللہ کے ساتھ شرک کیا جاتا ہے تو اس میں اللہ کا بہت زیادہ ذکر بھی کیا جاتا ہے، پھر فرمایا: عمر کو اس کی ضرورت نہیں کہ وہ جہنم کی وادی کے پاس نماز پڑھے۔ نماز کے قصے میں فرماتے ہیں، میں وہاں نماز پڑھوں گا جہاں رسول اللہ صلی اللہ علیہ وسلم نے معراج کی رات نماز پڑھی، پھر وہ قبلہ کی طرف بڑھے اور نماز پڑھی۔ ابن عساکر نے ان سوانح کو ابو شعیب حضرمی کے سوانح سے ملا دیا ہے، جنہوں نے استنجاء کے بارے میں ابوایوب سے روایت کی، ان سے عثمان بن ابوشوکہ نے روایت کی، مجھے معلوم ہوا کہ وہ اس کے علاوہ ہیں، حاکم ابواحمد نے حضرمی کے بارے میں بیان کیا ہے کہ انہیں ابو اشعث کہا جاتا تھا۔","",{"fn":"(1) اسد الغابہ (۶۰۰۱) تجرید (۱۷۷/۲)"}],[8727,"§۱۰۱۱۶ ۔ ابوشمر بن قیس\nشاعر تھے۔ بن فہر بن عمرو بن وہب بن ربیعہ بن معاویہ آکرمین کندی ابن کلبی کا قول ہے۔ زمانہ جاہلیت اور زمانہ اسلام میں شریف تھے۔"],[8728,"§۱۰۱۱۷ ۔ ابوشہاب ہذلی\nابوذؤیب کے والد ہیں، خلافت عمر میں اپنے والد کے ساتھ جہاد کیا، ابن مرزوق نے ہذلیین کے اشعار میں ان کا ذکر کیا ہے۔"],[8729,"§۱۰۱۱۸ ۔ ابوشہم تیمی\nتیم الرباب سے ہیں۔ دور جاہلیت کے ہیں، اسلام کا زمانہ پایا، ابوعبیدہ معمر بن مثنی نے کلاب اوّل والی حدیث میں ان کا ذکر کیا ہے، فرماتے ہیں: ابو ہم نے اسلام سے قبل اور خلافت عثمان بن عفان تک زندہ رہے۔"],[8730,"§۱۰۱۱۹ ۔ ابوشیبان\nانہوں نے آپ صلی اللہ علیہ وسلم کا زمانہ پایا۔ ابن ابو شیبہ نے معن بن عبدالرحمن کے طریق سے ذکر کیا ہے، فرماتے ہیں: ایک شخص نے شام کی طرف جہاد کیا، اسے شیبان کہا جاتا تھا، اس کا والد بہت بوڑھا تھا، اس نے اس کے بارے میں یہ اشعار کہے: ش ”شیبان تجھے کیا معلوم کتنی راتیں ایسی گزری ہیں جن میں میں نے تجھے شام کا دودھ پلایا جبکہ شام کا دودھ ہمیں بھی لذیذ تھا۔ تو نے مجھ سے لاپروائی کی یہاں تک کہ مجھے چھوڑ دیا اور میری یہ حالت ہوگئی کہ قریب کا آدمی مجھے دو دکھائی دیتے ہیں، شیبان جب تم لشکروں کے پاس آؤ گے تو انہیں دیکھو گے کہ وہ ایسے دن گزار رہے ہیں جو مصیبت زدہ ہیں۔“ فرماتے ہیں: جب سیدنا عمر رضی اللہ عنہ کو یہ اشعار پہنچے تو انہوں نے انہیں لوٹا دیا۔"],[8731,"§۱۰۱۲۰ ۔ ابوشییم مزنی\nواقدی(1) نے ان کا ذکر بحوالہ ان کے شیخ کیا ہے۔ کہتے ہیں: ابو شیم مزنی اسلام لائے، ان کا اسلام سنورنے کے بارے میں احادیث مروی ہیں۔ فرماتے ہیں: جب ہم غزوہ احزاب میں عیینہ بن حصن کے ساتھ نکلے، وہ ہمیں واپس لایا، جب خیبر کے نزدیک آیا تو اس نے خواب دیکھا، وہ آیا، اس نے دیکھا کہ نبی کریم صلی اللہ علیہ وسلم خیبر فتح کر چکے ہیں، اس نے کہا: اے محمد! میرے حلیفوں سے آپ نے جو میم میں لی ہیں، مجھے بھی اس میں سے دیجئے، میں آپ سے اور آپ سے قتال کرنے سے ہٹ جاؤں گا۔ آپ صلی اللہ علیہ وسلم نے اسے کچھ نہ دیا، تو وہ واپس لوٹ گیا۔ اس سے حارث بن عوف ملا۔ اس نے اس سے کہا: کیا میں نے تمہیں نہیں کہا تھا، اللہ کی قسم! الحمد مشرق اور مغرب پر غالب آئیں گے۔","",{"fn":"(1) مغازی (۶۵۰)"}],[8732,"§۱۰۱۲۱ ۔ ابوشبل (بے نسبت)\nدولابی نے صحابہ رضی اللہ عنہم میں ان کا ذکر کیا ہے، وہ وہم ہے۔ واصل بن مرزوق کے ہاں حدیث بحوالہ بنومخزوم کے ایک شخص مروی ہے جس کی کنیت ابو شیل ہے، بحوالہ ان کے دادا مروی ہے۔ وہ صحابہ رضی اللہ عنہم میں سے ہیں، مہمات میں اس کا بیان آئے گا۔"],[8733,"§۱۰۱۲۲ ۔ ابوشجرہ(1)\nابوزاہریہ کے شیخ ہیں، دولابی اور مستغفری نے صحابہ رضی اللہ عنہم میں ان کا ذکر کیا ہے، ابو موسیٰ نے اپنے استدراک میں ان کا ذکر کیا ہے۔ اس سے متنبہ کیا ہے کہ انہیں وہم ہوا ہے۔ بعض نے جائز کہا ہے کہ وہ یزید بن شجرہ ہیں، ان کی کنیت ابوشجرہ ہے، ان کے صحابی ہونے میں اختلاف ہے، لیکن ابواحمد حاکم نے ابو شجرہ یزید بن شجرہ اور ابو شجرہ شیخ ابوزاہریہ میں اختلاف کیا ہے، میری رائے صحیح ہے۔ کثیر بن مرہ میں گزر چکا ہے کہ بغوی رحمہ اللہ نے ان کے سوانح میں ابوزاہریہ کے طریق سے بحوالہ ابو شجرہ ایک حدیث نقل کی ہے، وہ یہ ہے کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا: ”صفوں کو سیدھا رکھو۔“ (الحدیث) اس میں ہے: ”جس نے صف کو جوڑا اللہ اسے جوڑے گا۔“(2) لگتا ہے کہ وہ کثیر بن مرہ کے علاوہ کوئی اور ہیں۔ واللہ اعلم","",{"fn":"(1) ۱۰۰۸۵ میں ان کے سوانح گزر چکے ہیں۔\n(2) مسند احمد (۹۷/۲) اسد الغابہ (۵/۵)"}],[8734,"§۱۰۱۲۳ ۔ ابوشریح (بے نسبت)(1)\nمسند بقی بن مخلد میں ان کی حدیث ہے، تجرید(2) میں فرمایا: ہوسکتا ہے وہ ھانی بن یزید ہوں۔ میں کہتا ہوں: بلکہ وہ ابوشریح خزاعی ہیں، یہ حدیث ان کی روایت ہے۔","",{"fn":"(1) اسد الغابہ (۵۹۹۸) تجرید (۱۷۷/۲)\n(2) التجرید (۱۶۴)"}],[8735,"§۱۰۱۲۴ ۔ ابوشریح مصری\nان کی حدیث مرسل روایت کی ہے۔ ان میں سے بعض صحابہ رضی اللہ عنہم نے ان کا ذکر کیا ہے۔ ساعدی نے لیث کے طریق سے بحوالہ ابو شریح مصری، انہوں نے نبی کریم صلی اللہ علیہ وسلم سے روایت کی، فرماتے ہیں: ”مؤمن کے ہتھیار سے جب اللہ کے رستے میں دفاع کیا جاتا ہے تو ہر روز اس کے صالح اعمال کے ساتھ اس کا وزن کیا جاتا ہے“۔"],[8736,"§۱۰۱۲۵ ۔ ابوشمیر\nبغوی نے ان کا ذکر کیا ہے، فرمایا: انہیں وہم ہوا ہے، فرماتے ہیں: ہم سے محمد بن علی نے بحوالہ شمیر روایت کیا، فرماتے ہیں: میں نے نبی کریم صلی اللہ علیہ وسلم سے کہا: میرے والد بہت بوڑھے ہیں، اور میرے بھائی ہیں، میں ان کے پاس جانا چاہتا ہوں۔ شاید وہ اسلام قبول کر لیں۔ تو میں انہیں آپ کے پاس لے آؤں آپ صلی اللہ علیہ وسلم نے فرمایا: ”اگر وہ اسلام لے آئیں تو ان کے لیے بہتر ہے، اگر انکار کریں تو اسلام وسیع ہے یا فرمایا کشادہ ہے۔ بغوی کا قول ہے: میرے خیال میں محمد بن علی کو اس بارے میں وہم ہوا، ہم سے ابوخیثمہ نے بحوالہ والد محمد بن عتاب بن شیر بن یعلیٰ بن عتاب بن شمر نقل کیا: یعنی عتاب بن شمیر کو شرف صحابیت حاصل ہے۔"],[8737,"§۱۰۱۲۶ ۔ ابوشہلہ\nحرف شین میں ان کا ذکر گزر چکا ہے۔"],[8738,"§۱۰۱۲۷ ۔ ابوصالح\nحمزہ بن عمرو اسلمی ہیں، ان کا ذکر گزر چکا ہے۔"],[8739,"§۱۰۱۲۸ ۔ ابوصبرہ\nتجرید میں مذکور ہے کہ مسند بقی بن مخلد میں ان کی ایک حدیث ہے۔"],[8740,"§۱۰۱۲۹ ۔ ابوصخر عقیلی(1)\nبخاری، مسلم، ابن حبان وغیرہ نے صحابہ رضی اللہ عنہم میں ان کا ذکر کیا ہے۔ بعض کا قول ہے: ان کا نام عبداللہ بن قدامہ ہے، اسے ابن عبدالبر نے بیان کیا ہے، اور ابن خزیمہ نے اپنی صحیح میں اور حسن بن سفیان نے اپنی مسند میں سالم بن نوح کے طریق سے بحوالہ ابو صخر جو بنو عقیل کے ایک شخص ہیں اور بعض روایتوں میں فرمایا: عبداللہ بن قدامہ، فرماتے ہیں: میں رسول اللہ صلی اللہ علیہ وسلم کے زمانے میں مدینہ آیا، تا کہ تجارت کا مال فروخت کروں۔ میں نے کہا: میں رسول اللہ صلی اللہ علیہ وسلم کے پاس جاؤں، میں آپ صلی اللہ علیہ وسلم کی طرف متوجہ ہوا اور آپ سے مدینہ کے راستے میں ابوبکر اور عمر کے درمیان میری ملاقات ہوئی، میں ان کے پیچھے چل پڑا، ایک یہودی کے پاس گئے جو تورات کو کھولے ہوئے اسے پڑھ رہا تھا، اس کا بیٹا موت کی سختی میں تھا، آپ اس کی عیادت کرنے گئے۔ فرماتے ہیں: رسول اللہ صلی اللہ علیہ وسلم اس کی طرف جھکے اور میں بھی آپ کے ساتھ جھکا، آپ صلی اللہ علیہ وسلم نے فرمایا: \"اے یہودی! میں تمہیں اس ذات کی قسم دیتا ہوں جس نے موسیٰ علیہ السلام پر تورات اتاری اور تمہیں اس ذات کی قسم دیتا ہوں جس نے بنی اسرائیل کے لیے دریا کو پھاڑا، یہودی پر یہ بات بڑی گراں گزری، کیا تم میری صفت اور میرا ظاہر ہونا اپنی کتاب میں پاتے ہو؟\" اس نے اپنے سر سے اشارہ کیا: نہیں۔ فرماتے ہیں، اس کے بیٹے نے کہا: وہ موت کی حالت میں تھا، اس ذات کی قسم جس نے موسیٰ علیہ السلام پر تورات کو اتارا، انہیں آپ کی صفت، مبعوث ہونا اور آپ کا ظاہر ہونا اپنی کتاب میں ملا ہے، میں گواہی دیتا ہوں کہ اللہ کے سوا کوئی معبود نہیں اور یہ کہ آپ اللہ کے رسول ہیں، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"اپنے بھائی کے پاس سے اس یہودی کو اٹھا دو، پھر رسول اللہ صلی اللہ علیہ وسلم نے اپنے ہاتھ سے اسے غسل دے کر کفن دیا اور اس کی نماز جنازہ پڑھی\"۔(2) ابن سعد کا قول ہے: ہم سے علی بن محمد مدائنی نے بحوالہ عبداللہ بن شقیق اسی طرح روایت کیا ہے اور اسے عبدالوہاب بن عطاء نے بحوالہ جریری روایت کیا ہے، فرماتے ہیں: بحوالہ عبداللہ بن قدامہ انہوں نے ایک اعرابی سے روایت کیا ہے، اسماعیل بن علیہ نے فرمایا: بحوالہ ابو صخر، انہوں نے اعراب کے ایک شخص سے نقل کیا، اسے احمد نے بحوالہ ابن علیہ نقل کیا ہے۔","",{"fn":"(1) اسد الغابہ (۶۰۱۱) تجرید (۱۷۸/۲)\n(2) مسند احمد (۴۱۱/۵) دلائل النبوۃ (۲۸۴/۶) جامع المسانید والسنن (۱۸۴/۱۴) اسد الغابہ (۱۲/۵)"}],[8741,"§۱۰۱۳۰ ۔ ابوصرمہ بن ابوقیس(1)\nانصاری مازنی، بعض کا قول ہے: ان کا نام قیس بن مالک ہے۔ ایک قول ہے: ابن ابو قیس، بقول بعض: ابن سعد، ابن برقی نے فرمایا: وہ قیس بن صِرمہ بن ابو صرمہ بن مالک بن عدی بن نجار ہیں، ابن قانع اور دمیاطی نے اسی طرح ان کا نسب بیان کیا ہے۔ عزل کے بارے میں نبی صلی اللہ علیہ وسلم سے روایت کی، انہوں نے بحوالہ ابو ایوب وغیرہ روایت کیا ہے۔ ان سے عبداللہ بن مخیریز اور لولوہ جو انصار کی مولاۃ ہیں اور محمد بن قیس اور زیاد بن نعیم نے روایت کی۔ عسکری نے ان سے روایت کرنے والوں میں محمد بن یحیی بن حبان کا ذکر کیا ہے، محفوظ یہ ہے کہ ان دونوں کے درمیان واسطہ ہے۔ بغوی نے ان کی حدیث بطریق یحیی بن سعید ان سے روایت کی ہے۔ لولوہ کا واسطہ اس میں ثابت ہے، دوسرے طریق سے ان سے حذف کے ساتھ روایت ہے۔ ابو عمر کا قول ہے: ان کے بدر میں شریک ہونے میں اختلاف ہے، ان کا تعاقب کیا گیا ہے کہ ابن اسحاق، موسیٰ بن عقبہ اور واقدی نے ان کا اِن میں ذکر نہیں کیا، نسائی، ترمذی کے ہاں ان کی حدیث ہے۔ محمد بن ربیع جیزی نے ان صحابہ رضی اللہ عنہم میں ان کا ذکر کیا ہے جو مصر آئے۔ فرماتے ہیں: یحیی بن عثمان نے ذکر کیا ہے کہ وہ مصر کی فتح میں شریک تھے، احمد بن یحیی بن وزیر نے ذکر کیا ہے کہ وہ عقبہ بن عامر کے پاس آئے۔ زیاد بن ابو ایوب کے طریق سے منقول ہے، فرماتے ہیں: ہم ابو ایوب کے ساتھ سمندر میں تھے، ہمارے پاس ابو صرمہ انصاری تھے جو رسول اللہ صلی اللہ علیہ وسلم کے ساتھی ہیں۔ بعض کا قول ہے: ابو صرمہ ہیں جن کے بارے میں یہ آیت نازل ہوئی: \"کھاؤ اور پیو یہاں تک کہ فجر کی سفید دھاری سیاہ دھاری سے جدا ہو جائے۔\" (الآیۃ)(2)","",{"fn":"(1) اسد الغابہ (۶۰۱۲) تجرید (۱۷۹/۲)\n(2) سورۃ البقرۃ (۱۸۷)"}],[8742,"§۱۰۱۳۱ ۔ ابوصغیر عُذری\nاس کے بارے میں ثعلبہ بن حصیر میں اختلاف گزر چکا ہے۔ بغوی رحمہ اللہ کا قول ہے: مدینہ میں رہے۔"],[8743,"§۱۰۱۳۲ ۔ ابوصفرہ\nعسعس بن سلامہ، اسماء میں ان کا ذکر گزر چکا ہے۔"],[8744,"§۱۰۱۳۳ ۔ ابوصفرہ ازدی(1)\nمہلب کے والد جو مشہور امیر ہے۔ ان کے صحابی ہونے میں اور ان کے نام میں اختلاف ہے، بعض کا قول ہے: ان کا نام ظالم بن سارق ہے، بعض نے کہا: ابوسترزاق، ایک قول ہے: قاطع بن سارق بن ظالم، بعض نے کہا: غالب بن سراق۔ ابن کلبی نے ان کا نسب بیان کیا ہے، فرماتے ہیں: ظالم بن سارق بن مصبح بن کندی بن عمرو بن عدی بن وائل بن .... ازد، بعض نے کہا کہ ان کی اصل حجم ہے۔ اور ازد کی طرف منسوب ہے۔ ابن سکن نے صحابہ رضی اللہ عنہم میں ان کا ذکر کیا ہے اور محمد بن عبد بن حمید کے طریق سے نقل کیا ہے کہ ابو صفرہ رسول اللہ صلی اللہ علیہ وسلم کے پاس آئے، اس شرط پر آپ سے بیعت کرنے لگے کہ وہ زرد جوڑا پہنیں گے، جس کے پیچھے ایک جبہ ہوگا، جسے وہ گھسیٹ رہے ہوں گے، وہ دراز قد، ڈیل ڈول والے، خوبصورت اور فصیح اللسان تھے، آپ صلی اللہ علیہ وسلم نے جب ان کا حسن و جمال دیکھا تو فرمایا: \"تم کون ہو۔\" انہوں نے کہا: میں قاطع بن سارق بن ظالم بن عمر بن شہاب بن حلقام بن جلند بن سلم ہوں جو ہر کشتی کو غصب کر لیتا تھا، میں شہزادہ ہوں، جس کا باپ بھی بادشاہ تھا۔ آپ صلی اللہ علیہ وسلم نے فرمایا: \"تم ابو صفرہ ہو اپنے نام سے سارق اور ظالم ختم کر دو\"۔ انہوں نے کہا: میں گواہی دیتا ہوں کہ اللہ کے سوا کوئی پکار اور عبادت کے لائق نہیں اور آپ اللہ کے بندے اور برحق اور سچے رسول ہیں۔ اللہ کے رسول! میری اٹھارہ نرینہ اولاد ہے، اور مجھے ایک بیٹی نصیب ہوئی ہے، جس کا نام میں نے صفرہ رکھا ہے۔ آپ صلی اللہ علیہ وسلم نے فرمایا: \"تم تو واقعی ابو صفرہ ہو\"۔ واقدی کتاب الردۃ میں فرماتے ہیں: قبیلہ ازد دبا سے اسلام کا اقرار کرتے ہوئے نبی علیہ السلام کے پاس آئے، حذیفہ بن یمان ازدی کو آپ صلی اللہ علیہ وسلم نے ان سے زکوٰۃ وصول کرنے کے لیے بھیجا، اور ان کے لیے زکوٰۃ کے فرائض لکھوائے، پھر ارتداد اور سیدنا عکرمہ کی ان سے جنگ والی حدیث ذکر کی، جس میں ان کے ان پر غالب آنے اور ان کے قیدیوں کو حذیفہ کو صدیق اکبر رضی اللہ عنہ کی طرف روانہ کرنے کا ذکر ہے۔ جب اہل دبا کے قیدی آئے ان میں ابو صفرہ بھی تھے جو ابھی نابالغ لڑکے تھے، صدیق اکبر رضی اللہ عنہ نے ان لوگوں کو رملہ بنت حارث کے گھر ٹھہرایا۔ آپ کی خواہش تھی کہ ان میں سے جنگجوؤں کو قتل کر دیا جائے تو سیدنا عمر رضی اللہ عنہ نے آپ سے فرمایا: اے خلیفہ رسول اللہ صلی اللہ علیہ وسلم! یہ مومن قوم تھی جنہوں نے اپنے مال پر بخل کیا، صدیق اکبر نے فرمایا: جس شہر میں جانا چاہتے ہو جاؤ، تم لوگ آزاد ہو چنانچہ یہ لوگ نکلے اور بصرہ فروکش ہو گئے تو ابو صفرہ بصرہ آنے والوں میں سے مہلب کے والد ہیں۔ ابو عمر فرماتے ہیں: ابو صفرہ عہد نبوی میں مسلمان تھے لیکن آپ کے پاس نہ آ سکے، سیدنا عمر رضی اللہ عنہ کے پاس اپنے دس لڑکوں سمیت آئے، دس لڑکوں میں سے مہلب سب سے کم سن تھے، سیدنا عمر رضی اللہ عنہ ان لوگوں کو دیکھ کر مسکرا رہے تھے اور خوش ہو رہے تھے، یہ تمہارے بیٹوں کا سردار ہے جو اس وقت کم سن تھے۔ اخبار بصرہ میں عمر بن شبہ لکھتے ہیں: عثمان بن ابی العاص جو ان دنوں بصرہ کے گورنر تھے، انہوں نے ابو صفرہ کو ازد کے چند لوگوں کے ساتھ سیدنا عمر رضی اللہ عنہ کے پاس بھیجا، آپ نے ان لوگوں کے نام پوچھے، ابو صفرہ سے پوچھا تو انہوں نے کہا: میں ظالم بن سارق ہوں، ان کے سر اور داڑھی کے بال سفید تھے، جب آئے تو خضاب لگا کر آئے تو سیدنا عمر رضی اللہ عنہ نے ان سے فرمایا: تم ابو صفرہ ہو، یوں یہ کنیت ان کے نام پر غالب آ گئی۔ میں کہتا ہوں: یہ واقدی کی روایت کے خلاف ہے کہ جب وہ آئے تو اس وقت نابالغ لڑکے تھے۔ اصمعی دیوان زیاد اعجم میں فرماتے ہیں ابو صفرہ نے عثمان بن ابی عاص سے زمین کا ٹکڑا مانگا تو انہوں نے مہالب میں انہیں جائیداد دے دی، کسی نے ان سے کہہ دیا کہ انہوں نے ابھی تک ختنہ نہیں کرایا تو انہوں نے انہیں بلا بھیجا، کہا: تمہارا ناس ہو تم نے ابھی تک پاکی حاصل نہیں کی، وہ کہنے لگے، امیر المؤمنین! اللہ کی قسم! میں تو دن میں پانچ بار پاکی حاصل کرتا ہوں۔ انہوں نے فرمایا: میں تم سے ختنے کے بارے میں پوچھ رہا ہوں، انہوں نے کہا: اللہ کی قسم! اللہ امیر المؤمنین کو عزت بخشے، اس کا پتہ نہیں۔ چنانچہ پھر انہوں نے ان کے ختنے کرانے کا حکم دیا۔ جس پر زیاد بن اعجم نے یہ شعر کہا: \"کچھ لوگوں نے بوڑھی عمر میں جا کے ختنہ کرایا، حالانکہ وہ عجمی تھے۔ اس کے بعد عرب بن گئے۔\" ابو فرج نے اغانی میں ابو عینیہ مسلمی کے سوانح میں لکھا ہے۔ ابو صفرہ کا نام سارق ہے۔ بقول بعض غالب، ابن قتیبہ کا قول ہے مہلب، عمان کے دبا نامی گاؤں کے تھے۔ نبی صلی اللہ علیہ وسلم کے عہد میں مسلمان ہوئے، پھر (نعوذ باللہ) مرتد ہو گئے۔ سیدنا حذیفہ کے حکم کے مطابق اترے آپ نے انہیں ابو بکر کی طرف بھیج دیا، جنہوں نے انہیں آزاد کر دیا۔ ہمیں ابو صفرہ کی سند حدیث ملی ہے جسے طبرانی نے اوسط میں زیاد بن عبداللہ قرشی کے طریق سے نقل کیا ہے کہ میں ہند بنت مہلب بن ابی صفرہ کے ہاں آیا جو حجاج کی بیوی تھی، اس کے ہاتھ میں سلائی تھی جس سے سوت کات رہی تھی، میں نے کہا: گورنر کی بیوی ہو کر آپ سوت کات رہی ہیں، وہ کہنے لگیں: میرے والد میرے دادا کے حوالے سے بیان کرتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: \"تم عورتوں میں سے زیادہ اجر والی وہ عورت ہے، جس کا طاق (بغیر گریبان کے کپڑا) زیادہ لمبا ہوگا\"۔(2) طبرانی کا قول ہے: ابو صفرہ نے اس کے علاوہ کوئی مسند حدیث بیان نہیں کی، ان سے صرف اسی سند سے مروی ہے۔ جس میں یزید بن مروان بن زیادہ منفرد ہیں۔ میں کہتا ہوں: یزید متروک ہے، اور وہ حدیث جسے ابن سکن نے نقل کیا ہے اس پر اعتراض کیا جا سکتا ہے۔","",{"fn":"(1) اسد الغابہ (۶۰۱۴) الاستیعاب (۳۰۸۷)\n(2) مجمع الزوائد (۱۳/۴، ۹۳/۴)"}],[8745,"§۱۰۱۳۴ ۔ ابوصفوان عبداللہ بن بشر مازنی"],[8746,"§۱۰۱۳۵ ۔ ابوصفوان مالک بن عمیرہ"],[8747,"§۱۰۱۳۶ ۔ ابوصفوان مخرمہ بن نوفل\nمسور کے والد ہیں، اسماء میں ان کا ذکر گزر چکا ہے۔"],[8748,"§۱۰۱۳۷ ۔ ابوصفوان یا ابن صفوان(1)\nمبہمات میں ذکر ہے۔","",{"fn":"(1) اسد الغابہ (۶۰۱۶)، تجرید (۱۷۹/۲)"}],[8749,"§۱۰۱۳۸ ۔ ابوصفیہ\nرسول اللہ صلی اللہ علیہ وسلم کے مولی ہیں، بخاری کا قول ہے: مہاجرین میں ان کا شمار ہے۔ اسے معلی بن عبد الرحمن کے طریق سے نقل کیا ہے، میں نے یونس بن عبید سے سنا وہ اپنی والدہ سے کہہ رہے تھے آپ نے ابو صفیہ کو کیا کرتے دیکھا؟ وہ کہنے لگیں: میں نے ابو صفیہ کو دیکھا، وہ اصحاب نبی تھے اور مہاجرین مسلمانوں سے تھے، گٹھلیوں پر تسبیح کا شمار کرتے، عبدالواحد بن زید نے بحوالہ یونس بن عبید ان کی پیروی کی ہے۔ فرماتی ہیں: میں نے ابو صفیہ کو دیکھا جو مہاجرین میں سے ہیں وہ گٹھلیوں پر تسبیح پڑھ رہے تھے، اسے بغوی نے نقل کیا ہے۔ اور دوسرے طریق سے بحوالہ ابی بن کعب نقل کیا ہے، بحوالہ ابو صفیہ مولی رسول اللہ صلی اللہ علیہ وسلم کہ ان کے لیے چٹائی بچھائی جاتی اس پر کنکریاں لائی جاتیں، وہ نصف نہار تک ذکر کرتے جب نماز پڑھ لیتے اور واپس آتے تو وہ دوبارہ لائی جاتیں وہ ذکر کرتے یہاں تک کہ شام ہو جاتی۔"],[8750,"§۱۰۱۳۹ ۔ ابوصمصمہ\nبعض نے کہا: مستغفری نے یہاں مہملہ ذکر کیا ہے، ضاد میں عنقریب آئے گا۔"],[8751,"§۱۰۱۴۰ ۔ ابوصہیب\nحاکم ابو احمد نے ان کا ذکر کیا ہے، فرماتے ہیں، انہوں نے نبی صلی اللہ علیہ وسلم سے روایت کی، ان سے حلال نے میرا خیال ہے، ابن لیاف نے روایت کی۔ عبد الرزاق کا قول ہے، بحوالہ معمر، انہوں نے ہلال سے روایت کی۔"],[8752,"§۱۰۱۴۱ ۔ ابوصُحار سعدی\nنبی کریم صلی اللہ علیہ وسلم کے زمانے میں ایک شخص تھے، حنین میں مشرکوں کے ساتھ شریک تھے، پھر اسلام لائے۔ ابو عبد اللہ بن اعرابی نے کتاب النوادر میں ان کا ذکر کیا ہے۔ فرماتے ہیں: سروجی کا قول ہے، ابو صحار سعدی ہے، سعد بن ابو بکر بن ہوازن، ان سے ان کی زوجہ نے کہا: ہمارے لیے روئی خرید کر لاؤ، تو انہوں نے کہا: انتظار کرو یہاں تک کہ پہاڑ روئی کے گالے بن جائیں جیسا کہ ایک قریش نے کہا ہے۔ پھر تم سستے داموں روئی لے لینا، ان کی قوم نے ان کو اسلام کی دعوت دی تو انہوں نے انکار کر دیا، حنین کے موقع پر انہوں نے یہ شعر کہا: \"سنو! اگر تمہارے پاس یہ خبر پہنچے کہ قریش ہوازن پر غالب آگئے تو جنگوں کی کچھ شرطیں ہوتی ہیں\"۔ یہ اشعار اور ان کا جواب عبد اللہ بن وہب اسدی کے سوانح میں گزر چکا ہے، فرماتے ہیں: پھر ابو صحار اس کے بعد اسلام لائے اور ان کا اسلام سنور گیا، عبید اللہ بن عباس بقیع کے پاس رہتے تھے جس کی ان کے بارے میں ایک حدیث ہے، اور اس کے متعلق ان کے مدحیہ اشعار نقل کیے۔ ابو عبد اللہ بن خالویہ نے اپنی کتاب میں ان کا واقعہ ذکر کیا ہے۔"],[8753,"§۱۰۱۴۲ ۔ ابوصالح\nام ہانی کے مولیٰ ہیں، مشہور تابعی ہیں۔ بعض راویوں نے ان کے طریق سے حدیث میں وہم کیا ہے، اسے حسن بن سفیان نے اپنی مسند میں نقل کیا ہے، اور ابو نعیم نے اپنے طریق سے ان کا صحابہ رضی اللہ عنہم میں ذکر کیا ہے، وہ وہم ہیں۔ حسن نے رزین کے طریق سے بحوالہ ابو صالح نقل کیا ہے۔ ام ہانی نے انہیں آزاد کیا تھا۔ فرماتے ہیں: میں ہر ماہ ان کے پاس آتا، اور ہر دو ماہ میں آنا ہوتا، ایک دن میں ان کے پاس گیا تو نبی کریم صلی اللہ علیہ وسلم اچانک وہاں تشریف لائے تو ام ہانی کہنے لگیں: اے چا زاد، میں بوڑھی ہو گئی ہوں، جسم بھاری ہو گیا ہے، جس سے میرے عمل میں ضعف آ گیا ہے، اس سے چھٹکارے کا کیا طریق ہے؟ آپ نے فرمایا: \"یوں خوشخبری ہو، خیر کثیر کی، سو مرتبہ الحمد للہ کہہ لیا کرو، یہ سو غلام آزاد کرنے کے برابر ہے۔ سو مرتبہ اللہ اکبر کہہ لیا کرو، جس کا ثواب اللہ کی راہ میں ایسے سو گھوڑے دینے کے برابر ہے جو زین کسے اور لگام والے ہوں، سو مرتبہ سبحان اللہ کہہ لیا کرو جو سو قلادہ والے اونٹوں کے برابر ہے جنہیں حج کی قربانی کے لیے بھیجا جائے اور سو مرتبہ لا إله إلا اللہ کہہ لیا کرو، کوئی گناہ تمہیں شرک کی طرف نہیں لے جائے گا۔\" رزین نے اسی طرح کہا ہے، یہ ضعیف ہے، درست اس طرح ہے کہ اچانک سیدنا علی رضی اللہ عنہ تشریف لائے تو ام ہانی رضی اللہ عنہا کہنے لگیں: بھیا! جس شخص کو تھوڑی بہت معرفت ہو گی، اس سے یہ خفی نہیں کہ ابو صالح، ام ہانی کے غلام، مشہور تابعی ہیں۔"],[8754,"§۱۰۱۴۳ ۔ ابوصباح بن نعمان\nکسی نے ان کا نام غلط لکھ دیا ہے، درست ضاد کے ساتھ ہے جیسا کہ عنقریب آئے گا۔"],[8755,"§۱۰۱۴۴ ۔ ابوھبیب بلوی\nبعض کا قول ہے: ابوضبیب، ان کا ذکر آئے گا۔"],[8756,"§۱۰۱۴۵ ۔ ابوضبیس جھنی(1)(2)\nابن مندہ کا قول ہے: میں نے ابن یونس سے بحوالہ واقدی ذکر کرتے ہوئے سنا(3) کہ وہ صحابی ہیں، اسکندریہ میں فروکش ہونے والوں میں ذکر کیا اور بحوالہ واقدی مروی ہے کہ وہ اصحاب شجرہ میں سے ہیں۔ سیدنا معاویہ رضی اللہ عنہ کی خلافت کے آخر میں وفات پائی، واقدی رحمہ اللہ نے عربین کے تعاقب میں نکلنے والوں میں ان کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابہ (۶۰۱۸) تجرید (۱۷۹/۲)\n(2) المغازی (۵۷۱)\n(3) تجرید (۱۷۹/۲)"}],[8757,"§۱۰۱۴۶ ۔ ابوضبیس بلوی(1)\nمحمد بن ربیع جیزی نے مصر میں آنے والے صحابہ رضی اللہ عنہم میں ان کا نام لیا ہے۔ واقدی نے محمد بن سعد مولی بنو مخزوم کے طریق سے نقل کیا ہے، فرماتے ہیں: وہ ربیع الاول میں میری قوم کا وفد آیا، مجھے ان کے آنے کا پتہ چلا، میں نے انہیں اپنے ہاں اتارا، وہ رسول اللہ صلی اللہ علیہ وسلم کے پاس گئے، ان میں سے ایک بوڑھے شخص ابو ضبیس نے کہا: یا رسول اللہ! میں ضیافت میں رغبت رکھتا ہوں، کیا میرے لیے اس میں اجر ہے؟ آپ نے فرمایا: \"ہاں! اور ہر امیر، غریب کے ساتھ نیکی صدقہ ہے\"۔","",{"fn":"(1) اسد الغابہ (۶۰۱۹) تجرید (۱۷۹/۲) اسد الغابہ (۱۵/۵)"}],[8758,"§۱۰۱۴۷ ۔ ابوضحاک عمرو بن حزم بن زید انصاری"],[8759,"§۱۰۱۴۸ ۔ ابوالضحاک فیروز دیلمی\nان دونوں کا ذکر گزر چکا ہے۔"],[8760,"§۱۰۱۴۹ ۔ ابوضحاک انصاری\nحسن بن سفیان نے اپنی مسند میں ان کا ذکر کیا ہے اور ابراہیم بن قیس انصاری کے طریق سے نقل کیا ہے کہ جب رسول اللہ صلی اللہ علیہ وسلم خیبر کی طرف چلے تو سیدنا علی رضی اللہ عنہ کو اپنے مقدمہ میں کیا، اور ان سے کہا: \"بے شک جبرائیل تم سے محبت رکھتے ہیں۔\" انہوں نے کہا: مجھے معلوم ہو چکا ہے کہ جبرئیل مجھ سے محبت رکھتے ہیں، آپ صلی اللہ علیہ وسلم نے فرمایا: \"ہاں! اور وہ بھی جو جبرائیل سے بہتر ہے، اللہ تم سے محبت رکھتا ہے\"۔(1)","",{"fn":"(1) اسد الغابہ (۶۰۲۰) تجرید (۱۸۰/۲)"}],[8761,"§۱۰۱۵۰ ۔ ابوضمرہ بن عیص(1)\nاسماء میں جندع بن ضمرہ کے حالات میں ان کے نام کے بارے میں اختلاف کا ذکر کیا اور کلام ....(2)","",{"fn":"(1) بیاض فی الاصل، تین کلمے۔\n(2) ..."}],[8762,"§۱۰۱۵۱ ۔ ابوضمرہ حمیری\nضمرہ کے والد ہیں، ابن مندہ نے کنیتوں میں ان کا ذکر کیا ہے۔ ان پر بغوی سبقت لے گئے ہیں اور ان سے پہلے محمد بن سعد، انہوں نے ان کا وصف بیان کیا ہے کہ وہ مولی رسول اللہ ہیں، بعض کا قول ہے: ان کا نام سعد ہے، بقول بعض: روح ہے۔ ضمیرہ کے سوانح میں اس کتاب میں جسے نبی کریم صلی اللہ علیہ وسلم نے آل ضمیرہ کے لیے لکھا ان کی روایت گزر چکی ہے۔ مصعب زبیری کا قول ہے: ابو ضمیرہ کا دار عقیق میں گھر تھا اور وہ اس ابو ضمیرہ کے علاوہ ہیں جو سیدنا علی رضی اللہ عنہ کے مولی ہیں، ابن سعد اور بلاذری نے فرمایا: حسین بن عبد اللہ بن ضمیرہ مہدی کے پاس خط لے کر گیا، اس نے اسے اپنی آنکھوں پر رکھ لیا اور اسے تین سو دینار دیے، وہ سفر میں تھا اور اس کے ساتھ اس کی قوم اور یہ خط تھا، انہیں چوروں نے آ لیا، انہوں نے سب کچھ لے لیا، خط نکالا اور اسے پڑھا پھر انہیں جو کچھ لیا تھا لوٹا دیا، اور ان سے پوچھ گچھ نہ کی، پھر بغوی نے بحوالہ اسماعیل بن ابو ادریس اس کا ذکر کیا ہے۔"],[8763,"§۱۰۱۵۲ ۔ ابوضمیمہ(1)\nابن مندہ نے ان کا ذکر کیا ہے اور عطاء خراسانی کے طریق سے بحوالہ حسن بصری نقل کیا ہے: میں نے ابو ضمیمہ سے سنا، انہوں نے نبی کریم صلی اللہ علیہ وسلم کا زمانہ پایا، فرماتے ہیں: میں نے نبی کریم صلی اللہ علیہ وسلم سے انصاف کے دروازوں کے بارے میں پوچھا، آپ صلی اللہ علیہ وسلم نے فرمایا: \"اپنے نفس سے لوگوں کو انصاف دینا، لوگوں میں سلام پھیلانا\"۔(2) میں کہتا ہوں: عطاء کا قول ہے: اس میں ضعف ہے، اور اس حدیث کے ان سے راوی پر کذب کی تہمت ہے، وہ اسحاق بن نجیح ہیں، اسے ابو نعیم نے دوسرے طریق سے روایت کیا ہے، فرمایا: بحوالہ ابو تمیمہ۔ واللہ اعلم!","",{"fn":"(1) اسد الغابہ (۶۰۲۳) تجرید (۱۸۰/۲)\n(2) جامع المسانید والسنن (۱۹۵/۱۴) اسد الغابہ (۱۶/۵)"}],[8764,"§۱۰۱۵۳ ۔ ابوضمضم(1)\nان کا نام اور نسبت معلوم نہیں، ابو عمر نے کتاب ابن سکن کے حاشیہ میں ان کا ذکر کیا ہے۔ میں نے اسے ان کی تحریر سے پڑھا ہے۔ ابو ضمضم غیر منسوب ہیں۔ ثابت نے بحوالہ انس نقل کیا ہے کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا: \"کیا تم پسند نہیں کرتے کہ تم ابو ضمضم کی طرح ہو جاؤ؟\" لوگوں نے کہا: یا رسول اللہ! کون ابو ضمضم؟ آپ صلی اللہ علیہ وسلم نے فرمایا: ابو ضمضم جب صبح ہوتی ہے تو کہتا ہے: اے اللہ! میں نے اپنی عزت کو اس پر صدقہ کیا جس نے مجھ پر ظلم کیا\"۔(2) فرماتے ہیں: نبی کریم صلی اللہ علیہ وسلم نے فرمایا کہ ان کی مغفرت کر دی گئی، اور صحابہ رضی اللہ عنہم میں ان کا شمار کیا ہے۔ فرماتے ہیں: ان سے حسن اور قتادہ نے روایت کی۔ اسی طرح ابو ہریرہ رضی اللہ عنہ سے مروی ہے کہ مسلمانوں میں سے ایک شخص فرماتے ہیں .... پھر اسی طرح ذکر کیا۔ ابو عمر کا قول ہے: میرا خیال ہے یہ ابو ضمضم مذکور ہے۔(3) میں کہتا ہوں: حاکم ابو احمد نے اس کی پیروی کی ہے، انہوں نے حماد بن زید کے طریق سے بحوالہ قتادہ نقل کیا ہے، دونوں کہتے ہیں: ابو ضمرہ نے کہا: اے اللہ! .... پھر اسے ذکر کیا پھر حدیث ابو ہریرہ، سعید بن عبد الرحمن کے طریق سے بحوالہ سفیان نقل کی ہے، وہ بھی جامع سفیان میں ہے۔ اسے ابن سنی نے عمل الیوم واللیلۃ میں نقل کیا ہے، بطریق شعیب بن بیان، بحوالہ انس، مرفوعاً۔ ابن فتحون نے ابن عبد البر کے قول کا تعاقب کیا ہے کہ ان سے حسن اور قتادہ نے روایت کی، فرماتے ہیں: یہ وہم ہے، اس میں ڈھکی چھپی بات نہیں، کیونکہ نبی کریم صلی اللہ علیہ وسلم اپنے اصحاب کو ابو ضمضم کے بارے میں خبر دے رہے تھے، وہ اسے نہیں جانتے تھے اور کہنے لگے، ابو ضمضم کون ہے؟ اور ابو عمر کا قول ہے: ان سے حسن اور قتادہ نے روایت کی ہے۔ اسے بزار اور ساجی نے ابو نضر ہاشم بن قاسم کے طریق سے بحوالہ انس حدیث نقل کی ہے، اس میں ہے، وہ کہنے لگے: ابو ضمضم کون ہے؟ آپ نے فرمایا: ابو ضمضم جب صبح ہوتی ہے تو کہتا ہے: اے اللہ! .... (الحدیث) بزار کی روایت میں یہ اضافہ ہے: وہ سخت آدمی تھے۔ ابن فتحون کا قول ہے: وہ شخص اس امت میں سے نہیں تھا، وہ اس سے پہلے تھا۔ آپ صلی اللہ علیہ وسلم نے اس کے حال کی خبر ترغیب دینے کے لیے دی تاکہ وہ اس کے اعمال کی طرح عمل کریں۔ اس سے وہم نہیں ہوتا کہ حدیث ابو ہریرہ رضی اللہ عنہ میں جو صحابی ہیں وہ ابو ضمضم خطا سے ہیں بلکہ وہ علبہ بن زید انصاری ہیں جیسا کہ حرف عین میں گزر چکا ہے۔ اگر اس بات کی تصریح نہ ہوتی کہ ابو ضمضم پہلے گزر چکا ہے تو یہ جائز تھا کہ علبہ کی کنیت ابو ضمضم ہو، لیکن ابو داؤد کی روایت سے بحوالہ موسیٰ بن اسماعیل اس سے انکار ہے، ابو بکر خطیب نے کتاب الموضح میں روح بن عبادہ کے طریق سے بحوالہ عبد الرحمن بن عجلان روایت کرتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا: \"تم میں سے کوئی عاجز ہے کہ وہ ابو ضمضم کی طرح ہو؟\" وہ کہنے لگے: \"ابو ضمضم کون ہے؟ یا رسول اللہ صلی اللہ علیہ وسلم!\" آپ صلی اللہ علیہ وسلم نے فرمایا: \"تم سے پہلے ایک شخص تھا ....\" (الحدیث)(4) ابو داؤد کا قول ہے، اسے ابو نضر نے بحوالہ انس روایت کیا ہے اور حماد کی روایت زیادہ صحیح ہے، اسے محمد بن ثور کے طریق سے بحوالہ قتادہ موقوفاً نقل کیا ہے۔ بخاری نے اپنی تاریخ میں اسے مسنداً نقل کیا ہے اور بزار اور ساجی نے ابو نضر کے طریق سے اور بزار نے اس طرف اشارہ کیا ہے کہ محمد بن عبد اللہ سے روایت کرنے میں تنہا ہیں، اسے بخاری وایمیہ نے اپنی تاریخ میں اور عقیلی نے ضعفاء میں نقل کیا ہے۔","",{"fn":"(1) اسد الغابہ (۶۰۲۱) تجرید (۱۸۰/۲)\n(2) اسد الغابہ (۱۶/۵)\n(3) جامع المسانید والسنن (۱۹۳/۱۴)\n(4) عمل الیوم واللیلۃ (۲۲) اسد الغابہ (۱۶/۵)"}],[8765,"§۱۰۱۵۴ ۔ ابوطخفہ\nطحفہ میں ان کا ذکر گزر چکا ہے۔"],[8766,"§۱۰۱۵۵ ۔ ابوطریف ھذلی(1)\nبغوی، مطین، ابن حبان، ابن سکن وغیرہ نے صحابہ رضی اللہ عنہم میں ان کا ذکر کیا ہے، طائف کے محاصرے میں شریک تھے، ابن قانع کا قول ہے: ان کا نام کیسان ہے۔ ابو عمر کا قول ہے: ان کا نام سنان ہے۔ احمد، حسن بن سفیان وغیرہ نے زکریا بن اسحاق کے طریق سے روایت نقل کی ہے، بغوی کی روایت میں ابو شمیرہ ہے، مجھ سے ابو طریف نے نقل کیا کہ وہ نبی کریم صلی اللہ علیہ وسلم کے پاس تھے اور آپ صلی اللہ علیہ وسلم اور اہل طائف کا محاصرہ کیے ہوئے تھے۔ فرماتے ہیں: آپ صلی اللہ علیہ وسلم نے ہمیں مغرب کی نماز پڑھائی حتی اسکہ کوئی شخص اگر اپنی کمان سے تیر پھینکتا تو اس تیر کے گرنے کی جگہ دیکھ سکتا، ابن خزیمہ نے اسے صحیح قرار دیا ہے۔","",{"fn":"(1) اسد الغابہ (۶۰۲۷) تجرید (۱۸۰/۲)"}],[8767,"§۱۰۱۵۶ ۔ ابوطریف عدی بن حاتم طائی\nان کا ذکر گزر چکا ہے۔"],[8768,"§۱۰۱۵۷ ۔ ابوطفیل(1)\nعامر بن واثلہ بن عبد اللہ بن عمرو بن جحش، بعض نے کہا: جیش بن جدی .... کنانی، پھر لیثی، انہوں نے جوانی میں نبی کریم صلی اللہ علیہ وسلم کو دیکھا اور آپ سے احادیث یاد کیں۔ ابن عدی کا قول ہے: انہیں شرف صحابیت حاصل ہے، بحوالہ ابوبکر، عمر، علی، معاذ، حذیفہ، ابن مسعود، ابن عباس، نافع بن عبد حارث، زید بن ارقم وغیرہ احادیث روایت کیں، ان سے زہری، ابو زبیر، قتادہ، عبد العزیز بن رفیع، عکرمہ بن خالد، عمرو بن دینار، یزید بن ابو حبیب، معروف بن خربوذ وغیرہ نے روایت کی۔ مسلم کا قول ہے: ۱۰۰ھ میں وفات پائی اور صحابہ رضی اللہ عنہم میں وفات پانے والوں میں آخری تھے۔ ابن برقی کا قول ہے: ۱۰۲ھ میں وفات پائی، وہ اپنا نام اور کنیت دونوں سے مشہور ہیں اور بحوالہ مبارک بن فضالہ ۱۰۷ھ میں وفات پائی۔ وہب بن جریر بن حازم نے اپنے والد کے حوالے سے بتایا: ۱۱۰ھ میں میں مکہ میں تھا۔ میں نے ان کا جنازہ دیکھا اور اس بارے میں دریافت کیا، مجھ سے کہا گیا کہ یہ ابو طفیل ہیں۔ ابن سکن کا قول ہے: ان سے روایات ثابت ہیں کہ انہوں نے نبی کریم صلی اللہ علیہ وسلم کو دیکھا اور رہا آپ صلی اللہ علیہ وسلم سے سماعت کرنا تو وہ ثابت نہیں۔ ابن سعد نے بحوالہ ابو طفیل ذکر کیا ہے، فرماتے ہیں: میں تلاش کرنے والوں کے ساتھ آپ صلی اللہ علیہ وسلم کو ڈھونڈ رہا تھا، جبکہ آپ صلی اللہ علیہ وسلم نماز میں تھے .... (الحدیث) یہ ضعیف ہے، کیونکہ اس میں اختلاف نہیں ہے کہ ابو طفیل اس رات میں پیدا نہیں ہوئے۔ میں کہتا ہوں: میرا خیال ہے یہ ابو طفیل کی بحوالہ ان کے والد روایت ہے۔ صالح بن احمد بن حنبل نے بحوالہ اپنے والد فرمایا: ابو طفیل کی ہے، ثقہ ہیں، بخاری نے تاریخ صغیر میں بحوالہ ابو طفیل نقل کیا ہے، فرماتے ہیں: انہوں نے نبی کریم صلی اللہ علیہ وسلم کی زندگی کے آٹھ سال پائے، ابو عمر کا قول ہے: وہ ابو بکر اور عمر رضی اللہ عنہما کی فضیلت کے قائل تھے، لیکن سیدنا علی رضی اللہ عنہ کو ان دونوں پر مقدم کرتے تھے۔","",{"fn":"(1) اسد الغابہ (۶۰۲۸) الاستیعاب (۳۰۹۵) تجرید (۱۸۰/۲)"}],[8769,"§۱۰۱۵۸ ۔ ابوطلحہ انصاری(1)\nزید بن سہل .... انصاری، بخاری۔ اپنے نام اور کنیت سے مشہور ہیں۔ انہوں نے کہا: \"میں ابو طلحہ ہوں میرا نام زید ہے، ہر روز میرے تھیلے میں شکار ہوتا ہے، اسماء میں ان کا ذکر گزر چکا ہے۔\"","",{"fn":"(1) اسد الغابہ (۶۰۲۹) الاستیعاب (۳۰۹۶)"}],[8770,"§۱۰۱۵۹ ۔ ابوطلحہ انصاری\nیہ دوسرے ہیں، خطیب نے مبہمات میں ان کا ذکر کیا ہے یہ وہی ہیں جنہوں نے ایک شخص کی ضیافت کی اور اسے اپنے کھانے پر ترجیح دی، ان کے بارے میں یہ آیت نازل ہوئی: اپنی ذات پر ترجیح دیتے ہیں۔(1) ذکر کیا کہ وہ ابو طلحہ کے علاوہ ہیں، جو ام سلیم کے شوہر ہیں، اور اس کا نسب بیان کیا ہے کہ وہ اس روایت میں واقع ہیں جسے مسلم نے نقل کیا ہے، تو انصار کا ایک شخص کھڑا ہوا جسے ابو طلحہ کہا جاتا تھا، گویا انہوں نے اسے بعید سمجھا ہے کہ ابو ہریرہ، ابو طلحہ کو جو ام سلیم کے خاوند ہیں نہ جانتے ہوں، یہاں تک کہ ان سے یہ عبارت تعبیر کی، دوسرے لوگوں نے یقین کیا ہے کہ یہ مانع نہیں کہ یہ قصہ ابو ہریرہ رضی اللہ عنہ کے مدینہ تشریف لانے کے اوائل میں پیش آیا ہو، اس سے پہلے کہ غالب اپنے اہل کو پہچانے۔","",{"fn":"(1) سورۃ الحشر (۹)"}],[8771,"§۱۰۱۶۰ ۔ ابوطلحہ\nدرع خولانی، طبرانی کا قول ہے: ان کی صحبت میں اختلاف ہے، حماد بن سلمہ کے طریق سے بحوالہ ابو طلحہ خولانی مروی ہے۔ ان کا نام درع ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"چار لشکر ہوں گے تم پر شام میں جانا لازم ہے ....\" (الحدیث)(1) ابن یونس کا قول ہے: مصر کی فتح میں شریک تھے۔","",{"fn":"(1) المعجم الکبیر (۲۷۵/۴)"}],[8772,"§۱۰۱۶۱ ۔ ابوطلیق(1)\nبعض کا قول ہے، طلیق، بغوی اور ابن سکن وغیرہ نے صحابہ رضی اللہ عنہم میں ان کا ذکر کیا ہے۔ مختار بن فلفل کے طریق سے نقل کیا ہے، فرماتے ہیں: مجھ سے طلق بن حبیب بصری نے نقل کیا ہے کہ ابو طلیق نے ان سے بیان کیا کہ ان کی زوجہ ام طلیق ان کے پاس آئی اور ان سے کہا: اے ابو طلیق! حج کا موسم آ گیا ہے، ان کے پاس ایک اونٹ اور ایک اونٹنی تھی۔ وہ اونٹنی پر حج کرتے اور اونٹ پر غزوات میں شریک ہوتے۔ انہوں نے ان سے کہا کہ انہیں اونٹ دے دیں تاکہ وہ اس پر حج کریں، انہوں نے کہا: کیا تم نہیں جانتی کہ میں نے اسے اللہ کے راستے میں جہاد کے لیے روکا ہوا ہے؟ انہوں نے کہا: حج بھی اللہ کے راستے میں ہوتا ہے، مجھے اونٹ دے دے اللہ تم پر رحم کرے، انہوں نے انکار کیا۔ وہ کہنے لگیں: پھر مجھے اونٹنی دے دو اور تم اونٹ پر حج کرو، انہوں نے کہا: میں تمہیں اپنے آپ پر ترجیح نہیں دوں گا۔ انہوں نے کہا: اپنے خرچ میں سے مجھے دے دو۔ انہوں نے کہا: میرے پاس اپنے اور اپنے عیال کے خرچ سے زائد نہیں جو تمہیں دے دوں، جسے تمہارے لیے چھوڑوں۔ انہوں نے کہا: اگر تم مجھے دے دو تو اللہ تعالیٰ تمہیں اس کے بدلے میں دے گا، فرماتے ہیں: جب میں نے اس پر بھی انکار کیا تو کہنے لگیں: جب تم رسول اللہ صلی اللہ علیہ وسلم سے ملو تو میری طرف سے سلام کہنا، اور آپ صلی اللہ علیہ وسلم کو بتانا جو کچھ میں نے تم سے کہا ہے۔ فرماتے ہیں: میں رسول اللہ صلی اللہ علیہ وسلم کے پاس آیا اور اس کی طرف سے آپ کو سلام پہنچایا، اور جو کچھ اس نے کہا تھا آپ صلی اللہ علیہ وسلم کو اس کی خبر دی، آپ صلی اللہ علیہ وسلم نے فرمایا: \"ام طلیق نے سچ کہا، اگر تم اسے اونٹ دے دو تو وہ اللہ کے راستے میں ہے، اگر تم اسے اونٹنی دے دو تو وہ اور تم اللہ کے راستے میں ہو، اگر تم اسے اپنے خرچ میں سے دو تو اللہ تعالیٰ تمہیں اس کا بدلہ دے گا\"۔(2) انہوں نے کہا کہ وہ آپ سے پوچھ رہی ہیں کیا چیز حج کے برابر ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا: \"رمضان میں عمرہ کرنا\"۔ حفص بن غیاث کے الفاظ ہیں جو بحوالہ ابو بشر دولابی منقول ہیں، اسے ابن ابو شیبہ، ابن سکن اور ابن مندہ نے عبد الرحیم بن سلیمان کے طریق سے بحوالہ مختار نقل کیا ہے، اس کی سند جید ہے۔","",{"fn":"(1) اسد الغابہ (۶۰۳۰) تجرید (۱۸۰/۲)\n(2) المعجم الکبیر (۳۲۴/۲۲) الآحاد والمثانی (۱۷۶/۵) مجمع الزوائد (۲۸۰/۳) کشف الاسرار (۳۸/۲)"}],[8773,"§۱۰۱۶۲ ۔ ابوطویل کندی\nشطب محدود، اسماء میں ان کا ذکر گزر چکا ہے۔"],[8774,"§۱۰۱۶۳ ۔ ابوطیبہ حجام(1)\nمولی انصار، بنو حارثہ سے ہیں، بعض کا قول ہے: بنو بیاضہ سے ہیں۔ بعض نے کہا: ان کا نام دینار ہے، اسے ابن عبد البر نے بیان کیا ہے، اور یہ صحیح نہیں، حاکم ابو احمد نے ذکر کیا ہے کہ دینار حجام آخری تابعی ہیں، ابن مندہ نے دینار حجام کی ایک حدیث بحوالہ ابو طیبہ نقل کی ہے، بعض نے کہا: ان کا نام میسرہ ہے۔ بغوی نے معجم الصحابہ میں بحوالہ احمد بن عبید ابو طیبہ نقل کیا ہے کہ انہوں نے ان کے دادا ابو طیبہ کے نام کے بارے میں سوال کیا، انہوں نے فرمایا: میسرہ، بعض کا قول ہے: نافع، عسکری کا قول ہے: ایک قول ہے کہ ان کا نام نافع ہے جو صحیح نہیں، ان کا نام معلوم نہیں۔ میں کہتا ہوں: اسی طرح فرمایا: اسی طرح مسند محیصہ بن مسعود میں مسند احمد میں ان کا نام ہے، پھر یزید بن ابو حبیب سے بحوالہ محیصہ روایت ہے کہ ان کا ایک غلام پچھنے لگاتا تھا جس کا نام نافع ابو طیبہ تھا، نبی کریم صلی اللہ علیہ وسلم سے اپنی کمائی کے بارے میں پوچھا، آپ صلی اللہ علیہ وسلم نے فرمایا: اپنے اونٹ کو چارا کھلا دیا کرو۔ اسے احمد وغیرہ نے لیث کی حدیث سے بحوالہ محیصہ بن مسعود نقل کیا ہے کہ ان کا ایک غلام پچھنے لگاتا تھا جس کا نام نافع ابو طیبہ تھا، ان کا ذکر صحیحین میں ثابت ہے کہ انہوں نے نبی کریم صلی اللہ علیہ وسلم کو پچھنے لگائے، یہ حدیث انس اور جابر وغیرہ سے ہے۔ ابن ابو خیثمہ نے ضعیف سند سے بحوالہ جابر نقل کیا ہے، فرماتے ہیں: ہمارے پاس ابو طیبہ رمضان کے اٹھارہ دنوں کے بعد آئے۔ ہم نے ان سے کہا: آپ کہاں تھے؟ انہوں نے کہا: میں نے رسول اللہ صلی اللہ علیہ وسلم کو پچھنے لگائے تھے۔(2) ابن سکن نے دوسری ضعیف سند سے حدیث ابن عباس رضی اللہ عنہ سے نقل کیا ہے کہ ہم نبی کریم صلی اللہ علیہ وسلم کے دروازے پر بیٹھے تھے۔ ہمارے پاس ابو طیبہ اپنے کپڑے میں کوئی چیز اٹھائے ہوئے آئے۔ ہم نے کہا: ابو طیبہ! یہ تمہارے پاس کیا ہے؟ انہوں نے کہا: میں نے نبی کریم صلی اللہ علیہ وسلم کے پچھنے لگائے تھے، آپ صلی اللہ علیہ وسلم نے مجھے میری اجرت عطا فرمائی۔","",{"fn":"(1) اسد الغابہ (۶۰۳۲) تجرید (۱۸۱/۲)\n(2) مسند احمد (۴۲۵/۵) المعجم الکبیر (۹۵۴/۲۲)"}],[8775,"§۱۰۱۶۴ ۔ ابوطفیل سہیل بن عوف"],[8776,"§۱۰۱۶۵ ۔ ابوطمحان قینی\nان کا نام نظلہ ہے، اسماء میں ان کا ذکر گزر چکا ہے۔"],[8777,"§۱۰۱۶۶ ۔ ابوطالب بن عبدالمطلب\nبن ہاشم بن عبد مناف .... ہاشمی۔ نبی کریم صلی اللہ علیہ وسلم کے چچا ہیں، آپ صلی اللہ علیہ وسلم کے والد کے سگے بھائی ہیں۔ ان کی والدہ فاطمہ بنت عمرو بن عائذ مخزومیہ ہیں، اپنی کنیت سے مشہور ہو گئے۔ ان کا نام عبد مناف ہے۔ بعض نے کہا: عمران، حاکم کا قول ہے: اکثر متقدمین کے نزدیک ان کا نام ہی ان کی کنیت ہے، نبی کریم صلی اللہ علیہ وسلم سے پینتیس(۳۵) سال قبل ولادت ہوئی۔ جب عبد المطلب کی وفات ہوئی تو انہوں نے محمد صلی اللہ علیہ وسلم کے بارے میں ابو طالب کو وصیت کی، انہوں نے آپ کی کفالت اور اچھی تربیت کی اور آپ کے ساتھ شام کی طرف سفر کیا، اس وقت وہ نوجوان تھے۔ جب آپ صلی اللہ علیہ وسلم مبعوث ہوئے تو آپ صلی اللہ علیہ وسلم کی نصرت کے لیے کھڑے ہوئے، اور آپ صلی اللہ علیہ وسلم سے آپ کے دشمنوں کو ہٹایا، اور آپ کی کئی مرتبہ تعریف کی، ان میں سے ایک ان کا یہ شعر ہے، جب اہل مکہ نے پانی طلب کیا اور ان پر بارش ہو گئی: \"وہ سفید چہرے والے ہیں جن کی وجہ سے بادلوں سے پانی مانگا جاتا ہے وہ یتیموں کا رکھوالا اور بیواؤں کا محافظ ہے۔\" ایک شعر یہ ہے: \"اللہ نے اپنے نام سے ان کا نام علیحدہ کیا ہے، عرش والا محمود ہے اور یہ محمد ہے۔\" ابن عیینہ کا قول بحوالہ علی بن زید ہے: میں نے اس شعر سے بہتر نہیں سنا۔ احمد نے حبہ غزنی کے طریق سے نقل کیا ہے، فرماتے ہیں: میں نے سیدنا علی رضی اللہ عنہ کو منبر پر ہنستے دیکھا حتی کہ ان کی داڑھیں نظر آنے لگیں۔ پھر ابو طالب کا قول ذکر کیا کہ وہ ہمارے پاس آئے اور میں نبی کریم صلی اللہ علیہ وسلم کے ساتھ بطن نخلہ میں نماز پڑھ رہا تھا، انہوں نے آپ صلی اللہ علیہ وسلم سے کہا: آپ دونوں کیا کر رہے ہیں؟ آپ صلی اللہ علیہ وسلم نے انہیں اسلام کی دعوت دی۔ انہوں نے کہا: جو آپ کہہ رہے ہیں اس میں حرج نہیں لیکن اللہ کی قسم! میری کمر ٹوٹ جائے گی۔ بخاری نے تاریخ میں طلحہ بن یحیی کے طریق سے بحوالہ عقیل بن ابو طالب روایت کیا ہے، فرماتے ہیں: قریش نے ابو طالب سے کہا: تیرے اس بھتیجے نے ہمیں ایذا دی ہے۔ پھر قصہ ذکر کیا۔ فرماتے ہیں: یا عقیل میرے پاس محمد کو لے آؤ۔ فرماتے ہیں: میں آپ صلی اللہ علیہ وسلم کو لے کر دوپہر کے وقت آیا، انہوں نے کہا: تیرے یہ چچا زاد دعوی کرتے ہیں کہ تم انہیں ایذاء دیتے ہو۔ انہیں تکلیف دینے سے رُک جاؤ۔ آپ صلی اللہ علیہ وسلم نے فرمایا: \"کیا تم اس سورج کو دیکھ رہے ہو؟ یہ آ جائے تو پھر بھی اسے چھوڑنے کا نہیں۔\" تو اس پر ابو طالب نے فوراً کہا: اللہ کی قسم! میرے بھتیجے نے کبھی جھوٹ نہیں بولا۔(1) عبد الرزاق کا قول ہے: ہم سے سفیان نے بحوالہ حبیب بن ابو ثابت جنہوں نے ابن عباس رضی اللہ عنہما سے اللہ تعالیٰ کے قول کے بارے میں سنا: ﴿وہ اس سے دور کرتے اور خود اس سے رکتے ہیں۔﴾(2) یہ آیت ابو طالب کے بارے میں نازل ہوئی، وہ نبی کریم صلی اللہ علیہ وسلم سے ایذاء کو روکتے اور خود اس چیز سے رُکتے جسے لے کر نبی کریم صلی اللہ علیہ وسلم آئے۔ ابن عدی نے یحیم بکاء کے طریق سے بحوالہ انس نقل کیا ہے، فرماتے ہیں: ابو طالب بیمار ہوئے تو نبی کریم صلی اللہ علیہ وسلم نے ان کی عیادت کی۔ انہوں نے کہا: اے میرے بھتیجے! اپنے رب سے دعا کرو جس نے تمہیں بھیجا ہے کہ مجھے عافیت دے۔ آپ صلی اللہ علیہ وسلم نے فرمایا: \"اے اللہ! میرے چچا کو شفا دے۔\" تو وہ کھڑے ہو گئے گویا رسیوں سے آزاد ہوئے ہوں۔ انہوں نے کہا: اے بھتیجے! تیرا رب تیری بات مانتا ہے۔ آپ صلی اللہ علیہ وسلم نے فرمایا: \"چچا جان! آپ اگر اس کی اطاعت کریں تو آپ کی بات بھی ضرور مانے گا\"۔(3) مغازی میں یونس بن بکیر کی زیادات میں بحوالہ ابو سفر مروی ہے، فرماتے ہیں: ابو طالب نے نبی کریم صلی اللہ علیہ وسلم کی طرف پیغام بھیجا کہ مجھے اپنی جنت کے انگور کھلائے، تو سیدنا ابو بکر رضی اللہ عنہ نے فرمایا: اللہ تعالیٰ نے اسے کافروں پر حرام کر دیا ہے، اور رافضہ کا قول لیا ہے کہ وہ مسلمان فوت ہوئے، انہوں نے اس بات کو لیا ہے جو ان کی طرف منسوب ہے: \"آپ نے مجھے دعوت دی اور میں جانتا ہوں کہ آپ سچے ہیں۔ آپ صلی اللہ علیہ وسلم نے سچ کہا، آپ اس سے پہلے امانت دار تھے، میں جانتا ہوں کہ محمد صلی اللہ علیہ وسلم کا دین دنیا کے تمام ادیان سے بہتر ہے۔\" ابن عساکر رحمہ اللہ نے ترجمے کے شروع میں فرمایا: بعض کا قول ہے کہ وہ اسلام لائے اور ان کا اسلام صحیح نہیں۔ میں بعض شیعہ کی تصانیف سے واقف ہوں کہ انہوں نے ابو طالب کا اسلام لانا ثابت کیا ہے۔ اس میں سے وہ ہے جسے یونس بن بکیر کے طریق سے بحوالہ ابن عباس رضی اللہ عنہما روایت کیا گیا ہے، فرماتے ہیں: رسول اللہ صلی اللہ علیہ وسلم ابو طالب کے پاس ان کے مرض میں آئے تو ان سے کہا: \"اے چچا! کلمہ لا الہ الا اللہ کہہ دیجئے، تاکہ قیامت والے دن میں آپ کی شفاعت کر سکوں\"۔(4) فرماتے ہیں: اے بھتیجے! اللہ کی قسم! اگر مجھ پر اور میرے اہل پر میرے بعد عار نہ ہوتی کہ وہ کہیں گے کہ میں نے موت کی گھبراہٹ میں یہ کلمہ کہا تو میں ضرور کہہ دیتا۔ تو ان کے ہونٹ حرکت کرتے ہوئے دکھائی دیئے۔ تو سیدنا عباس رضی اللہ عنہ ان کی طرف جھکے اور ان کی بات سنی۔ پھر اپنا سر ان سے اٹھایا اور کہا: انہوں نے اللہ کی قسم وہ کلمہ کہا ہے جس کا آپ نے ان سے سوال کیا تھا۔ اسحاق بن عیسیٰ ہاشمی کے طریق سے بحوالہ ان کے والد مروی ہے میں نے مہاجر مولی بنو نوفل کو فرماتے ہوئے سنا فرماتے ہیں: میں نے ابو رافع کو فرماتے ہوئے سنا، میں نے ابو طالب کو فرماتے ہوئے سنا: میں نے اپنے بھتیجے محمد بن عبد اللہ کو فرماتے ہوئے سنا کہ انہیں ان کے رب نے صلہ رحمی کے ساتھ بھیجا ہے اور یہ کہ ایک اللہ کی عبادت کی جائے اس کے ساتھ کسی اور کی عبادت نہ کی جائے، اور محمد سب سے بڑے سچے اور امانت دار ہیں۔ ابن مبارک کے طریق سے بحوالہ ابو عامر ہوزنی مروی ہے کہ آپ صلی اللہ علیہ وسلم ابو طالب کے جنازے کے سامنے سے گزرے۔ اور آپ فرما رہے تھے: \"رشتہ داری تم سے جڑی رہے گی۔\"(5) جب سیدنا علی رضی اللہ عنہ مسلمان ہوئے تو ابو طالب نے ان سے کہا: اپنے چچا زاد کا ساتھ نہ چھوڑنا۔ عمران بن حصین سے مروی ہے کہ ابو طالب نے جعفر بن ابی طالب سے کہا: جب وہ اسلام لا چکے تھے، اپنے عم زاد کا بازو چوموں چنانچہ سیدنا جعفر نے نبی کریم صلی اللہ علیہ وسلم کے ساتھ نماز پڑھی۔ سیدنا ابن عباس رضی اللہ عنہما نے فرمایا: صدیق اکبر ابو قحافہ کو ساتھ لے کر آئے اور انتہائی سن رسیدہ بزرگ تھے جن کی نظر بھی جاتی رہی تھی۔ رسول اللہ صلی اللہ علیہ وسلم نے دیکھتے ہی فرمایا: \"بوڑھے میاں کو کیوں تکلیف دی میں خود ہی ان کے پاس آ جاتا۔\"(6) صدیق اکبر رضی اللہ عنہ نے عرض کی: میں چاہتا ہوں اللہ تعالیٰ انہیں اجر عطا فرمائے۔ اس ذات کی قسم جس نے آپ کو حق دے کر بھیجا ہے، اگر آپ کے چچا ابو طالب اسلام لے آتے تو مجھے اپنے والد کی نسبت ان کے اسلام لانے سے زیادہ خوشی ہوتی کیونکہ اس سے آپ کو مسرت ہوئی تھی۔ ان احادیث کی سندیں بے حد کمزور ہیں۔ آخری حدیث میں ابو طالب کے مسلمان ہونے کا ثبوت مراد نہیں، چنانچہ عمر بن شبہ نے کتاب مکہ میں، ابو یعلی، ابو بشر اور سمویہ نے اپنے فوائد میں بحوالہ سیدنا انس رضی اللہ عنہ روایت کی ہے جس میں ابو قحافہ کے اسلام لانے کا واقعہ ہے جب انہوں نے بیعت کے لیے ہاتھ بڑھایا تو ابو بکر صدیق رو پڑے، نبی کریم صلی اللہ علیہ وسلم نے فرمایا: کیا بات ہے؟ عرض کی:(7) اگر آپ کے چچا کا ہاتھ ان کی جگہ ہوتا اور وہ اسلام لے آتے تو اللہ تعالیٰ آپ کو مسرت بخشا یہ مجھے ان کے اسلام لانے سے زیادہ پسند ہوتا۔ اس کی سند صحیح ہے۔ حاکم نے اسی سند سے نقل کیا ہے کہ شیخین (بخاری و مسلم) کی شرط پر صحیح ہے۔ بالفرض اگر یہ ثابت بھی ہو جائے تو صحیح حدیث اس سے ٹکرا رہی ہے۔ پہلی حدیث صحیحین میں بطریق زہری مروی ہے کہ نبی کریم صلی اللہ علیہ وسلم ابو طالب کی وفات کے وقت ان کے پاس تشریف لے گئے۔ وہاں ابو جہل اور عبد اللہ بن ابی امیہ بھی تھا آپ نے فرمایا: چچا جان! لا الہ الا اللہ کہہ لیں تاکہ میں اللہ تعالیٰ کے سامنے آپ کی سفارش کر سکوں، تو ابو جہل اور عبد اللہ بن ابی امیہ بولا: ابو طالب! کیا تم عبد المطلب کے دین سے منہ پھیر رہے ہو؟ وہ دونوں مسلسل انہیں یہی بات کہتے رہے یہاں تک کہ انہوں نے آخری بات یہی کہی میں عبد المطلب کے دین پر ہوں۔ جس پر نبی صلی اللہ علیہ وسلم نے فرمایا: \"جب تک مجھے ممانعت نہیں ہو جاتی میں آپ کے لیے استغفار کرتا رہوں گا\"۔(8) جس پر یہ آیت نازل ہوئی: ﴿نبی اور ایمان والوں کے لیے اس بات کی گنجائش نہیں کہ وہ مشرکین کے لیے استغفار کریں۔﴾(9) اور یہ آیت نازل ہوئی: ﴿اے نبی! آپ جسے چاہیں ہدایت نہیں دے سکتے بلکہ اللہ جسے چاہتا ہے ہدایت سے نوازتا ہے۔﴾(10) یہی صحیح ہے جس سے اس روایت کی تردید ہو جاتی ہے جو ابن اسحاق نے ذکر کی ہے کیونکہ اگر انہوں نے کلمہ توحید کہا ہوتا تو اللہ تعالیٰ اپنے نبی صلی اللہ علیہ وسلم کو ان کے لیے استغفار کرنے سے نہ روکتا۔ یہ جواب اس شخص کے اعتراض کے زیادہ مناسب ہے جس کا کہنا ہے کہ عباس باوجودیکہ مسلمان تھے لیکن انہوں نے شہادت ادا نہیں کی، نا قابل توجہ ہے۔ مذکورہ رافضی نے اس بات کا جواب دیا ہے کہ وہ عبد المطلب کے دین پر ہیں کہ عبد المطلب بھی مسلمان تھے اور دلیل میں ایک مقطوع اثر پیش کیا جو جعفر صادق رحمہ اللہ سے منقول ہے جسے میں عنقریب ذکر کروں گا جو منقطع اور اس کے رجال (راویوں) کے ضعیف ہونے کی وجہ سے دلیل بننے سے قاصر ہے۔ رہی دوسری حدیث جس میں ابو طالب کی نبی صلی اللہ علیہ وسلم کی تصدیق کرنے کی گواہی ہے اس کا اور ابو طالب کے اشعار کا جواب یہ ہے کہ اس کی مثال ایسے ہے جیسے اللہ تعالیٰ نے قریش کے کافروں کا حال بیان کیا: \"انہوں نے اس کا انکار کیا جبکہ ان کے دل اس کا یقین رکھتے ہیں کہ یہی ظالم اور سرکش ہیں۔\"(11) ان کا کفر عناد و ضد کی وجہ سے تھا جو تکبر و نفرت سے پیدا ہوا، اس کی طرف ابو طالب نے اپنی اس بات سے اشارہ کیا ہے اگر قریش مجھے عار نہ دلائیں۔ رہی تیسری حدیث جو ہوزنی کا اثر ہے اور مرسل ہے، اس کے باوجود اس میں رشتہ داری آپ کو جوڑے رکھے گی۔ ان کے مسلمان ہونے کی کوئی بات نہیں بلکہ اس کے منافی بات موجود ہے وہ یہ کہ آپ ان کے جنازے کی طرف مخالف سمت سے آئے ورنہ آپ جنازے کے ساتھ چلتے اور خود نماز جنازہ پڑھاتے۔ اس سے زیادہ صحیح روایت میں ہے جو ابو داؤد اور نسائی نے نقل کی اور ابن خزیمہ نے اسے صحیح کہا ہے، بطریق ناجیہ بن کعب بحوالہ سیدنا علی رضی اللہ عنہ مروی ہے، فرمایا: جب ابو طالب کا انتقال ہوا میں نبی کریم صلی اللہ علیہ وسلم کے پاس آیا کہ آپ کا گمراہ چچا چل بسا ہے۔ آپ صلی اللہ علیہ وسلم نے فرمایا: جاؤ ان کی نعش دفن کر دو اور یہ کام ختم کرنے تک مجھ سے کوئی بات نہ کرنا۔ چنانچہ میں نے ایسا ہی کیا۔ جب واپس آیا تو آپ صلی اللہ علیہ وسلم نے مجھے کئی دعائیں دیں۔(12) مذکورہ رافضی نے ایک اور سند سے بواسطہ ناجیہ بن کعب بحوالہ سیدنا علی یہ روایت لفظ ضال (گمراہ) کے بغیر نقل کی ہے۔ رہی چوتھی اور پانچویں حدیث کہ ابو طالب نے اپنے بیٹوں کو نبی صلی اللہ علیہ وسلم کے اتباع کا حکم دیا اور خود اتباع نہ کرنا بجائے خود عناد و ضد ہے جو ان کی اچھی مدد اور آپ علیہ السلام کا دفاع اور آپ علیہ السلام کی وجہ سے اپنی قوم کی دشمنی مول لینے کا سبب ہے۔ رہی صدیق اکبر رضی اللہ عنہ کی بات کہ مجھے ابو طالب کے اسلام لانے سے زیادہ خوشی ہوتی، سے مراد یہ ہے کہ اگر وہ اسلام لے آتے۔ جس کی وضاحت ابن عمر رضی اللہ عنہما کی ایک روایت سے ہو جاتی ہے کہ فتح مکہ کے روز ابو بکر، ابو قحافہ کا ہاتھ تھامے آئے، رسول اللہ صلی اللہ علیہ وسلم نے ان کی پیرانہ سالی دیکھ کر فرمایا: \"میاں کو کیوں تکلیف دی میں خود ہی ان کے پاس آ جاتا\"۔ ابو بکر رضی اللہ عنہ نے فرمایا: \"میں چاہتا ہوں اللہ تعالیٰ انہیں اجر دے۔ اللہ کی قسم! اگر ابو طالب ایمان لے آتے تو مجھے اپنے والد کے اسلام سے زیادہ ان کے اسلام کی خوشی ہوتی\"۔ ابن اسحاق کا بیان ہے: فتح مکہ کی رات جب سیدنا عباس ابو سفیان کو لے کر آئے تو راہ میں سیدنا عمر رضی اللہ عنہ مل گئے، عباس رضی اللہ عنہ نے ان سے کہا: اگر یہ شخص بنی عدی کا ہوتا تو تم اس کے قتل سے خوش نہ ہوتے!؟ تو سیدنا عمر رضی اللہ عنہ نے ان سے فرمایا: میں تمہارے اسلام سے بنسبت خطاب کے اسلام کے زیادہ خوش ہوں، اگر اسلام لاتے۔ پھر رافضی نے بطریق راشد الحمانی روایت کی ہے کہ ابو عبد اللہ یعنی جعفر الصادق سے کسی نے جنتی لوگوں کے بارے میں پوچھا، انہوں نے فرمایا: انبیاء جنت میں، صلحاء جنت میں، اسباط (نواسے پوتے) جنت میں ہیں۔ سب لوگوں سے زیادہ عزت والے محمد صلی اللہ علیہ وسلم، حضرت آدم علیہ السلام اور ان کے بعد والے آباء و اجداد، آگے ہوں گے۔ یہ قسمیں اس کی باتیں کر رہی ہوں گی۔ عبد المطلب کا حشر اس عالم میں ہوگا کہ ان کے ساتھ انبیاء کا نور ہوگا اور بادشاہوں کا جمال ہوگا۔ ابو طالب انہی کی جماعت میں اٹھائے جائیں گے جب پیشی کے لیے روانہ ہوں گے اور جنتی اپنے ٹھکانوں میں اور جہنمی اپنے ویرانوں میں جا پہنچیں گے۔ ایک شعلہ بلند ہوگا جسے ہر دیکھنے والا بلا شک و شبہ آگ کا بادل سمجھے گا۔ اس وقت ہر مذہب کا وہ شخص حاضر ہوگا جسے رب کی معرفت تو ہوگی لیکن وہ اپنے نبی کو نہ جانتا ہوگا اور جو شخص اکیلا ہوگا، جن میں بوڑھے، بچے ہوں گے۔ ان سے کہا جائے گا رب تعالیٰ تمہیں اس آگ میں کود جانے کا حکم دیتا ہے تو جو کوئی اس میں کود پڑے گا وہ بلند جنتوں تک پہنچ جائے گا اور جو اڑا رہے گا وہ آگ کا بادل اسے اپنی لپیٹ میں لے لے گا۔ یہی روایت ابو بشر احمد بن ابراہیم بن یعلی بن اسد سے بحوالہ ابو صالح حمادی وہ اپنے والد سے بحوالہ اپنے دادا روایت کرتے ہیں کہ میں نے راشد حمانی کو فرماتے سنا۔ پھر اسے ذکر کیا۔ یہ غالی رافضیوں کا سلسلہ ہے۔ آخری حدیث مختلف طریق کے ذریعہ، بوڑھے آدمی، زمانہ فترت میں فوت ہونے والے، کوڑھی، اندھے بہرے پیدا ہونے والے، مجنون یا پاگل پیدا ہونے والے یا جس پر بالغ ہونے سے پہلے پاگل پنا طاری ہو جائے کے حق میں وارد ہوئی ہے۔ ان میں سے ہر ایک اپنی دلیل پیش کرے گا کہ اگر مجھے سمجھ بوجھ ہوتی یا میں یاد رکھتا تو ایمان لے آتا، تو ان کے لیے آگ بلند ہوگی اور ان سے کہا جائے گا: اس میں کود پڑو! جو اس میں داخل ہو جائے گا وہ اس کے لیے گلزار بن جائے گی اور جو رکا رہا اسے زبردستی داخل کیا جائے گا۔ یہ اس کا مطلب ہے جو اس قسم کی احادیث ہیں، جس کے طرق میں نے علیحدہ رسالے میں جمع کیے ہیں۔ ہم بھی یہی اُمید رکھتے ہیں کہ عبد المطلب اور ان کے گھرانے کے لوگ اس میں خوشی سے داخل ہو جائیں اور نجات حاصل کر لیں لیکن ابو طالب کے بارے میں اس کے خلاف حدیث آتی ہے۔ ایک تو یہ آیت براءت اور صحیحین کی حدیث عباس کہ انہوں نے نبی صلی اللہ علیہ وسلم سے کہا: آپ اپنے چچا ابو طالب کو کیا فائدہ پہنچائیں گے کیونکہ وہ آپ کی حفاظت کرتا اور آپ کے لیے لوگوں سے ناراض رہتا تھا۔ آپ صلی اللہ علیہ وسلم نے فرمایا: \"وہ پایاب آگ میں ہے اگر میں نہ ہوتا تو وہ جہنم کے سب سے نچلے طبقے میں ہوتا\"۔ یہ کفر پر مرنے والے شخص کا درجہ ہے اگر وہ توحید پر مرے ہوتے تو جہنم سے بالکل نجات یافتہ ہوتے۔ اس بارے میں صحیح احادیث اور کئی روایات موجود ہیں۔ مدینہ میں جب محمد بن عبد اللہ بن حسن نے خروج کیا تو منصور نے اس پر فخر کیا جس کے بارے میں ان کی خط و کتابت مشہور ہے۔ ان میں سے منصور ایک خط میں لکھتا ہے: جب نبی صلی اللہ علیہ وسلم مبعوث ہوئے تو ان کے چار چچے تھے جن میں سے دو آپ پر ایمان لائے، ان میں سے ایک میرا جد امجد تھا اور دو نے کفر کیا جن میں سے ایک تمہارا جد اعلیٰ تھا۔ عبد اللہ بن المعتز کا شعر ہے جس میں فاطمین کو مخاطب کرتے ہوئے کہتا ہے: \"تم لوگ ہمارے مقابلہ میں آپ صلی اللہ علیہ وسلم کی بیٹی کی اولاد ہو اور ہم آپ علیہ السلام کے مسلمان چچا کی اولاد میں سے ہیں\"۔ اسی طرح رافضی نے ابو طالب کی وفات کا واقعہ بطریق علی بن محمد بن متسیم نقل کیا ہے میں نے اپنے والد سے انہوں نے اپنے دادا سے کہ میں نے سیدنا علی بن ابی طالب رضی اللہ عنہ کو فرماتے سنا: ابو طالب تمام حالات میں عبد المطلب کے پیروکار رہے یہاں تک کہ دنیا سے انہی کے مذہب پر رہتے ہوئے رخصت ہوئے۔ اور مجھے وصیت کی تھی کہ مجھے ان کی قبر میں دفن کرنا۔ میں نے رسول اللہ صلی اللہ علیہ وسلم کو بتایا، آپ نے فرمایا: \"جاؤ! انہیں دفن کر آؤ\"۔ میں آیا انہیں غسل دیا کفنانے کے بعد انہیں معجون لے آیا، عبد المطلب کی قبر کھودی تو وہ قبلہ کی جانب رخ کیے ہوئے تھے چنانچہ انہیں بھی ان کے ساتھ دفن کر دیا۔ متیم کہتے ہیں: \"سیدنا علی رضی اللہ عنہ اور ان کے آباء و اجداد میں سے کسی نے شرک نہیں کیا، صرف اللہ کی عبادت کی اور مرتے دم تک اسی پر قائم رہے\"۔ یہی روایت ابو بشر سے منقول ہے جس کا ذکر ہو چکا ہے وہ ابو بردہ مسلمی سے وہ حسن بن ما شاء اللہ سے وہ اپنے والد سے وہ علی بن محمد بن مقیم سے، یہ غالی شیعوں کا سلسلہ روایت ہے جس پر خوش ہونے کی ضرورت نہیں۔ اس سے زیادہ صحیح جو پہلے گزر چکا ہے وہ اس سے ٹکرا رہا ہے۔ وہی معتبر ہے پھر اس رافضی نے اللہ تعالیٰ کے ارشاد \"پھر جن لوگوں نے نبی پر ایمان لاکر ان کی مدد و نصرت کی اور جو نور ان پر نازل ہوا (یعنی قرآن) اس کی پیروی کی حقیقت میں یہی لوگ کامیاب ہیں\"(13) کو بطور دلیل پیش کیا ہے کہ ابو طالب نے جیسا کہ مشہور ہے آپ کی مدد کی، آپ کی وجہ سے قریش کی دشمنی مول لی، جس کا کوئی مورخ انکار نہیں کرتا۔ لہذا وہ بھی فلاح پانے والوں میں سے ہوں گے۔ یہ ان کے علم کی رسائی ہے۔ ہم مانتے ہیں کہ خواجہ ابو طالب نے آپ کی مدد کی اور اس میں بہت ہمت کوشش کی لیکن انہوں نے آپ پر نازل ہونے والے نور کا اتباع نہیں کیا جو اللہ تعالیٰ کی کتاب عزیز ہے جو توحید کی دعوت دیتی ہے۔ فلاح و کامیابی اس وقت تک حاصل نہیں ہو سکتی جب تک اس پر تمام صفات مرتب نہیں ہوتیں۔ مرزبانی لکھتے ہیں: ابو طالب کا انتقال بعثت کے دسویں(۱۰) سال ہوا، اس وقت ان کی عمر اسی(۸۰) سے زائد تھی۔ ابن سعد بحوالہ واقدی بیان کرتے ہیں: وہ سال کی پندرہ شوال میں فوت ہوئے۔ ہمیں ابو طالب کی وہ روایت جو انہوں نے نبی صلی اللہ علیہ وسلم سے کی ہے جسے خطیب نے \"روایۃ الآباء عن الابناء\" نامی کتاب میں بطریق احمد بن حسن (جو دھین سے مشہور ہیں) نقل کی ہے۔ حسین بن علی کہتے ہیں: میں نے ابو طالب کو فرماتے سنا: مجھ سے میرے بھتیجے محمد (صلی اللہ علیہ وسلم) نے بیان کیا۔ جو اللہ کی قسم سچا انسان ہے، میں نے اس سے پوچھا: اللہ تعالیٰ نے تمہیں کیا دے کر مبعوث کیا ہے؟ اس نے کہا: \"صلہ رحمی، نماز قائم کرنے اور زکوٰۃ ادا کرنے کے ساتھ\"۔ خطیب لکھتے ہیں: میں نے یہ سند صرف اسی شیخ سے لکھی ہے اور دھین المقرئی بڑی عجیب و غریب اور زیادہ تر منکر روایات نقل کرتا ہے۔ نیز خطیب فرماتے ہیں: ابو نعیم نے ہمیں بتایا کہ ابو رافع فرماتے ہیں میں نے ابو طالب کو فرماتے سنا: مجھ سے محمد (علیہ السلام) نے بیان کیا کہ اللہ تعالیٰ نے اسے صلہ رحمی، صرف اللہ تعالیٰ کی عبادت کرنے اس کے ساتھ کسی کی پکار نہ کرنے کے ساتھ بھیجا ہے، اور محمد میرے نزدیک بے حد سچا اور امین ہے۔ خطیب لکھتے ہیں: علم حدیث کے ناقلین اس حدیث کو ثابت نہیں کرتے اور اس کی اسناد میں بے شمار مجہول راوی ہیں۔ اور جعفر بن عبد الواحد قصہ گو بے حد کمزور راوی ہے۔ ابن سعد طبقات میں بحوالہ عمرو بن سعید روایت کرتے ہیں کہ ابو طالب نے فرمایا: میں اپنے بھتیجے کے ساتھ ذو المجاز میں تھا مجھے سخت پیاس لگی، میں نے اس سے شکایت کی حالانکہ اس کے پاس کچھ بھی نہ تھا۔ وہ جھک کر نیچے اترا زمین کی طرف اپنی لاٹھی کی اور پانی لے آیا، کہنے لگا: چچا جان! ہیں! میں نے پی لیا۔ اس سلسلے میں وہ احادیث جو اس رافضی نے ذکر نہیں کی ہیں وہ \"تمام\" نے اپنے فوائد میں نقل کی ہیں۔ عبد اللہ بن عمر سے مرفوع روایت کرتے ہیں۔ جب قیامت کا دن ہوگا تو میں اپنے والدین، چچا ابو طالب اور جاہلیت میں اپنے ایک بھائی کے لیے شفاعت کروں گا۔ \"تمام\" فرماتے ہیں: ولید منکر احادیث نقل کرتا ہے۔ حافظ ابن عساکر کا قول ہے جو حدیث مسلم نے حدیث ابی سعید خدری سے نقل کی وہ صحیح ہے کہ رسول اللہ صلی اللہ علیہ وسلم کے سامنے ابو طالب کا تذکرہ ہوا آپ نے فرمایا: \"میری شفاعت سے انہیں فائدہ ہوگا۔ انہیں جہنم کی پایاب (پاؤں تک پہنچنے والی) آگ میں عذاب ہوگا جس سے ان کا دماغ کھولے گا\"۔","",{"fn":"(1) دلائل النبوۃ (۱۸۷/۲)\n(2) سورۃ الانعام (۲۶)\n(3) مستدرک حاکم (۵۴۲/۱) مجمع الزوائد (۳۳۰/۲)\n(4) بخاری (۴۷۷۲) مسلم (۳۹) بدایہ والنھایہ (۱۲۵/۳) کنز العمال (۳۴۴۳)\n(5) المعجم الکبیر (۲۹/۹) مجمع الزوائد (۱۷۴/۶)\n(6) مجمع الزوائد (۱۴۱/۷)\n(7) بخاری کتاب الجنائز باب اذا قال المشرک عند الموت (۱۳۶۰)\n(8) مسلم کتاب الایمان باب الدلیل علی صحۃ اسلام .... (۱۳۱)\n(9) سورۃ التوبۃ (۱۱۳)\n(10) سورۃ القصص (۵۶)\n(11) سورۃ النمل (۱۴)\n(12) ابوداؤد کتاب الجنائز باب الرجل یموت له قرابۃ مشرک (۳۲۱۴) نسائی کتاب الطہارۃ باب الغسل من موارۃ المشرک (۱۹۰) مسند احمد (۱۳۰/۱)\n(13) سورۃ الاعراف (۱۵۷)"}],[8778,"§۱۰۱۶۷ ۔ ابوطرفہ کندی(1)\nتابعی۔ ان کی حدیث مرسل ہے، بعض نے اس کی وجہ سے ان کا ذکر صحابہ رضی اللہ عنہم میں کیا ہے۔ مستغفری نے بقیہ کے طریق سے ان کا ذکر کیا ہے کہ مجھ سے ولید بن کامل نے بحوالہ ابو طرفہ کندی روایت کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جس کی صحت اس کے مرض پر غالب آ جائے تو وہ دوا نہ کرے\"۔(2)","",{"fn":"(1) اسد الغابہ (۶۰۲۶) تجرید (۱۸۰/۲)\n(2) اسد الغابہ (۱۸/۵)"}],[8779,"§۱۰۱۶۸ ۔ ابوطریف\nمولی عبد الرحمن بن طریف، تابعی ہیں۔ ان کی حدیث مرسل ہے۔ اس وجہ سے بعض نے صحابہ رضی اللہ عنہم میں ان کا ذکر کیا ہے۔ ابو داؤد نے کتاب القدر میں عمر بن عبد اللہ مولی عفرہ کے طریق سے بحوالہ ابو طریف نقل کیا ہے، فرماتے ہیں: ہمیں یہ بات معلوم ہوئی ہے کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا: \"میں نے اپنے رب سے انسان کی اولاد میں سے لہو میں مشغول لوگوں کے بارے سوال کیا\"۔"],[8780,"§۱۰۱۶۹ ۔ ابوظبیان\nان کا نام عبد اللہ بن حارث بن کبیر عامدی ہے، اسماء میں ان کا ذکر گزر چکا ہے۔"],[8781,"§۱۰۱۷۰ ۔ ابوظبیہ(1)(2)\nنبی کریم صلی اللہ علیہ وسلم نے انہیں دودھیا جانور دیا تھا۔ ابن مندہ کا قول ہے: ابو سلامہ نے بحوالہ ابو سلام ان سے حدیث روایت کی ہے، اسے بحوالہ عبد الرحمن نقل کیا ہے، فرماتے ہیں: بحوالہ ابو سلمہ، اسے ابو احمد حاکم نے ابو اسامہ کے طریق سے موصولاً نقل کیا ہے، اس کے الفاظ بحوالہ ابو سلام مولی قریش مروی ہیں، فرماتے ہیں: میں کوفہ میں آیا، میں جمعہ کے دن مجلس عظیم میں بیٹھا پھر ایک شخص آیا، اس نے لوگوں کو سلام کیا، اور کہنے لگا: میں ابو ظبیہ ہوں، رسول اللہ صلی اللہ علیہ وسلم نے مجھے دودھیا جانور دیا تھا آپ مجھے بتاتے تھے کہ میں اس کے بعد ضرورت مند ہو جاؤں گا، مجھے وظیفہ ملتا تھا۔ انہیں مغیرہ بن شعبہ کے بارے میں خوف ہوا، میں آپ سے جمعہ سے لے کر جمعہ تک سوال کرتا ہوں، ان سے لوگوں نے کہا: اے ابو ظبیہ! آپ ہم سے ایسی حدیث بیان کریں جسے آپ نے رسول اللہ صلی اللہ علیہ وسلم سے سنا ہے۔ انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"واہ واہ! پانچ چیزیں میزان میں وزن رکھتی ہیں۔ سبحان اللہ، الحمد للہ، لا الہ الا اللہ، اللہ اکبر، مومن جس کی صالح اولاد فوت ہو جائے تو وہ ثواب کی امید رکھے\"۔(3) فرماتے ہیں: اسے ولید بن مسلم بحوالہ ابو سلمی جو رسول اللہ صلی اللہ علیہ وسلم کی بکریاں چرانے والے ہیں روایت کیا ہے، فرماتے ہیں: میں ان سے کوفہ کی مسجد میں ملا، انہوں نے ذکر کیا کہ نبی علیہ السلام نے ان سے فرمایا: \"تم میرے بعد زندہ رہو گے اور تم سے سوال کیا جائے گا۔\" پھر اسی طرح حدیث نقل کی۔ ولید کی روایت زیادہ راجح ہے، کیونکہ عبد الرحمن بن یزید جن سے ابو اسامہ نے روایت کی ضعیف ہیں، وہ شامی ہیں جو کوفہ میں آئے، پھر انہوں نے ان سے حدیث بیان کی، لوگوں نے ان کا نام پوچھا، انہوں نے کہا: عبد الرحمن بن یزید، انہوں نے گمان کیا کہ وہ ابن جابر ہیں اور وہ ثقہ راوی ہیں، تو انہوں نے ان سے حدیث نقل کی اور اسے جابر کی طرف منسوب کر دیا۔ کوفہ کی ایک جماعت کے ساتھ یہ پیش آیا۔ ان میں ابو اسامہ شامل ہیں وہ ابن جابر نہیں۔ وہ ابن تمیم ہیں۔ ان کا اور ان کے بیٹے کا نام ابن جابر اور ان کے بیٹے جیسا ہے۔ ان کی نسبت بھی ایک جیسی ہے، عبد الرحمن بن یزید بن جابر کوفہ کبھی نہیں آئے، جب یہ ثابت ہو گیا۔ تو عبد الرحمن بن یزید بن جابر، جو معتبر ہیں، کا قول بحوالہ ابو سلمہ، جو چرواہے ہیں، یہ عبد الرحمن بن یزید بن تمیم کے قول سے زیادہ صحیح ہے جو ضعیف ہیں۔ بحوالہ ابو ظبیہ، عبد اللہ بن علاء بن زبیر جو ثقات میں سے ہیں، وہ عبد الرحمن بن یزید بن جابر کے اس قول کی وجہ سے موافق ہیں۔ میں نے احتمال کی وجہ سے اس قسم میں ان کا ذکر کیا۔","",{"fn":"(1) اسد الغابہ (۶۰۳۴) الاستیعاب (۳۱۰۰) تجرید (۱۸۱/۲)\n(2) جامع المسانید والسنن (۲۳۹/۱۴) اسد الغابہ (۲۲/۵)\n(3) المعجم الکبیر (۸۷۳/۲۲) الآحاد والمثانی (۳۴۷/۱) المستدرک (۵۱۱/۱) جامع المسانید والسنن (۲۳۹/۱۴) مسند جامع (۲۷۰/۱۶)"}],[8782,"§۱۰۱۷۱ ۔ ابوظبیہ کلاعی\nابو بشر دولابی نے صحابہ رضی اللہ عنہم میں ان کا ذکر کیا ہے، کیونکہ انہوں نے نبی کریم صلی اللہ علیہ وسلم کا زمانہ پایا، اور ابو مغیرہ کے طریق سے بحوالہ ابو ظبیہ سلفی کلاعی ذکر کیا ہے۔ فرماتے ہیں: جمعہ کے دن سیدنا عمر رضی اللہ عنہ نے جابیہ کے مقام پر ہمیں خطبہ دیا، اور یہ آیت پڑھی: ﴿جب آسمان پھٹ جائے گا۔﴾(1) پھر وہ منبر سے اترے اور سجدہ کیا، لوگوں نے ان کے ساتھ سجدہ کیا۔ اسی طرح احمد نے بحوالہ ابو مغیرہ عبد القدوس بن حجاج نقل کیا ہے، اس کے رجال ثقات ہیں، لیکن احمد رحمہ اللہ کے نزدیک بے نقط ہے، اس طرف اشارہ کیا کہ اس میں لفظی غلطی ہے، صحیح نقطے کے ساتھ ہے۔ عباس بن محمد دوری نے فرمایا: میں نے ابن معین کو فرماتے ہوئے سنا: ابو ظبیہ کلاعی معاذ بن جبل کے ساتھی ہیں، ابن خراش کا قول ہے: مجھے امید ہے کہ انہوں نے معاذ سے سنا، ابو یعلی نے اعمش کے طریق سے بحوالہ شہر بن حوشب نقل کیا ہے، فرماتے ہیں: میں مسجد میں داخل ہوا تو ابو امامہ بیٹھے ہوئے تھے، میں ان کے پاس بیٹھ گیا تو شیخ ابو ظبیہ آئے، لوگ سوائے صحابی رسول صلی اللہ علیہ وسلم کے کسی کو ان کے برابر نہیں سمجھتے تھے۔ ابو ظبیہ نے بھی عمر بن خطاب سے روایت کیا، اور جابیہ میں سیدنا عمر رضی اللہ عنہ کے خطبہ کے وقت موجود تھے۔ بحوالہ معاذ، مقداد، عمرو بن العاص، ان کے بیٹے عبد اللہ بن عمرو بن عبسہ وغیرہ۔ ان سے تابعین میں سے ثابت بنانی، شہر بن حوشب، شریح بن عبید وغیرہ نے روایت کی۔ ابو داؤد، نسائی، ابن ماجہ، بخاری رحمہ اللہ کی الادب المفرد میں ان کی حدیث صحابہ رضی اللہ عنہم کے حوالے سے مروی ہے۔ ابن ابو حاتم رحمہ اللہ فرماتے ہیں: میں نے ابو زرعہ سے ابو ظبیہ کے نام کے بارے میں پوچھا، انہوں نے کہا: میں کسی کو نہیں جانتا جو ان کا نام بتائے۔ ابو زرعہ دمشقی نے اہل دمشق کے تابعین کے طبقہ علیا میں ان کا ذکر کیا ہے۔","",{"fn":"(1) سورہ انشقاق آیہ (۹)"}]])